// ── harness ────────────────────────────────────────────────────────────────────

let failures = 0
let passes = 0
let group = ''
const sectionsRun: string[] = []

/**
 * Empty suites must not print ALL GATES PASSED (SOL-46).
 *
 * MIN_GATE_PASSES is the assertion floor: the assertion count must not
 * fall. It is a monotonic ratchet. It rises to meet the suite whenever assertions are added, and it
 * never falls. An assertion may be retired only after its replacement passes at an earlier internal
 * boundary while the subject still exists, and only with a named successor recorded in
 * the gate ledger. Anything that appears to need a lower floor is a governance
 * question for the tester; it is not decided here. The one sanctioned fall so far is Step 4.5's
 * retirement of the CLI's own assertions (3572 → 3198, gate_ledger.md §5m.5b).
 */
const MIN_GATE_SECTIONS = 35
const MIN_GATE_PASSES = 4182

/**
 * A gate's temp-folder cleanup. A Windows scanner can hold a folder it has just emptied for longer
 * than `rmSync`'s retries; a folder left behind is the OS's to clear and never ends or fails the run.
 */
function rmTemp(dir: string): void {
  try {
    fs.rmSync(dir, { recursive: true, force: true, maxRetries: 20, retryDelay: 150 })
  } catch (err) {
    console.log(`  note  temp folder left behind: ${dir} (${(err as NodeJS.ErrnoException).code ?? 'error'})`)
  }
}

function section(name: string): void {
  group = name
  sectionsRun.push(name)
  console.log(`\n=== ${name} ===`)
}

function check(name: string, ok: boolean, detail?: string): void {
  if (ok) {
    passes++
    console.log(`  PASS  ${name}`)
  } else {
    failures++
    console.log(`  FAIL  ${name}${detail ? `\n        ${detail}` : ''} [${group}]`)
  }
}

function eq<T>(name: string, actual: T, expected: T): void {
  const a = JSON.stringify(actual)
  const e = JSON.stringify(expected)
  check(name, a === e, a === e ? undefined : `expected ${e}\n        actual   ${a}`)
}

/** Replay a run's output through the panel's collapser, one line at a time as it arrives. */
/** A started Translate configuration with nothing engine-specific in it, for reducer fixtures. */
function literalTranslateConfig(outputPath: string): RunConfigurationSummary {
  return {
    provider: 'gemini',
    model: DEFAULT_MODEL_ID,
    inputPaths: ['C:/in.srt'],
    outputPath,
    targetLanguage: 'Hebrew',
    serviceTier: 'standard',
    credentialSlotCount: 1,
    hasDescription: false,
    hasSystemPrompt: false,
    hasVideo: false,
    hasAudio: false,
    showTokenStats: false,
    writeTokenReport: false,
    progressLog: false,
    thoughtsLog: false,
    hebrewSpeakerRepair: false,
    hebrewMethodB: false,
    hebrewC1Spanish: false,
    hebrewC1Portuguese: false
  }
}

function feedLog(lines: string[]): LogRow[] {
  let rows: LogRow[] = []
  for (const l of lines) rows = appendLogLine(rows, l)
  return rows
}

