section('C16/C17/C22/C22b + Steps 6/7/9 — argv')

/** A translation request's batch JSON: its last text part (with Context ON the D15-3R block comes first). */
function batchItems(req: ProviderRequest): Array<{ index: string; text: string }> {
  const texts = req.parts.filter((p): p is { text: string } => 'text' in p)
  return JSON.parse(texts[texts.length - 1].text) as Array<{ index: string; text: string }>
}

function baseArgs(over: Partial<TranslateArgs> = {}): TranslateArgs {
  return {
    inputFile: 'C:/in.srt',
    sourceLang: 'auto',
    targetLang: 'he',
    model: 'gemini-3.1-flash-lite',
    apiKeys: ['KEY-A'],
    batchSize: 100,
    batchContext: true,
    customGenerationParams: false,
    temperature: 1,
    topP: 0.95,
    topK: null,
    thinkingLevel: 'low',
    thinkingBudget: 512,
    serviceTier: 'standard',
    paidQuota: false,
    disableStreaming: false,
    writeTokenReport: false,
    progressLog: false,
    thoughtsLog: false,
    ...over
  }
}

setSettings({ apiKeys: ['KEY-A'], apiKeyValid: [true], apiKeyTiers: ['free'] })

{
  // Step 7: thinking flags must match what the engine will actually honour.
  eq('2.5 Flash floor is 1, not 0', modelCapabilities('gemini-2.5-flash').thinkingBudgetMin, 1)
  eq('2.5 Pro floor is 128', modelCapabilities('gemini-2.5-pro').thinkingBudgetMin, 128)
  eq('thinking cannot be switched off on Flash either', modelCapabilities('gemini-2.5-flash').canDisableThinking, false)

  const dedicatedCaps = modelCapabilities('gemini-3.5-transcribe')
  eq('dedicated transcribe model has no thinking control', dedicatedCaps.thinking, 'none')
  eq('dedicated transcribe model can still be selected for transcription', dedicatedCaps.supportsTranscription, true)
  const flash37 = modelCapabilities('gemini-3.7-flash').acceptedThinkingLevels
  check('3.7 Flash offers Default', flash37.includes('default'))
  check('3.7 Flash does not offer Minimal', !flash37.includes('minimal'))
  check('3.7 Flash offers Low/Medium/High', flash37.includes('low') && flash37.includes('medium') && flash37.includes('high'))

  const pro3id = modelCapabilities('gemini-3-pro').acceptedThinkingLevels
  check('3 Pro offers Default', pro3id.includes('default'))
  check('3 Pro does not offer Medium', !pro3id.includes('medium'))
  check('3 Pro does not offer Minimal', !pro3id.includes('minimal'))

  eq(
    'unknown 3.x falls back to Default/Low/High',
    modelCapabilities('gemini-3.9-ultra').acceptedThinkingLevels,
    ['default', 'low', 'high']
  )
  eq(
    '3 Pro Image is Default + High',
    modelCapabilities('gemini-3-pro-image').acceptedThinkingLevels,
    ['default', 'high']
  )
  eq(
    '3 Pro Image with the API prefix is the same model',
    modelCapabilities('models/gemini-3-pro-image').acceptedThinkingLevels,
    ['default', 'high']
  )
  eq(
    '3 Pro Image preview keeps the documented set',
    modelCapabilities('gemini-3-pro-image-preview').acceptedThinkingLevels,
    ['default', 'high']
  )
  eq('3 Pro Image coerces an unsupported level to High', effectiveThinkingLevel('gemini-3-pro-image', 'medium'), 'high')
  eq(
    '3.1 Flash Image is Default + Minimal + High',
    modelCapabilities('gemini-3.1-flash-image').acceptedThinkingLevels,
    ['default', 'minimal', 'high']
  )
  eq(
    '3.1 Flash-Lite Image is the same pair',
    modelCapabilities('gemini-3.1-flash-lite-image').acceptedThinkingLevels,
    ['default', 'minimal', 'high']
  )
  eq(
    'an unknown flash-image id falls back rather than inheriting Minimal',
    modelCapabilities('gemini-3.9-flash-image').acceptedThinkingLevels,
    ['default', 'low', 'high']
  )
  eq(
    'an unknown pro-image id falls back rather than High-only',
    modelCapabilities('gemini-3.9-pro-image').acceptedThinkingLevels,
    ['default', 'low', 'high']
  )
  eq(
    'stored Low stays Low on an unknown image model',
    effectiveThinkingLevel('gemini-3.9-flash-image', 'low'),
    'low'
  )
  eq(
    'an image id does not inherit its text-model cousin’s full set',
    modelCapabilities('gemini-3.5-flash-image').acceptedThinkingLevels,
    ['default', 'low', 'high']
  )

  eq(
    '3.1 Pro does not offer Minimal',
    modelCapabilities('gemini-3.1-pro').acceptedThinkingLevels.includes('minimal'),
    false
  )
  eq(
    '3.5 Flash-Lite keeps all four discrete levels',
    modelCapabilities('gemini-3.5-flash-lite').acceptedThinkingLevels,
    ['default', 'minimal', 'low', 'medium', 'high']
  )
  eq(
    'undocumented 3.6 Flash-Lite falls back rather than inheriting 3.6 Flash',
    modelCapabilities('gemini-3.6-flash-lite').acceptedThinkingLevels,
    ['default', 'low', 'high']
  )

  check('THINKING_LEVELS has a Default entry', THINKING_LEVELS.some((o) => o.value === 'default' && o.label === 'Default'))
  check('THINKING_LEVELS has no Disabled entry', !THINKING_LEVELS.some((o) => o.value === 'disabled'))
  check('Low is not labelled as Default', !THINKING_LEVELS.some((o) => o.value === 'low' && /default/i.test(o.label)))
  eq(
    'dropdown hides unsupported levels',
    thinkingLevelsForModel(['default', 'low', 'high']).map((o) => o.value),
    ['default', 'low', 'high']
  )
  check(
    'dropdown keeps an orphan current value so the Select is not blank',
    thinkingLevelsForModel(['default', 'low', 'high'], 'medium').some((o) => o.value === 'medium')
  )

  eq('transcription capability matches the engine', modelCapabilities('gemini-2.0-flash').supportsTranscription, false)
  eq('2.5 can transcribe', modelCapabilities('gemini-2.5-flash').supportsTranscription, true)
  eq('3.x can transcribe', modelCapabilities('gemini-3.1-pro').supportsTranscription, true)
  eq('effective level is reported honestly', effectiveThinkingLevel('gemini-3.1-pro', 'minimal'), 'low')
}

// ── A.1: subtitle intake — inspect/decode/language owner (Bundle A, D14.1) ─────
//
// Synthetic, author-written dialogue encoded into each code page. These are the always-run controls;
// the ≥5-real-files-per-code-page proof is `scripts/gates/fixtures/encoding/verify-corpus.mjs` against
// the private corpus (gate_ledger.md §5d), whose tracked manifest is checked at the end of this section.

section('A.1 — subtitle intake: inspect, decode, language, receipt')
{
  const encodeLegacy = (text: string, cp: string): Buffer => {
    const dec = new TextDecoder(cp)
    const map = new Map<string, number>()
    for (let b = 0; b < 256; b++) {
      const ch = dec.decode(Buffer.from([b]))
      if (ch !== '\uFFFD' && !map.has(ch)) map.set(ch, b)
    }
    const out: number[] = []
    for (const ch of text) {
      const b = map.get(ch)
      if (b === undefined) throw new Error(`${cp} cannot encode ${JSON.stringify(ch)}`)
      out.push(b)
    }
    return Buffer.from(out)
  }
  const srt = (lines: string[], eol = '\n'): string =>
    lines
      .map((l, i) => `${i + 1}${eol}00:00:${String(i * 3 + 1).padStart(2, '0')},000 --> 00:00:${String(i * 3 + 3).padStart(2, '0')},500${eol}${l}${eol}`)
      .join(eol)
  const said = (s: string): string[] => s.split(/(?<=[.?!])\s+/).filter(Boolean)
  const ok = (r: SubtitleInspectResult) => (r.ok ? r.inspection : null)

  const FIXTURES: { cp: string; lang: string; eol?: string; text: string }[] = [
    { cp: 'windows-1255', lang: 'he', eol: '\r\n',
      text: 'אני לא יודע מה זה. אתה רוצה ללכת איתי? כן, אבל רק אם יש לך זמן. זה לא טוב, הוא אמר את זה כל הזמן. מה אתה עושה פה עכשיו? אני חושב שהיא לא כאן. למה לא? אין לי מושג איך זה קרה.' },
    { cp: 'windows-1256', lang: 'ar',
      text: 'لا أعرف ماذا يحدث هنا. هل أنت بخير؟ أنا لم أكن هناك. ما هذا الذي في يدك؟ هو قال إنه سيأتي مع كل الناس. لماذا لا تذهب إلى البيت الآن؟ هذا ليس من شأنك يا صديقي. لقد كان هنا قبل ساعة.' },
    { cp: 'windows-1256', lang: 'fa',
      text: 'من نميدونم چي شده. تو اينجا چه کار ميکني؟ اين براي ما خيلي مهم است. با من بيا. نه، من بايد برم. اون گفت که به خونه مياد. شما هم با ما هستيد؟ خب، پس بريم. اين کتاب رو به من بده.' },
    { cp: 'windows-1251', lang: 'ru', eol: '\r\n',
      text: 'Я не знаю, что это было. Ты меня слышишь? Да, но мне нужно идти. Он сказал, что всё будет хорошо. Это не так просто, как ты думаешь. Мы были там вчера, а она нет. Ну вот, опять ты за своё.' },
    { cp: 'windows-1251', lang: 'uk',
      text: 'Я не знаю, що це було. Ти мене чуєш? Так, але мені треба йти. Він сказав, що все буде добре. Це не так просто, як ти думаєш. Ми були там учора, а вона ні. Чи є тут хтось, хто мене знає? Вже пізно.' },
    { cp: 'windows-1250', lang: 'pl',
      text: 'Nie wiem, co to było. Czy ty mnie słyszysz? Tak, ale muszę już iść. On powiedział, że wszystko będzie dobrze. To nie jest takie proste, jak myślisz. Byłem tam wczoraj, a ona nie. Wiesz, że to się może zdarzyć? Jestem tu tylko na chwilę, dobrze?' },
    { cp: 'windows-1250', lang: 'cs',
      text: 'Nevím, co to bylo. Slyšíš mě? Ano, ale už musím jít. Řekl, že to bude dobré. To není tak jednoduché, jak si myslíš. Byl jsem tam včera, ale ona ne. Víš, proč jsem tady? Jen se na to podívej, už je to pryč.' },
    { cp: 'windows-1250', lang: 'hu',
      text: 'Nem tudom, mi volt ez. Hallasz engem? Igen, de már mennem kell. Azt mondta, hogy minden rendben lesz. Ez nem olyan egyszerű, mint gondolod. Tegnap ott voltam, de ő nem. Mit csinálsz itt most? Még nincs késő, csak gyere velem.' },
    { cp: 'windows-1252', lang: 'fr',
      text: "Je ne sais pas ce que c'est. Tu m'entends ? Oui, mais je dois partir. Il a dit que tout irait bien. Ce n'est pas aussi simple que tu le penses. J'étais là hier, mais elle non. C'est à toi de voir, moi je reste ici avec les enfants. Elle a le cœur sur la main… vraiment." },
    { cp: 'windows-1252', lang: 'es',
      text: 'No sé qué es esto. ¿Me oyes? Sí, pero tengo que irme. Él dijo que todo estaría bien. No es tan fácil como crees. Yo estuve allí ayer, pero ella no. ¿Por qué no vienes con nosotros? Está bien, ahora mismo voy, señor.' },
    { cp: 'windows-1252', lang: 'pt',
      text: 'Eu não sei o que é isso. Você me ouve? Sim, mas eu tenho que ir. Ele disse que tudo ia ficar bem. Não é tão fácil como você pensa. Eu estava lá ontem, mas ela não. Por que você não vem com a gente? Está bem, já vou.' },
    { cp: 'windows-1253', lang: 'el',
      text: 'Δεν ξέρω τι είναι αυτό. Με ακούς; Ναι, αλλά πρέπει να φύγω. Είπε ότι όλα θα πάνε καλά. Άσε με να σου πω κάτι. Ήμουν εκεί χθες, αλλά αυτή όχι. Τι θέλεις από μένα;' },
    { cp: 'windows-1254', lang: 'tr',
      text: 'Bunun ne olduğunu bilmiyorum. Beni duyuyor musun? Evet, ama gitmem gerek. Her şeyin iyi olacağını söyledi. Bu senin düşündüğün kadar kolay değil. Dün oradaydım, ama o yoktu. Şimdi ne yapacağız? Neden benimle gelmiyorsun? Hayır, bir şey yok. Sana bir şey söylemem lazım, ama burada değil. Çok iyi, o zaman yarın görüşürüz. Ben de seni çok özledim.' }
  ]

  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'ng-a1-'))
  const put = (name: string, buf: Buffer): string => {
    const p = path.join(dir, name)
    fs.writeFileSync(p, buf)
    return p
  }

  eq('A.1 the closed legacy set is the seven labelled Windows code pages', [...LEGACY_ENCODINGS].sort(), [
    'windows-1250', 'windows-1251', 'windows-1252', 'windows-1253', 'windows-1254', 'windows-1255', 'windows-1256'
  ])

  for (const f of FIXTURES) {
    const text = srt(said(f.text), f.eol)
    const bytes = encodeLegacy(text, f.cp)
    const file = put(`${f.lang}-${f.cp}.srt`, bytes)
    const r = inspectSubtitleFile(file)
    const ins = ok(r)
    eq(`A.1 ${f.lang} in ${f.cp}: detected as ${f.cp} / ${f.lang}`, ins && [ins.receipt.encoding, ins.language], [f.cp, f.lang])
    check(`A.1 ${f.lang} in ${f.cp}: encoding and language are certain`, !!ins && ins.encodingCertain && ins.languageCertain)
    check(
      `A.1 ${f.lang} in ${f.cp}: the decode is the exact visible text, line endings and cue structure included`,
      !!ins && decodeSubtitleBuffer(bytes, ins.receipt.encoding) === text
    )
    check(`A.1 ${f.lang} in ${f.cp}: the original is byte-identical after inspection`, fs.readFileSync(file).equals(bytes))
  }

  // §17.5 item 1: valid UTF-8 is never reinterpreted, even when a legacy page would decode it "plausibly".
  const frUtf8 = srt(said(FIXTURES.find((f) => f.lang === 'fr')!.text))
  const u1 = ok(inspectSubtitleBytes(Buffer.from(frUtf8, 'utf-8'), { path: 'x.srt' }))
  eq('A.1 valid UTF-8 French stays UTF-8 (never read as cp1252 mojibake)', u1 && [u1.receipt.encoding, u1.encodingSource, u1.language], ['utf-8', 'utf8', 'fr'])
  check('A.1 valid UTF-8 decodes to exactly its own text', decodeSubtitleBuffer(Buffer.from(frUtf8, 'utf-8'), 'utf-8') === frUtf8)
  const heUtf8 = srt(said(FIXTURES[0].text))
  const u2 = ok(inspectSubtitleBytes(Buffer.from(heUtf8, 'utf-8'), { path: 'x.srt', hint: 'ar' }))
  eq('A.1 valid UTF-8 Hebrew: UTF-8 / he, a wrong hint ignored', u2 && [u2.receipt.encoding, u2.language, u2.hintUsed], ['utf-8', 'he', false])

  // BOM controls.
  const enText = srt([
    "I don't know what you want from me.", 'You have to tell me the truth now.', "It's not what I was looking for.",
    'We can do this, but not here and not with them.', 'Is that your car out there?', 'I think he was right all along, and so are you.',
    'What are you going to do with it?', 'Get in, we have to go before the rain.'
  ])
  const bom8 = Buffer.concat([Buffer.from([0xef, 0xbb, 0xbf]), Buffer.from(enText, 'utf-8')])
  const b8 = ok(inspectSubtitleBytes(bom8, { path: 'x.srt' }))
  eq('A.1 UTF-8 BOM: encoding utf-8-bom, language en', b8 && [b8.receipt.encoding, b8.encodingSource, b8.language], ['utf-8-bom', 'bom', 'en'])
  check('A.1 UTF-8 BOM: the BOM is consumed and nothing else changes', decodeSubtitleBuffer(bom8, 'utf-8-bom') === enText)
  const le = Buffer.concat([Buffer.from([0xff, 0xfe]), Buffer.from(enText, 'utf16le')])
  const ble = ok(inspectSubtitleBytes(le, { path: 'x.srt' }))
  eq('A.1 UTF-16LE BOM decodes as utf-16le-bom / en', ble && [ble.receipt.encoding, ble.language], ['utf-16le-bom', 'en'])
  check('A.1 UTF-16LE BOM text is exact', decodeSubtitleBuffer(le, 'utf-16le-bom') === enText)
  const beBody = Buffer.from(enText, 'utf16le')
  for (let i = 0; i + 1 < beBody.length; i += 2) [beBody[i], beBody[i + 1]] = [beBody[i + 1], beBody[i]]
  const be = Buffer.concat([Buffer.from([0xfe, 0xff]), beBody])
  const bbe = ok(inspectSubtitleBytes(be, { path: 'x.srt' }))
  eq('A.1 UTF-16BE BOM decodes as utf-16be-bom / en', bbe && [bbe.receipt.encoding, bbe.language], ['utf-16be-bom', 'en'])
  check('A.1 UTF-16BE BOM text is exact', decodeSubtitleBuffer(be, 'utf-16be-bom') === enText)
  const noBom16 = inspectSubtitleBytes(Buffer.from(enText, 'utf16le'), { path: 'x.srt' })
  eq('A.1 UTF-16 without a BOM is refused, not guessed', noBom16.ok ? 'ok' : noBom16.code, 'utf16-no-bom')

  // §17.5 item 10: ASS keeps its UTF-8/BOM-UTF-16 path; only no-BOM legacy ASS is refused.
  const assText = '[Script Info]\nTitle: t\n\n[Events]\nFormat: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text\n' +
    'Dialogue: 0,0:00:01.00,0:00:02.00,Default,,0,0,0,,{\\an8}Je ne sais pas ce que tu veux, mais je suis là.\n'
  const a1 = ok(inspectSubtitleBytes(Buffer.from(assText, 'utf-8'), { path: 'styled.ass' }))
  eq('A.1 BOM-less UTF-8 .ass is accepted as UTF-8', a1 && [a1.format, a1.receipt.encoding], ['ass', 'utf-8'])
  const a2 = ok(inspectSubtitleBytes(Buffer.concat([Buffer.from([0xff, 0xfe]), Buffer.from(assText, 'utf16le')]), { path: 'styled.ass' }))
  eq('A.1 BOM-marked UTF-16 .ass is accepted', a2 && [a2.format, a2.receipt.encoding], ['ass', 'utf-16le-bom'])
  const a3 = inspectSubtitleBytes(encodeLegacy(assText, 'windows-1252'), { path: 'styled.ass' })
  eq('A.1 no-BOM legacy .ass is refused', a3.ok ? 'ok' : a3.code, 'ass-legacy')
  check('A.1 the .ass refusal tells the user to re-save as UTF-8', !a3.ok && a3.error.includes('UTF-8'))

  eq('A.1 an empty file is refused', (() => { const r = inspectSubtitleBytes(Buffer.alloc(0), { path: 'x.srt' }); return r.ok ? 'ok' : r.code })(), 'empty')
  const noise = Buffer.from(Array.from({ length: 900 }, (_, i) => (i % 7 === 6 ? 0x20 : 0x80 + ((i * 37) % 0x7f))))
  const nz = inspectSubtitleBytes(noise, { path: 'x.srt' })
  eq('A.1 bytes no candidate decodes plausibly are refused', nz.ok ? 'ok' : nz.code, 'undetectable')
  check('A.1 the refusal offers the language choice as the way through', !nz.ok && nz.error.includes("Choose the file's language"))

  // §17.5 item 4: ambiguous short files, punctuation/numbers/tags, wrong hints, mixed scripts.
  const shortEs = encodeLegacy(srt(['¿Qué?', 'Sí, señor.']), 'windows-1252')
  const se = inspectSubtitleBytes(shortEs, { path: 'x.srt' })
  check('A.1 a two-cue file is never reported as a certain language', !(se.ok && se.inspection.languageCertain && se.inspection.encodingCertain))

  const tagged = srt([
    '<i>Я не знаю, что это было.</i>', '{\\an8}Ты меня слышишь? 12:30, 1999 год...', '♪ Да, но мне нужно идти ♪',
    '- Он сказал, что всё будет хорошо.\n- Это не так просто!', '<font color="#ffff00">Мы были там вчера, а она нет.</font>',
    'Ну вот, опять ты за своё... 100%', 'Это было только у меня, и всё.'
  ].map((l) => l.replace(/♪/g, '*')))
  const tg = ok(inspectSubtitleBytes(encodeLegacy(tagged, 'windows-1251'), { path: 'x.srt' }))
  eq('A.1 tags, numbers and punctuation do not disturb detection (ru / cp1251)', tg && [tg.receipt.encoding, tg.language], ['windows-1251', 'ru'])
  check('A.1 tags survive the decode verbatim', !!tg && decodeSubtitleBuffer(encodeLegacy(tagged, 'windows-1251'), tg.receipt.encoding) === tagged)

  const heBytes = encodeLegacy(srt(said(FIXTURES[0].text)), 'windows-1255')
  const wh = ok(inspectSubtitleBytes(heBytes, { path: 'movie.ar.srt', hint: 'ar' }))
  eq('A.1 a wrong cross-script hint cannot force an implausible decode', wh && [wh.receipt.encoding, wh.language, wh.hintUsed], ['windows-1255', 'he', false])
  const esBytes = encodeLegacy(srt(said(FIXTURES.find((f) => f.lang === 'es')!.text)), 'windows-1252')
  const wp = ok(inspectSubtitleBytes(esBytes, { path: 'x.srt', hint: 'pl' }))
  eq('A.1 a wrong same-script hint cannot override a clear language', wp && [wp.receipt.encoding, wp.language, wp.hintUsed], ['windows-1252', 'es', false])

  const hrBs = srt(said('Ne znam, je li to bilo dobro. Ti si bio ovdje, ali ja nisam. Kako si mi to mogao učiniti? Sve je u redu, ne brini se za mene. On je rekao da će doći kad bude mogao. Ja sam bio na poslu cijeli dan, a ti? Ona je bila sa mnom, ali sada je otišla. Da li ti znaš kako se zove?'))
  const tieBytes = encodeLegacy(hrBs, 'windows-1250')
  const tie = ok(inspectSubtitleBytes(tieBytes, { path: 'x.srt' }))
  check('A.1 Croatian/Bosnian shared text: decoded as cp1250, language not claimed as certain', !!tie && tie.receipt.encoding === 'windows-1250' && !tie.languageCertain)
  const tieHint = ok(inspectSubtitleBytes(tieBytes, { path: 'film.bs.srt', hint: 'bs' }))
  eq('A.1 a hint breaks a same-script near-tie', tieHint && [tieHint.language, tieHint.hintUsed, tieHint.languageCertain], ['bs', true, true])

  const mixed = srt([...said(FIXTURES[0].text), 'Yesterday all my troubles seemed so far away.', 'Oh, I believe in yesterday.'])
  const mx = ok(inspectSubtitleBytes(encodeLegacy(mixed, 'windows-1255'), { path: 'x.srt' }))
  eq('A.1 Hebrew with English song lines stays cp1255 / he', mx && [mx.receipt.encoding, mx.language], ['windows-1255', 'he'])
  const enMostly = srt([
    "I don't know what you want from me.", 'You have to tell me the truth now.', "It's not what I was looking for.",
    'We can do this, but not here and not with them.', 'Is that your car out there?', 'I think he was right all along.',
    'What are you going to do with it?', 'Get in, we have to go before the rain.', ...said(FIXTURES[0].text).slice(0, 3)
  ])
  const em = inspectSubtitleBytes(encodeLegacy(enMostly, 'windows-1255'), { path: 'x.srt' })
  check(
    'A.1 mostly-English cp1255 with Hebrew lines is never decoded through cp1252 (no silent mojibake)',
    !(em.ok && em.inspection.receipt.encoding === 'windows-1252'),
    JSON.stringify(em.ok ? [em.inspection.receipt.encoding, em.inspection.language] : em.code)
  )

  // Override: the user's language decides, and for legacy bytes it selects the code page.
  const plBytes = encodeLegacy(srt(said(FIXTURES.find((f) => f.lang === 'pl')!.text)), 'windows-1250')
  const ov1 = ok(inspectSubtitleBytes(plBytes, { path: 'x.srt', language: 'cs' }))
  eq('A.1 override cs on cp1250 bytes: cp1250 / cs, source override', ov1 && [ov1.receipt.encoding, ov1.language, ov1.encodingSource, ov1.languageCertain], ['windows-1250', 'cs', 'override', true])
  const ov2 = ok(inspectSubtitleBytes(plBytes, { path: 'x.srt', language: 'ru' }))
  eq('A.1 override ru selects cp1251 — the user may decide, the decode follows', ov2 && ov2.receipt.encoding, 'windows-1251')
  const ov3 = inspectSubtitleBytes(plBytes, { path: 'x.srt', language: 'lt' })
  eq('A.1 override to a language with no supported code page is refused', ov3.ok ? 'ok' : ov3.code, 'override-unsupported')
  const ov4 = ok(inspectSubtitleBytes(Buffer.from(frUtf8, 'utf-8'), { path: 'x.srt', language: 'it' }))
  eq('A.1 override on UTF-8 changes the language, never the encoding', ov4 && [ov4.receipt.encoding, ov4.language], ['utf-8', 'it'])
  const rev = ok(inspectSubtitleBytes(plBytes, { path: 'x.srt' }))
  eq('A.1 inspecting again without the override reverts to the detection', rev && [rev.receipt.encoding, rev.language], ['windows-1250', 'pl'])
  eq('A.1 legacyEncodingsFor: pl, he, regional pt-BR, lt', [legacyEncodingsFor('pl'), legacyEncodingsFor('he'), legacyEncodingsFor('pt-BR'), legacyEncodingsFor('lt')], [
    ['windows-1250'], ['windows-1255'], ['windows-1252'], []
  ])

  // §2.9: BiDi marks stripped for analysis only.
  eq('A.1 stripBidiControls removes every listed mark', stripBidiControls('\u202Bא\u202C\u2066b\u2069\u200E\u200F\u061C\uFEFFc\u202A\u202D\u202E\u2067\u2068'), 'אbc')
  const rtl = srt(said(FIXTURES[0].text).map((l) => `\u202B${l}\u202C`))
  const rt = ok(inspectSubtitleBytes(Buffer.from(rtl, 'utf-8'), { path: 'x.srt' }))
  eq('A.1 RTL-embedded Hebrew is still he', rt && rt.language, 'he')
  check('A.1 the preview is free of BiDi marks', !!rt && rt.preview.length > 0 && stripBidiControls(rt.preview) === rt.preview)
  check('A.1 the decoded text handed onward keeps the BiDi marks', decodeSubtitleBuffer(Buffer.from(rtl, 'utf-8'), 'utf-8') === rtl)

  // §17.5 item 8: the receipt, and Start's single verified read.
  const heFile = put('receipt.srt', heBytes)
  const pinned = 1_700_000_000
  fs.utimesSync(heFile, pinned, pinned)
  const rcpt = ok(inspectSubtitleFile(heFile))
  check('A.1 receipt: canonical path', !!rcpt && rcpt.receipt.path === fs.realpathSync(heFile))
  check('A.1 receipt: raw byte length and SHA-256 of the exact bytes', !!rcpt && rcpt.receipt.byteLength === heBytes.length && rcpt.receipt.sha256 === createHash('sha256').update(heBytes).digest('hex'))
  if (rcpt) {
    const v = readVerifiedSubtitle(heFile, rcpt.receipt)
    check('A.1 verified read returns the exact Buffer and its decode', v.ok && v.buffer.equals(heBytes) && v.text === decodeSubtitleBuffer(heBytes, 'windows-1255'))
    const st = fs.statSync(heFile)
    const swapped = Buffer.from(heBytes)
    const at = swapped.indexOf(Buffer.from('00:00:01,000'))
    swapped.write('00:00:02,000', at, 'latin1')
    fs.writeFileSync(heFile, swapped)
    fs.utimesSync(heFile, pinned, pinned)
    const st2 = fs.statSync(heFile)
    check('A.1 the swap fixture really is same path / same size / same mtime / different parseable cues', st2.size === st.size && st2.mtimeMs === st.mtimeMs && !swapped.equals(heBytes))
    const sw = readVerifiedSubtitle(heFile, rcpt.receipt)
    eq('A.1 a same-path/size/mtime byte swap is refused on digest', sw.ok ? 'ok' : sw.code, 'changed')
    const other = put('other.srt', heBytes)
    const pm = readVerifiedSubtitle(other, rcpt.receipt)
    eq('A.1 identical bytes at another path are refused as a path mismatch', pm.ok ? 'ok' : pm.code, 'path-mismatch')
    const gone = readVerifiedSubtitle(path.join(dir, 'missing.srt'), rcpt.receipt)
    eq('A.1 an unreadable source is a typed refusal, never fail-open', gone.ok ? 'ok' : gone.code, 'read-failed')
    const ins2 = inspectSubtitleFile(path.join(dir, 'missing.srt'))
    eq('A.1 inspecting an unreadable file is a typed refusal', ins2.ok ? 'ok' : ins2.code, 'read-failed')
  }

  // §17.5 item 7 and the scope fence: one decode owner, no IPC/UI in it.
  const ownerSrc = fs.readFileSync(path.join(process.cwd(), 'electron', 'engine', 'subtitleInput.ts'), 'utf-8')
  check('A.1 subtitleInput.ts imports neither electron nor IPC', !/from 'electron'|ipcMain|ipcRenderer|BrowserWindow/.test(ownerSrc))
  const srtSrc = fs.readFileSync(path.join(process.cwd(), 'electron', 'engine', 'srt.ts'), 'utf-8')
  check('A.1 srt.ts never guesses an encoding', !/windows-125|TextDecoder|latin1/.test(srtSrc))

  // §17.5 items 2–3 and the closed-set rule: the tracked manifest of the private real corpus.
  const manifest = JSON.parse(fs.readFileSync(path.join(process.cwd(), 'scripts', 'gates', 'fixtures', 'encoding', 'manifest.json'), 'utf-8')) as {
    files: Record<string, unknown>[]
  }
  const perCp = new Map<string, number>()
  for (const f of manifest.files) perCp.set(String(f.siteEncoding), (perCp.get(String(f.siteEncoding)) ?? 0) + 1)
  check('A.1 manifest: ≥5 real files each for CP1255, CP1256, CP1251, CP1250', ['CP1255', 'CP1256', 'CP1251', 'CP1250'].every((cp) => (perCp.get(cp) ?? 0) >= 5))
  check('A.1 manifest: every runtime code page has ≥5 labelled real files', LEGACY_ENCODINGS.every((cp) => (perCp.get('CP' + cp.slice(8)) ?? 0) >= 5))
  check(
    'A.1 manifest: every entry carries provenance and both digests',
    manifest.files.every((f) => /^[0-9a-f]{64}$/.test(String(f.origSha256)) && /^[0-9a-f]{64}$/.test(String(f.refSha256)) && f.imdb && f.orgIdSubtitle && f.comFileId && f.siteLanguageIso639)
  )
  check('A.1 manifest: holds no subtitle text (no value longer than a digest)', manifest.files.every((f) => Object.values(f).every((v) => String(v).length <= 64)))
  rmTemp(dir)
}

// ── A.2: Start's one verified read, for both engines (Bundle A, D14.1, §17.5 items 6–9) ─────────────

section('A.2 — Start reads the subtitle once, proves it is the inspected file, and hands that text onward')
{
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'ng-a2-'))
  const put = (name: string, buf: Buffer): string => {
    const p = path.join(dir, name)
    fs.writeFileSync(p, buf)
    return p
  }
  const enc = (text: string, cp: string): Buffer => {
    const dec = new TextDecoder(cp)
    const map = new Map<string, number>()
    for (let b = 0; b < 256; b++) {
      const ch = dec.decode(Buffer.from([b]))
      if (ch !== '\uFFFD' && !map.has(ch)) map.set(ch, b)
    }
    return Buffer.from([...text].map((ch) => map.get(ch) ?? 0x3f))
  }
  const srtOf = (lines: string[], eol = '\n'): string =>
    lines
      .map((l, i) => `${i + 1}${eol}00:00:${String(i * 3 + 1).padStart(2, '0')},000 --> 00:00:${String(i * 3 + 3).padStart(2, '0')},500${eol}${l}${eol}`)
      .join(eol)
  const heText = srtOf([
    'אני לא יודע מה זה.', 'אתה רוצה ללכת איתי?', 'כן, אבל רק אם יש לך זמן.', 'זה לא טוב, הוא אמר את זה כל הזמן.',
    'מה אתה עושה פה עכשיו?', 'אני חושב שהיא לא כאן.', 'למה לא?', 'אין לי מושג איך זה קרה.'
  ], '\r\n')
  const heBytes = enc(heText, 'windows-1255')
  const enText = srtOf([
    "I don't know what you want from me.", 'You have to tell me the truth now.', "It's not what I was looking for.",
    'We can do this, but not here and not with them.', 'Is that your car out there?', 'I think he was right all along.'
  ])
  const hrBs = srtOf('Ne znam, je li to bilo dobro. Ti si bio ovdje, ali ja nisam. Kako si mi to mogao učiniti? Sve je u redu, ne brini se za mene. On je rekao da će doći kad bude mogao. Ja sam bio na poslu cijeli dan, a ti? Ona je bila sa mnom, ali sada je otišla. Da li ti znaš kako se zove?'.split(/(?<=[.?!])\s+/))
  const tiny1252 = Buffer.from('1\r\n00:00:01,000 --> 00:00:02,000\r\ncaf\xe9 cr\xe8me\r\n', 'latin1')
  const shortEs = enc(srtOf(['No sé qué es esto.', '¿Me oyes?', 'Sí, pero tengo que irme.', 'Él dijo que todo estaría bien.']), 'windows-1252')
  const KEY_A2 = 'AIza' + 'SyA2000000000000000000000000000000000'

  // The IPC copy of the intake types (shared/types.ts) is the engine owner's, field for field.
  type Same<A, B> = [A] extends [B] ? ([B] extends [A] ? true : false) : false
  const sameTypes: [
    Same<IpcSubtitleEncoding, SubtitleEncoding>,
    Same<IpcSubtitleReceipt, SubtitleReceipt>,
    Same<IpcSubtitleInspection, SubtitleInspection>,
    Same<IpcSubtitleRefusalCode, SubtitleRefusalCode>,
    Same<IpcSubtitleInspectResult, SubtitleInspectResult>
  ] = [true, true, true, true, true]
  check('A.2 the IPC intake types (shared/types.ts) are the engine owner\u2019s, field for field', sameTypes.every(Boolean))

  // The language hint: track tag first, else the filename's trailing tag. Tiebreaker only (§2.6 step 5).
  eq(
    'A.2 subtitleLanguageHint reads the track tag, then the trailing filename tag, and nothing else',
    [
      subtitleLanguageHint('Film.he.srt'), subtitleLanguageHint('Film.heb.srt'), subtitleLanguageHint('Film.iw.srt'),
      subtitleLanguageHint('C:\\x\\Movie.2019.1080p.pt-BR.srt'), subtitleLanguageHint('Film.Hebrew.srt'), subtitleLanguageHint('Film.en.forced.srt'),
      subtitleLanguageHint('Film.srt'), subtitleLanguageHint('It.srt'), subtitleLanguageHint('Film.x264.srt'), subtitleLanguageHint('Film.en.srt', 'heb')
    ],
    ['he', 'he', 'he', 'pt-BR', 'he', 'en', '', '', '', 'he']
  )

  // subtitle:inspect
  const heFile = put('Film.heb.srt', heBytes)
  const insp = inspectSubtitleRequest({ path: heFile })
  eq('A.2 subtitle:inspect: a cp1255 file is cp1255 / he with a canonical receipt', insp.ok && [insp.inspection.receipt.encoding, insp.inspection.language, insp.inspection.receipt.path === fs.realpathSync(heFile)], ['windows-1255', 'he', true])
  const tieFile = put('tie.srt', enc(hrBs, 'windows-1250'))
  const tie = inspectSubtitleRequest({ path: tieFile, trackLanguage: 'bos' })
  eq('A.2 subtitle:inspect: a track tag breaks a Croatian/Bosnian tie', tie.ok && [tie.inspection.language, tie.inspection.hintUsed], ['bs', true])
  const tinyFile = put('tiny.srt', tiny1252)
  const tinyAuto = inspectSubtitleRequest({ path: tinyFile })
  const tinyFr = inspectSubtitleRequest({ path: tinyFile, language: 'fr' })
  eq('A.2 subtitle:inspect: a two-word legacy file is undetectable alone; the user\u2019s language decodes it', [tinyAuto.ok ? 'ok' : tinyAuto.code, tinyFr.ok && [tinyFr.inspection.receipt.encoding, tinyFr.inspection.encodingSource, tinyFr.inspection.preview]], ['undetectable', ['windows-1252', 'override', 'caf\u00e9 cr\u00e8me']])
  eq('A.2 subtitle:inspect: a request with no path is a typed refusal', (() => { const r = inspectSubtitleRequest({} as never); return r.ok ? 'ok' : r.code })(), 'read-failed')

  // Instrumentation: count reads of the user's file; optionally stop or fail at the sibling write.
  const io = fs as unknown as { readFileSync: (...a: unknown[]) => unknown; writeFileSync: (...a: unknown[]) => unknown }
  const realRead = io.readFileSync
  const realWrite = io.writeFileSync
  const isSibling = (p: unknown): p is string => typeof p === 'string' && /\.utf8\.(srt|ass)$/.test(p)
  function watched<T>(file: string, opt: { stopAtSibling?: boolean; failSibling?: boolean }, body: () => T): { value: T; reads: number; siblings: string[] } {
    const keys = new Set([path.resolve(file).toLowerCase(), fs.realpathSync(file).toLowerCase()])
    let reads = 0
    const siblings: string[] = []
    io.readFileSync = (p: unknown, ...rest: unknown[]) => {
      if (typeof p === 'string' && keys.has(path.resolve(p).toLowerCase())) reads++
      return realRead(p, ...rest)
    }
    io.writeFileSync = (p: unknown, ...rest: unknown[]) => {
      if (isSibling(p) && opt.failSibling) throw new Error('ENOSPC: no space left on device')
      const r = realWrite(p, ...rest)
      if (isSibling(p)) {
        siblings.push(p)
        if (opt.stopAtSibling) stopCurrent()
      }
      return r
    }
    try {
      const value = body()
      return { value, reads, siblings }
    } finally {
      io.readFileSync = realRead
      io.writeFileSync = realWrite
    }
  }

  // readTranslateSource with the page's receipt.
  if (insp.ok) {
    const v = watched(heFile, {}, () => readTranslateSource({ inputFile: heFile, sourceLang: 'auto', sourceReceipt: insp.inspection.receipt }))
    check('A.2 with a receipt: one read of the user\u2019s file returns that exact Buffer and its decode', v.value.ok && v.value.buffer.equals(heBytes) && v.value.text === heText && v.reads === 1, JSON.stringify({ reads: v.reads }))
    const bad = [
      { ...insp.inspection.receipt, sha256: 'x' },
      { ...insp.inspection.receipt, encoding: 'iso-8859-8' },
      { ...insp.inspection.receipt, byteLength: -1 },
      'not a receipt'
    ].map((r) => { const x = readTranslateSource({ inputFile: heFile, sourceLang: 'auto', sourceReceipt: r as never }); return x.ok ? 'ok' : x.code })
    eq('A.2 a malformed receipt from the renderer is refused, never trusted', bad, ['receipt-invalid', 'receipt-invalid', 'receipt-invalid', 'receipt-invalid'])
    const twin = put('twin.srt', heBytes)
    const pm = readTranslateSource({ inputFile: twin, sourceLang: 'auto', sourceReceipt: insp.inspection.receipt })
    eq('A.2 the same bytes at another path are refused as not the inspected file', pm.ok ? 'ok' : pm.code, 'path-mismatch')
  }
  // Without a receipt: inspect these same bytes, and refuse what the page would have had to confirm.
  const enFile = put('plain.srt', Buffer.from(enText, 'utf-8'))
  const nr = watched(enFile, {}, () => readTranslateSource({ inputFile: enFile, sourceLang: 'auto' }))
  check('A.2 no receipt, UTF-8: one read, the exact text', nr.value.ok && nr.value.text === enText && nr.value.receipt.encoding === 'utf-8' && nr.reads === 1, JSON.stringify({ reads: nr.reads }))
  const nh = readTranslateSource({ inputFile: heFile, sourceLang: 'auto' })
  eq('A.2 no receipt, a certain legacy file: decoded as detected', nh.ok && [nh.receipt.encoding, nh.text === heText], ['windows-1255', true])
  const esFile = put('short-es.srt', shortEs)
  const codeOf = (f: string): string => { const r = readTranslateSource({ inputFile: f, sourceLang: 'auto' }); return r.ok ? 'ok' : r.code }
  eq('A.2 no receipt: an unconfirmable legacy file, an undetectable one and a missing one are typed refusals', [codeOf(esFile), codeOf(tinyFile), codeOf(path.join(dir, 'missing.srt'))], ['unconfirmed', 'undetectable', 'read-failed'])
  check('A.2 the unconfirmed refusal sends the user to confirm the language', (() => { const r = readTranslateSource({ inputFile: esFile, sourceLang: 'auto' }); return !r.ok && r.error.includes("confirm the file's language") })())


  // Source pins: one reader, no second read, no fail-open helper, on either path.
  const nativeSrc = fs.readFileSync(path.join(process.cwd(), 'electron', 'engine', 'native', 'nativeAdapter.ts'), 'utf-8')
  const translateBody = nativeSrc.slice(nativeSrc.indexOf('async translate(args, ctx, emit)'), nativeSrc.indexOf('async transcribe(args, ctx, emit)'))
  check(
    'A.2 native translate: consumes the verified text for the parse, the note and the output check; no path read, no ensureUtf8Subtitle',
    // Amended in place at Step 3.4 (gate_ledger §5j.4): a Continue decodes the same verified bytes with the
    // checkpoint's frozen encoding, so the run reads `sourceText`, which is only ever one of these two.
    /readTranslateSource\(args\)/.test(translateBody) &&
      /readSource:\s*\(\)\s*=>\s*sourceText\b/.test(translateBody) &&
      /let sourceText = source\.text\b/.test(translateBody) &&
      [...translateBody.matchAll(/sourceText = ([^\n]*)/g)].map((m) => m[1].trim()).every((rhs) => rhs === 'source.text' || /^decodeSubtitleBuffer\(source\.buffer, config\.sourceEncoding\)$/.test(rhs)) &&
      /sourceFragmentNote\(source\.text\)/.test(translateBody) &&
      /deps\.scanOutput\(source\.receipt\.path, outputPath, sourceText\)/.test(translateBody) &&
      !/readFileSync/.test(translateBody) &&
      !/ensureUtf8Subtitle/.test(nativeSrc)
  )
  const ipcSrcA2 = fs.readFileSync(path.join(process.cwd(), 'electron', 'main', 'ipc.ts'), 'utf-8')
  // Amended in place at Step 3.4 (gate_ledger §5j.4): the adapter also receives the resume store.
  // Amended in place at Round 17 F4: the adapter also receives Bundle F's request record.
  // Amended in place at Round 19 H.11: the adapter also receives the OpenSubtitles client captured at Start.
  check(
    'A.2 ipc: native\u2019s output check is handed the verified text',
    /createNativeEngineAdapter\(\{\s*scanOutput:\s*\(source, output, text\)\s*=>\s*scanOutputWarnings\(source, output, text\)\.map\(toRunWarning\)(?:,\s*resume:\s*resumeStore\(\))?(?:,\s*quotaBudget:\s*\(\)\s*=>\s*quotaBudgetStoreAt\(app\.getPath\('userData'\)\))?(?:,\s*referenceClient)?\s*\}\)/.test(ipcSrcA2)
  )
  const preloadSrcA2 = fs.readFileSync(path.join(process.cwd(), 'electron', 'preload', 'index.ts'), 'utf-8')
  check(
    'A.2 subtitle:inspect is registered in main and exposed by the preload',
    /ipcMain\.handle\('subtitle:inspect',\s*\(_e, req: SubtitleInspectRequest\)\s*=>\s*inspectSubtitleRequest\(req\)\)/.test(ipcSrcA2) && /inspectSubtitle:[\s\S]{0,160}'subtitle:inspect'/.test(preloadSrcA2)
  )
  check('A.2 the inspected originals are byte-identical after everything above', fs.readFileSync(heFile).equals(heBytes) && fs.readFileSync(tinyFile).equals(tiny1252))

  section('A.3 — the Translate page asks when it cannot be sure, and sends the language it settled on')
  // The page's own decision functions, fed by the real subtitle:inspect handler on real files.
  const inspectA3 = (req: Parameters<typeof inspectSubtitleRequest>[0]) => Promise.resolve(inspectSubtitleRequest(req))
  const pageCheck = async (file: string, srcLang: string, filePick: string | null = null, trackLanguage?: string): Promise<SourceCheck> =>
    sourceCheck(await inspectSource(inspectA3, file, trackLanguage, sourceUserLanguage(filePick, srcLang)), filePick, srcLang)
  const shape = (c: SourceCheck): unknown[] =>
    c.kind === 'ready'
      ? [c.kind, c.language, c.how, c.receipt.encoding]
      : c.kind === 'confirm'
        ? [c.kind, c.reason, c.guess, c.allowAuto]
        : [c.kind]
  const enLongText = srtOf([
    "I don't know what you want from me, but I can't stay here.", 'You have to tell me the truth now, all of it.',
    "It's not what I was looking for when I came to this town.", 'We can do this, but not here and not with them watching.',
    'Is that your car out there by the old house?', 'I think he was right all along, and we should have listened.',
    'There is nothing more that I can do for you tonight.', 'She said she would be back before the end of the week.'
  ])
  const enLong = put('long-en.srt', Buffer.from(enLongText, 'utf-8'))
  const esUtf8 = put('short-es-utf8.srt', Buffer.from(srtOf(['No sé qué es esto.', '¿Me oyes?', 'Sí, pero tengo que irme.', 'Él dijo que todo estaría bien.']), 'utf-8'))
  const assOf = (text: string): string =>
    '[Script Info]\nTitle: t\n\n[Events]\nFormat: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text\n' +
    `Dialogue: 0,0:00:01.00,0:00:03.00,Default,,0,0,0,,${text}\n`
  const legacyAss = put('styled-he.ass', enc(assOf('אני לא יודע מה זה.'), 'windows-1255'))
  const utf8Ass = put('styled-en.ass', Buffer.from(assOf('I think he was right all along and we should have listened to him. '.repeat(6)), 'utf-8'))
  const emptyFile = put('empty.srt', Buffer.alloc(0))
  const a3Files = [heFile, enLong, esUtf8, esFile, tinyFile, tieFile, legacyAss, utf8Ass]
  const a3Before = a3Files.map((f) => fs.readFileSync(f))

  const heAuto = await pageCheck(heFile, 'auto')
  eq(
    'A.3 Auto Detect, a certain cp1255 file: shown as Hebrew (detected); Start is open and sends "he" with the cp1255 receipt',
    [shape(heAuto), sourceBlockReason(heAuto), heAuto.kind === 'ready' && startSource(heAuto)?.sourceReceipt === heAuto.receipt && startSource(heAuto)?.sourceLang],
    [['ready', 'he', 'detected', 'windows-1255'], '', 'he']
  )
  const esAuto = await pageCheck(esUtf8, 'auto')
  eq(
    'A.3 Auto Detect, a short UTF-8 Spanish file: the card blocks Start, guesses Spanish and offers to let the model work it out',
    [shape(esAuto), startSource(esAuto), sourceBlockReason(esAuto).length > 0],
    [['confirm', 'language', 'es', true], null, true]
  )
  const esPicked = await pageCheck(esUtf8, 'auto', 'pt')
  const esReverted = await pageCheck(esUtf8, 'auto', null)
  const esAgain = await pageCheck(esUtf8, 'auto', 'es')
  eq(
    'A.3 override round-trip: change to Portuguese, revert to detected (asks again), confirm Spanish — Start blocked only while unanswered',
    [shape(esPicked), startSource(esPicked)?.sourceLang, shape(esReverted), startSource(esReverted), shape(esAgain), startSource(esAgain)?.sourceLang],
    [['ready', 'pt', 'picked', 'utf-8'], 'pt', ['confirm', 'language', 'es', true], null, ['ready', 'es', 'picked', 'utf-8'], 'es']
  )
  const esModel = await pageCheck(esUtf8, 'auto', 'auto')
  eq('A.3 "let the model work it out" on UTF-8 text: Start opens and sends no source language, as Auto Detect always did', [shape(esModel), startSource(esModel)?.sourceLang], [['ready', 'auto', 'auto', 'utf-8'], 'auto'])
  const legAuto = await pageCheck(esFile, 'auto')
  const legModel = await pageCheck(esFile, 'auto', 'auto')
  const legEs = await pageCheck(esFile, 'auto', 'es')
  eq(
    'A.3 a short legacy file: the card asks, the model cannot decide its letters for it, and choosing Spanish reads it as cp1252',
    [shape(legAuto), shape(legModel), shape(legEs), legEs.kind === 'ready' && legEs.preview],
    [['confirm', 'encoding', 'es', false], ['confirm', 'encoding', 'es', false], ['ready', 'es', 'picked', 'windows-1252'], 'No sé qué es esto.']
  )
  const tinyA3 = await pageCheck(tinyFile, 'auto')
  const tinyPick = await pageCheck(tinyFile, 'auto', 'fr')
  const tinyBack = await pageCheck(tinyFile, 'auto', null)
  eq(
    'A.3 an undetectable legacy file: the card asks for its language; French reads "café crème"; revert asks again',
    [shape(tinyA3), shape(tinyPick), tinyPick.kind === 'ready' && tinyPick.preview, shape(tinyBack)],
    [['confirm', 'undetectable', '', false], ['ready', 'fr', 'picked', 'windows-1252'], 'caf\u00e9 cr\u00e8me', ['confirm', 'undetectable', '', false]]
  )
  const heAsEn = await pageCheck(heFile, 'en')
  const heUse = await pageCheck(heFile, 'en', 'he')
  const heKeep = await pageCheck(heFile, 'en', 'en')
  eq(
    'A.3 a Source Language that would misread a certain legacy file asks first; "Use Hebrew" and "Keep English" both answer it',
    [shape(heAsEn), heAsEn.kind === 'confirm' && heAsEn.chosen, shape(heUse), shape(heKeep)],
    [['confirm', 'mismatch', 'he', false], 'en', ['ready', 'he', 'picked', 'windows-1255'], ['ready', 'en', 'picked', 'windows-1252']]
  )
  const enAsFr = await pageCheck(enLong, 'fr')
  eq(
    'A.3 a Source Language on UTF-8 text is the user\u2019s call: Start opens with it, and the note says what the file reads as',
    [shape(enAsFr), enAsFr.kind === 'ready' && enAsFr.detected, startSource(enAsFr)?.sourceLang],
    [['ready', 'fr', 'chosen', 'utf-8'], 'en', 'fr']
  )
  const tieTrack = await pageCheck(tieFile, 'auto', null, 'hrv')
  eq('A.3 an extracted track\u2019s language tag settles a Croatian/Bosnian tie', shape(tieTrack), ['ready', 'hr', 'detected', 'windows-1250'])
  const assLeg = await pageCheck(legacyAss, 'auto')
  const assLegPick = await pageCheck(legacyAss, 'auto', 'he')
  const assUtf8 = await pageCheck(utf8Ass, 'auto')
  eq(
    'A.3 D3: a non-UTF-8 .ass is refused in words and no language answers it; a UTF-8 .ass is refused by name when picked, with the sentence Start would give (RR-3)',
    [
      shape(assLeg), assLeg.kind === 'refused' && /\.ass file is not UTF-8/.test(assLeg.message), shape(assLegPick), sourceBlockReason(assLeg) === (assLeg.kind === 'refused' ? assLeg.message : ''),
      shape(assUtf8), sourceBlockReason(assUtf8)
    ],
    [['refused'], true, ['refused'], true, ['refused'], 'This is an ASS/SSA subtitle. The built-in translator reads SubRip (.srt) files only.']
  )
  const gone = await pageCheck(path.join(dir, 'gone.srt'), 'auto')
  const emptyA3 = await pageCheck(emptyFile, 'auto')
  const thrown = sourceCheck(await inspectSource(() => Promise.reject(new Error('channel closed')), heFile, undefined, 'auto'), null, 'auto')
  eq(
    'A.3 a missing, an empty or an uncheckable file is refused in words, never started',
    [shape(gone), shape(emptyA3), shape(thrown), thrown.kind === 'refused' && thrown.message.includes('could not be checked')],
    [['refused'], ['refused'], ['refused'], true]
  )
  const notReady = [esAuto, esReverted, legAuto, legModel, tinyA3, tinyBack, heAsEn, assLeg, assLegPick, gone, emptyA3, thrown, { kind: 'checking' } as SourceCheck]
  check('A.3 uncertain blocks Start: every unanswered, refused or still-reading state has a reason and nothing to send', notReady.every((c) => startSource(c) === null && sourceBlockReason(c).length > 0))
  const texts = [esAuto, legAuto, tinyA3, heAsEn].map((c) => (c.kind === 'confirm' ? sourceConfirmText(c) : ''))
  check(
    'A.3 the card says what it found in plain words: the guess, and for a mismatch both languages',
    texts[0].includes('Spanish') && texts[1].includes('not UTF-8') && texts[2].includes('Choose its language') && texts[3].includes('Hebrew') && texts[3].includes('English')
  )

  // R5-01: two code pages can both read as the same language and still give different letters. Albanian
  // is written in cp1250 and cp1252; byte 0xF8 is "ø" in one and "ř" in the other.
  const albLine = 'të në nuk një që është për unë çfarë jam ke ka.'
  const albAmb = put('alb-1252.srt', enc(srtOf([albLine, albLine, albLine, `${albLine} Søren.`]), 'windows-1252'))
  const albSame = put('alb-plain.srt', enc(srtOf([albLine, albLine, albLine, albLine]), 'windows-1252'))
  const pageCheckAt = async (file: string, srcLang: string, filePick: string | null, encoding?: SubtitleEncoding): Promise<SourceCheck> =>
    sourceCheck(await inspectSource(inspectA3, file, undefined, sourceUserLanguage(filePick, srcLang), encoding), filePick, srcLang)
  const albDetect = inspectSubtitleRequest({ path: albAmb })
  eq(
    'R5-01 detection: a cp1252 Albanian file that cp1250 also reads as Albanian, with different letters, is not encoding-certain',
    albDetect.ok && [albDetect.inspection.language, albDetect.inspection.encodingCertain, albDetect.inspection.languageCertain],
    ['sq', false, false]
  )
  const albAuto = await pageCheck(albAmb, 'auto')
  const albSq = await pageCheckAt(albAmb, 'auto', 'sq')
  const albSqGlobal = await pageCheckAt(albAmb, 'sq', null)
  const readingsOf = (c: SourceCheck): unknown =>
    c.kind === 'confirm' ? (c.readings ?? []).map((r) => [r.encoding, (r.preview ?? '').endsWith('Søren.') ? 'ø' : (r.preview ?? '').endsWith('Sřren.') ? 'ř' : r.preview]) : null
  eq(
    'R5-01 page: Auto Detect asks; confirming Albanian (per file or as Source Language) asks which reading, showing the line where they differ',
    [shape(albAuto), shape(albSq), readingsOf(albSq), shape(albSqGlobal), readingsOf(albSqGlobal)],
    [
      ['confirm', 'encoding', 'sq', false],
      ['confirm', 'reading', 'sq', false], [['windows-1250', 'ř'], ['windows-1252', 'ø']],
      ['confirm', 'reading', 'sq', false], [['windows-1250', 'ř'], ['windows-1252', 'ø']]
    ]
  )
  check(
    'R5-01 page: an unchosen reading blocks Start with a reason and nothing to send',
    [albAuto, albSq, albSqGlobal].every((c) => startSource(c) === null && sourceBlockReason(c).length > 0) &&
      albSq.kind === 'confirm' && sourceConfirmText(albSq).includes('Albanian') && sourceBlockReason(albSq).includes('letters are read')
  )
  const albPicked = await pageCheckAt(albAmb, 'auto', 'sq', 'windows-1252')
  const albOther = await pageCheckAt(albAmb, 'auto', 'sq', 'windows-1250')
  eq(
    'R5-01 page: choosing a reading settles it, either way, and Start sends Albanian with that reading\u2019s receipt',
    [shape(albPicked), startSource(albPicked)?.sourceLang, shape(albOther)],
    [['ready', 'sq', 'picked', 'windows-1252'], 'sq', ['ready', 'sq', 'picked', 'windows-1250']]
  )
  eq(
    'R5-01 Start without a receipt refuses the ambiguous file, with or without a Source Language hint',
    [codeOf(albAmb), (() => { const r = readTranslateSource({ inputFile: albAmb, sourceLang: 'sq' }); return r.ok ? 'ok' : r.code })()],
    ['unconfirmed', 'unconfirmed']
  )
  const albPlainDetect = inspectSubtitleRequest({ path: albSame })
  const albPlainSq = inspectSubtitleRequest({ path: albSame, language: 'sq' })
  eq(
    'R5-01 code pages that read the same letters are no rival: plain Albanian stays certain, detected and chosen',
    [albPlainDetect.ok && [albPlainDetect.inspection.language, albPlainDetect.inspection.encodingCertain], albPlainSq.ok && [albPlainSq.inspection.encodingCertain, albPlainSq.inspection.candidates.length], shape(await pageCheck(albSame, 'auto'))],
    [['sq', true], [true, 0], ['ready', 'sq', 'detected', 'windows-1250']]
  )
  const pin = (req: Parameters<typeof inspectSubtitleRequest>[0]): unknown => {
    const r = inspectSubtitleRequest(req)
    return r.ok ? [r.inspection.receipt.encoding, r.inspection.encodingSource, r.inspection.encodingCertain] : r.code
  }
  eq(
    'R5-01 a reading must be one the language is written in; junk or a reading without a language is ignored; UTF-8 ignores it',
    [
      pin({ path: albAmb, language: 'sq', encoding: 'windows-1255' }),
      pin({ path: albAmb, language: 'sq', encoding: 'latin-9' as never }),
      pin({ path: albAmb, encoding: 'windows-1252' }),
      pin({ path: enLong, language: 'en', encoding: 'windows-1252' }),
      pin({ path: heFile, language: 'he', encoding: 'windows-1255' })
    ],
    ['override-unsupported', ['windows-1250', 'override', false], ['windows-1250', 'detected', false], ['utf-8', 'utf8', true], ['windows-1255', 'override', true]]
  )

  // R5-02: refusing the user's own language choice keeps the way back.
  const heLt = await pageCheck(heFile, 'auto', 'lt')
  const heLtBack = await pageCheck(heFile, 'auto', null)
  const heLtFix = await pageCheck(heFile, 'auto', 'he')
  const heLtGlobal = await pageCheck(heFile, 'lt')
  eq(
    'R5-02 detected Hebrew → Lithuanian (no legacy code page) is refused as a changeable choice; revert and re-pick both reach Start',
    [
      shape(heLt), heLt.kind === 'refused' && heLt.canChange, heLt.kind === 'refused' && heLt.message.includes('Choose another language'), startSource(heLt),
      shape(heLtBack), startSource(heLtBack)?.sourceLang, shape(heLtFix), shape(heLtGlobal), heLtGlobal.kind === 'refused' && heLtGlobal.canChange,
      assLeg.kind === 'refused' && assLeg.canChange, gone.kind === 'refused' && gone.canChange
    ],
    [['refused'], true, true, null, ['ready', 'he', 'detected', 'windows-1255'], 'he', ['ready', 'he', 'picked', 'windows-1255'], ['refused'], true, false, false]
  )
  const noteHtml = (c: SourceCheck, picked: boolean): string =>
    renderToStaticMarkup(createElement(SourceLanguageNote, { check: c, picked, revertLabel: 'revert to detected', onPick: () => {}, onRevert: () => {} }))
  const ltHtml = noteHtml(heLt, true)
  const ltGlobalHtml = noteHtml(heLtGlobal, false)
  const assHtml = noteHtml(assLeg, false)
  const readingHtml = noteHtml(albSq, true)
  check(
    'R5-02 rendered: the refused per-file choice keeps "choose another language" and revert; a Source Language refusal keeps the picker',
    ltHtml.includes('no supported legacy code page') && ltHtml.includes('choose another language') && ltHtml.includes('revert to detected') &&
      ltGlobalHtml.includes('choose another language') && !ltGlobalHtml.includes('revert to detected'),
    ltHtml
  )
  check('R5-02 rendered: a hard refusal (D3 legacy .ass) offers no language controls', assHtml.includes('.ass file is not UTF-8') && !assHtml.includes('choose another language') && !assHtml.includes('revert'), assHtml)
  check(
    'R5-01 rendered: the reading card offers each reading by its differing line, plus change and revert',
    readingHtml.includes('Søren.') && readingHtml.includes('Sřren.') && readingHtml.includes('windows-1252') && readingHtml.includes('windows-1250') &&
      readingHtml.includes('choose another language') && readingHtml.includes('revert to detected'),
    readingHtml
  )
  // R5-03: the difference can sit past the first 120 characters of its line; the preview must still show it.
  const albLongLine = `${[albLine, albLine, albLine].join(' ')} Søren.`
  const albLong = put('alb-long-1252.srt', enc(srtOf([albLine, albLine, albLine, albLongLine]), 'windows-1252'))
  const longSq = inspectSubtitleRequest({ path: albLong, language: 'sq' })
  const longPreviews = longSq.ok ? longSq.inspection.candidates.map((c) => [c.encoding, c.preview ?? '']) : []
  eq(
    'R5-03 a difference past character 120 is inside both bounded previews, which start with an ellipsis and differ',
    [
      albLongLine.indexOf('Søren') > 120,
      longPreviews.map(([e, p]) => [e, p.startsWith('…'), p.length <= 122, p.includes('Søren') ? 'ø' : p.includes('Sřren') ? 'ř' : 'missing']),
      longPreviews.length === 2 && longPreviews[0][1] !== longPreviews[1][1]
    ],
    [true, [['windows-1250', true, true, 'ř'], ['windows-1252', true, true, 'ø']], true]
  )
  const longHtml = noteHtml(await pageCheckAt(albLong, 'auto', 'sq'), true)
  check('R5-03 rendered: the long-line reading card shows both "Søren" and "Sřren"', longHtml.includes('Søren') && longHtml.includes('Sřren'), longHtml)

  // What Start actually does with the page's answer.

  const pageSrc = fs.readFileSync(path.join(process.cwd(), 'src', 'pages', 'TranslatePage.tsx'), 'utf-8')
  const startFn = pageSrc.slice(pageSrc.indexOf('async function handleStart('), pageSrc.indexOf('function handleNew('))
  check(
    'A.3 page: Start sends the settled language and its receipt, never the raw picker value',
    /sourceLang: intake\.sourceLang,\s*sourceReceipt: intake\.sourceReceipt/.test(startFn) && !/sourceLang: srcLang/.test(pageSrc) && /const intake = startSource\(source\)/.test(startFn)
  )
  check(
    'A.3 page: a subtitle file is inspected on pick, an extracted track with its language tag, and Start waits on both',
    /inspectSource\(window\.api\.inspectSubtitle, subject\.path, subject\.trackLanguage, userLang, pickEncoding\)/.test(pageSrc) &&
      /inspectSource\(window\.api\.inspectSubtitle, trackPath, trackLanguage,/.test(startFn) &&
      /if \(srtFile\) return sourceBlockReason\(check\)/.test(pageSrc)
  )
  check('A.3 page: no modal, ever (feature_decisions §2.7) — the question is a card', !/window\.(confirm|alert|prompt)\(|<dialog|showMessageBox/.test(pageSrc) && /<SourceLanguageNote/.test(pageSrc))
  check('A.3 source bytes unchanged: every file the page inspected and started is byte-identical', a3Files.every((f, i) => fs.readFileSync(f).equals(a3Before[i])))
  rmTemp(dir)
}

// ── G3: output sanity (REP-16) and the token report (REP-1) ────────────────────

/** G3's measured filler run as file text, reused by the Step 0.5 scan check. */
let G3_FILLER_PAIR = { source: '', output: '' }
/** G3d's late-drift pair as file text, reused by the Step 0.7 warning split. */
let G3_TIMING_PAIR = { source: '', output: '' }

section('G3 — output sanity: two signals must agree before anything is said')
{
  const srt = (cues: string[]): string =>
    cues
      .map((text, i) => {
        const s = i * 2
        const stamp = (sec: number): string =>
          `00:${String(Math.floor(sec / 60)).padStart(2, '0')}:${String(sec % 60).padStart(2, '0')},000`
        return `${i + 1}\n${stamp(s)} --> ${stamp(s + 1)}\n${text}\n`
      })
      .join('\n')

  // Deterministic, so a fixture cannot drift between runs and quietly stop testing what it tested.
  const rand = (seed: number) => () => {
    seed = (seed + 0x6d2b79f5) | 0
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }

  /** A plausible clean pair: varied lengths, occasional two-line cues, a ~0.9x expansion factor. */
  function cleanPair(count: number): { source: string[]; output: string[] } {
    const next = rand(20260821)
    const source: string[] = []
    const output: string[] = []
    for (let i = 0; i < count; i++) {
      const words = 3 + Math.floor(next() * 9)
      const twoLine = next() < 0.3
      const src = Array.from({ length: words }, (_, w) => `word${(i + w) % 97}`).join(' ')
      const out = Array.from({ length: words }, (_, w) => `tr${(i + w) % 89}`).join(' ')
      source.push(twoLine ? src.replace(' ', '\n') : src)
      output.push(twoLine ? out.replace(' ', '\n') : out)
    }
    return { source, output }
  }

  // ---- the measured fault, reproduced at the indices it was measured at ----
  const FILLER = 'ב-'
  const bad = cleanPair(736)
  const corrupted = [...bad.output]
  for (let i = 463; i < 599; i++) corrupted[i] = FILLER // cues 464..599, 136 of them
  const warnings = scanTranslatedOutput(srt(bad.source), srt(corrupted))
  G3_FILLER_PAIR = { source: srt(bad.source), output: srt(corrupted) }

  check('G3 the filler run produces exactly one warning', warnings.length === 1, `got ${warnings.length}`)
  if (warnings.length === 1) {
    const w = warnings[0]
    check(`G3 the range starts at or before the first bad cue`, w.from <= 464, `from ${w.from}`)
    eq('G3 the range ends at the last bad cue', w.to, 599)
    check('G3 all three signals fired', w.signals.length === 3, w.signals.join('+'))
    check('G3 filler is not reported as a timing shift', !w.signals.includes('wrong timings'))
    check('G3 the message says the file was not altered', /exactly\s+as the engine wrote it/i.test(w.message))
  }
  eq('G3 the same file without the filler is silent', scanTranslatedOutput(srt(bad.source), srt(bad.output)).length, 0)

  // ---- each signal alone must NOT warn: this is what makes "two of three" real ----
  const only = (source: string[], output: string[]): number =>
    scanTranslatedOutput(srt(source), srt(output)).length

  // S1 alone: every translation identical, but the right length and the right shape.
  const s1Source = Array.from({ length: 200 }, (_, i) => `source line number ${i} here`)
  const s1Output = Array.from({ length: 200 }, () => 'identical translation text!')
  eq('G3 S1 alone (repeated text, normal length) says nothing', only(s1Source, s1Output), 0)

  // S2 alone: everything far too short, but all distinct and all one line like their sources.
  const s2Source = Array.from({ length: 200 }, (_, i) => `a reasonably long source sentence ${i}`)
  const s2Output = Array.from({ length: 200 }, (_, i) => `x${i}`)
  eq('G3 S2 alone (length collapse) says nothing', only(s2Source, s2Output), 0)

  // S3 alone: right length, all distinct, but every cue re-wrapped onto two lines.
  const s3Source = Array.from({ length: 200 }, (_, i) => `single line source sentence ${i}`)
  const s3Output = Array.from({ length: 200 }, (_, i) => `two line\ntranslation ${i} here`)
  eq('G3 S3 alone (re-wrapping) says nothing', only(s3Source, s3Output), 0)

  // ---- each PAIR must warn: if a signal were dead code, two of these would go quiet ----
  // Each corrupts a stretch rather than the whole file, which is both the measured fault shape and
  // what leaves S2 a clean baseline to judge against.
  const damage = (clean: string[], bad: (i: number) => string): string[] =>
    clean.map((text, i) => (i >= 60 && i < 160 ? bad(i) : text))

  const s1s2Source = Array.from({ length: 200 }, (_, i) => `a reasonably long source sentence ${i}`)
  const s1s2Clean = Array.from({ length: 200 }, (_, i) => `a plausible translated sentence ${i}`)
  check('G3 S1+S2 warns (repeated AND collapsed)', only(s1s2Source, damage(s1s2Clean, () => FILLER)) > 0)

  const s1s3Source = Array.from({ length: 200 }, (_, i) => `single line source sentence ${i}`)
  const s1s3Clean = Array.from({ length: 200 }, (_, i) => `single line translated text ${i}`)
  check(
    'G3 S1+S3 warns (repeated AND re-shaped)',
    only(s1s3Source, damage(s1s3Clean, () => 'identical two\nline translation!!')) > 0
  )

  const s2s3Source = Array.from({ length: 200 }, (_, i) => `a two line\nsource sentence ${i}`)
  const s2s3Clean = Array.from({ length: 200 }, (_, i) => `a two line\ntranslated text ${i}`)
  check('G3 S2+S3 warns (collapsed AND re-shaped)', only(s2s3Source, damage(s2s3Clean, (i) => `y${i}`)) > 0)

  // The hole the pair fixtures exposed: a file that is MOSTLY filler must still be caught, even
  // though the corrupt cues then dominate the length distribution.
  const mostly = Array.from({ length: 200 }, (_, i) => (i < 40 ? `a plausible translation ${i}` : FILLER))
  check('G3 a file that is mostly filler is still caught', only(s1s2Source, mostly) > 0)

  // ---- the false positives that would teach a user to ignore the warning ----
  const sound = Array.from({ length: 200 }, () => '♪')
  eq('G3 a file of repeated sound cues is not corruption', only(sound, sound.map(() => '♪')), 0)

  const repeatedSource = Array.from({ length: 200 }, (_, i) => (i % 2 === 0 ? 'Yes.' : `line ${i}`))
  const repeatedOutput = Array.from({ length: 200 }, (_, i) => (i % 2 === 0 ? 'כן.' : `שורה ${i}`))
  eq('G3 a legitimately repeated short phrase is not corruption', only(repeatedSource, repeatedOutput), 0)

  const untranslated = Array.from({ length: 200 }, (_, i) => `${i + 1}.`)
  eq('G3 cues left untranslated on purpose are excluded, not flagged', only(untranslated, untranslated), 0)

  // ---- the floor, and the guards ----
  const tinySource = Array.from({ length: 25 }, (_, i) => `a reasonably long source sentence ${i}`)
  eq(
    'G3 a file under the 30-cue floor is never judged',
    only(tinySource, tinySource.map(() => FILLER)),
    0
  )
  eq('G3 empty input produces nothing rather than throwing', scanTranslatedOutput('', '').length, 0)
  eq('G3 unparseable input produces nothing', scanTranslatedOutput('not a subtitle', '{}').length, 0)
  eq(
    'G3 an output missing half its cues is skipped, not guessed at',
    scanTranslatedOutput(srt(bad.source), srt(bad.output.slice(0, 100))).length,
    0
  )

  // ---- ASS, because the app translates it too ----
  const ass = (cues: string[]): string =>
    '[Script Info]\n\n[Events]\nFormat: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text\n' +
    cues
      .map((t) => `Dialogue: 0,0:00:01.00,0:00:02.00,Default,,0,0,0,,${t.replace(/\n/g, '\\N')}`)
      .join('\n')
  const assPair = cleanPair(200)
  eq('G3 a clean ASS pair is silent', scanTranslatedOutput(ass(assPair.source), ass(assPair.output)).length, 0)
  const assBad = [...assPair.output]
  for (let i = 60; i < 160; i++) assBad[i] = FILLER
  check('G3 the same fault is caught in ASS', scanTranslatedOutput(ass(assPair.source), ass(assBad)).length === 1)
}

section('G3b — the token report names the user\u2019s files (REP-1)')
{
  const engineReport = JSON.stringify(
    {
      timestamp: '2026-08-19T21:42:36.023737',
      mode: 'translate',
      model: 'gemini-3.5-flash-lite',
      output_file: 'C:\\temp\\1787164913314.srt',
      duration_seconds: 40.54,
      tokens: { prompt: 10926, thoughts: 0, output: 16413, total: 27339 },
      input_file: 'C:\\temp\\1787164913314.utf8.srt',
      target_language: 'Hebrew'
    },
    null,
    2
  )

  const rewritten = retargetTokenReport(engineReport, 'D:\\Movies\\Show.eng.srt', 'D:\\Movies\\Show_he.srt')
  const parsed = JSON.parse(rewritten) as Record<string, unknown>
  eq('G3b the output path is the file the user saved', parsed.output_file, 'D:\\Movies\\Show_he.srt')
  eq('G3b the input path is the file the user chose', parsed.input_file, 'D:\\Movies\\Show.eng.srt')
  eq('G3b the token counts are untouched', parsed.tokens, {
    prompt: 10926,
    thoughts: 0,
    output: 16413,
    total: 27339
  })
  eq('G3b every other field survives', parsed.target_language, 'Hebrew')
  eq('G3b no temp path is left anywhere in the file', /1787164913314/.test(rewritten), false)

  const noInput = JSON.parse(retargetTokenReport(engineReport, '', 'D:\\out.srt')) as Record<string, unknown>
  eq(
    'G3b an unknown source leaves the original value rather than guessing',
    noInput.input_file,
    'C:\\temp\\1787164913314.utf8.srt'
  )

  eq('G3b an unparseable report is returned untouched', retargetTokenReport('{oops', 'a', 'b'), '{oops')
  eq('G3b a JSON array is not treated as a report', retargetTokenReport('[1,2]', 'a', 'b'), '[1,2]')
}

section('G3c — the scan can never strand a finished job')
{
  // This runs on the path that delivers the terminal event, so every one of these must return an
  // empty list rather than throw. A run that ends with no `done` event is worse than any warning.
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'srt-gate-scan-'))
  const missing = path.join(dir, 'nope.srt')
  const empty = path.join(dir, 'empty.srt')
  const junk = path.join(dir, 'junk.srt')
  fs.writeFileSync(empty, '')
  fs.writeFileSync(junk, 'this is not a subtitle at all')

  eq('G3c no paths at all', scanOutputFiles('', ''), [])
  eq('G3c a missing source', scanOutputFiles(missing, junk), [])
  eq('G3c a missing output', scanOutputFiles(junk, missing), [])
  eq('G3c an empty output', scanOutputFiles(junk, empty), [])
  eq('G3c an unparseable pair', scanOutputFiles(junk, junk), [])
  eq('G3c a directory where a file was expected', scanOutputFiles(dir, junk), [])
}

section('G3d — alignment, fragment-heavy sources, abort copy (REP-32)')
{
  const srt = (cues: string[]): string =>
    cues
      .map((text, i) => {
        const s = i * 2
        const stamp = (sec: number): string =>
          `00:${String(Math.floor(sec / 60)).padStart(2, '0')}:${String(sec % 60).padStart(2, '0')},000`
        return `${i + 1}\n${stamp(s)} --> ${stamp(s + 1)}\n${text}\n`
      })
      .join('\n')

  /** Length-only pair: S1/S2/S3 stay quiet (distinct, proportional, one line). */
  function lengthPair(
    count: number,
    outLen: (i: number, srcLen: number) => number
  ): { source: string[]; output: string[] } {
    const source: string[] = []
    const output: string[] = []
    for (let i = 0; i < count; i++) {
      const sl = 12 + (i % 19) * 3
      source.push('S'.repeat(sl))
      output.push('T'.repeat(Math.max(1, outLen(i, sl))))
    }
    return { source, output }
  }

  const aligned = lengthPair(400, (_i, sl) => sl)
  eq(
    'G3d an aligned length pair is silent',
    scanTranslatedOutput(srt(aligned.source), srt(aligned.output)).length,
    0
  )

  const uniformSrc = Array.from({ length: 80 }, () => 'hello world')
  const uniformOut = Array.from({ length: 80 }, () => 'shalom olam!!')
  eq(
    'G3d uniform lengths (no variance) are treated as aligned',
    scanTranslatedOutput(srt(uniformSrc), srt(uniformOut)).length,
    0
  )

  const scramble = (i: number, sl: number): number => 12 + ((i * 7 + 3) % 19) * 3
  const late = lengthPair(400, (i, sl) => (i < 240 ? sl : scramble(i, sl)))
  const lateWarn = scanTranslatedOutput(srt(late.source), srt(late.output))
  G3_TIMING_PAIR = { source: srt(late.source), output: srt(late.output) }
  check('G3d late drift warns', lateWarn.length >= 1, `got ${lateWarn.length}`)
  if (lateWarn.length >= 1) {
    const w = lateWarn[0]
    check('G3d late drift is a timing warning', w.signals.includes('wrong timings'))
    check('G3d late drift names wrong timings', /wrong timings/i.test(w.message))
    check('G3d late drift starts in the scrambled half', w.from >= 180, `from ${w.from}`)
    check('G3d late drift does not accuse the aligned prefix', w.from > 50, `from ${w.from}`)
  }

  const early = lengthPair(400, (i, sl) => (i < 40 ? sl : scramble(i, sl)))
  const earlyWarn = scanTranslatedOutput(srt(early.source), srt(early.output))
  check('G3d early drift warns', earlyWarn.length >= 1, `got ${earlyWarn.length}`)
  if (earlyWarn.length >= 1) {
    check('G3d early drift is a timing warning', earlyWarn[0].signals.includes('wrong timings'))
    check('G3d early drift starts before the late-stretch fixture', earlyWarn[0].from < 180, `from ${earlyWarn[0].from}`)
  }

  const weak = lengthPair(400, (i) => 20 + (i % 3))
  eq(
    'G3d weak length correlation without fragments stays silent (SOL-63)',
    scanTranslatedOutput(srt(weak.source), srt(weak.output)).length,
    0
  )

  function fragPad(i: number, n: number): string {
    const stem = i % 2 === 0 ? 'this fragment continues without a stop ' : 'and the next cue starts lower '
    if (n <= stem.length) return stem.slice(0, Math.max(1, n))
    return stem.repeat(Math.ceil(n / stem.length)).slice(0, n)
  }
  const wholeFragSrc = Array.from({ length: 400 }, (_, i) => fragPad(i, 12 + (i % 19) * 3))
  const wholeFragOut = Array.from({ length: 400 }, (_, i) => 'T'.repeat(Math.max(1, scramble(i, 12 + (i % 19) * 3))))
  const wholeFragWarn = scanTranslatedOutput(srt(wholeFragSrc), srt(wholeFragOut))
  check(
    'G3d a fully drifted fragment-heavy file still warns',
    wholeFragWarn.length >= 1,
    `got ${wholeFragWarn.length}`
  )
  if (wholeFragWarn.length >= 1) {
    check('G3d whole-file fragment drift is a timing warning', wholeFragWarn[0].signals.includes('wrong timings'))
  }

  const pro = Array.from({ length: 80 }, (_, i) => {
    if (i % 28 === 1) return 'on the next line we finish.'
    if (i % 28 === 0) return 'This sentence continues'
    return `A complete sentence number ${i}.`
  })
  eq('G3d a professionally punctuated source is silent', sourceFragmentNote(srt(pro)), null)

  const youtube = Array.from({ length: 80 }, (_, i) =>
    i % 2 === 0 ? `this fragment continues without a stop ${i}` : `and the next cue starts lower ${i}`
  )
  const ytNote = sourceFragmentNote(srt(youtube))
  check('G3d a fragment-heavy source produces a log note', ytNote !== null)
  if (ytNote) {
    check('G3d the note names mid-sentence breaks', /mid-sentence/i.test(ytNote))
    check('G3d the note tells them to re-segment', /re-segment/i.test(ytNote))
    check('G3d the note does not block by promising a model fix', !/try a stronger|use a stronger/i.test(ytNote))
  }
  eq(
    'G3d a short fragment-heavy file is not judged',
    sourceFragmentNote(srt(youtube.slice(0, 10))),
    null
  )

  // Text-free shape copies of the reported files: every letter is replaced by one of the same script
  // and case, so cue numbers, timings, lengths, line breaks and punctuation are what the scanners saw.
  const sanity = (name: string): string =>
    fs.readFileSync(path.join(process.cwd(), 'scripts', 'gates', 'fixtures', 'sanity', name), 'utf-8')
  const sisters = scanTranslatedOutput(sanity('bad-sisters.source.srt'), sanity('bad-sisters.he.srt'))
  eq('G3d Bad Sisters stays silent (the false-positive that matters)', sisters.length, 0)
  eq('G3d Bad Sisters is not flagged as fragment-heavy', sourceFragmentNote(sanity('bad-sisters.source.srt')), null)
  const srcText = sanity('boeing.source.srt')
  const lite = scanTranslatedOutput(srcText, sanity('boeing-flash-lite.he.srt'))
  check(
    'G3d Boeing flash-lite is a timing warning',
    lite.some((w) => w.signals.includes('wrong timings')),
    lite.map((w) => `${w.from}-${w.to} ${w.signals.join('+')}`).join('; ') || 'nothing'
  )
  check('G3d Boeing source is fragment-heavy', sourceFragmentNote(srcText) !== null)
  const worse = scanTranslatedOutput(srcText, sanity('boeing-flash-3.5.he.srt'))
  check(
    'G3d Boeing flash 3.5 is a timing warning',
    worse.some((w) => w.signals.includes('wrong timings')),
    worse.map((w) => `${w.from}-${w.to} ${w.signals.join('+')}`).join('; ') || 'nothing'
  )
  check(
    'G3d flash 3.5 drift starts earlier than flash-lite',
    lite.length >= 1 && worse.length >= 1 && worse[0].from < lite[0].from,
    `3.5 from ${worse[0]?.from}, lite from ${lite[0]?.from}`
  )
}

// ── G4: the run panel (REP-2/3/12, MAN-1/6/8) ──────────────────────────────────

section('G4 — collapsing a repeated block, and never hiding a line')
{
  /** What the panel actually shows, top to bottom. */
  const shown = (rows: LogRow[]): string[] => {
    const out: string[] = []
    for (const r of rows) {
      if (r.kind === 'block') out.push(...r.lines)
      else out.push(`<${r.hiddenLines} hidden>`)
    }
    return out
  }
  /**
   * The invariant the whole feature stands on: collapsing may only ever remove text that is
   * still on screen somewhere. An error folded away into a counter is worse than repetition.
   */
  const nothingHidden = (name: string, stream: string[], rows: LogRow[]): void => {
    const visible = new Set(shown(rows))
    const missing = [...new Set(stream)].filter((l) => !visible.has(l))
    check(
      `G4 ${name} — every distinct line still visible`,
      missing.length === 0,
      `missing: ${missing.slice(0, 3).join(' | ')}`
    )
  }

  // 1. the two cases the plan's first revision got wrong
  {
    const abab = ['A', 'B', 'A', 'B']
    const rows = feedLog(abab)
    eq('G4 A B A B collapses to one two-line block', shown(rows), ['A', 'B'])
    eq('G4 A B A B counts two', rows.length === 1 && rows[0].kind === 'block' ? rows[0].count : -1, 2)
    nothingHidden('A B A B', abab, rows)

    const abac = ['A', 'B', 'A', 'C']
    const rowsC = feedLog(abac)
    eq('G4 A B A C stays four rows', shown(rowsC), abac)
    nothingHidden('A B A C', abac, rowsC)
  }

  // 2. a progress line whose number moves must never collapse: if it does, progress is hidden
  {
    const stream = Array.from({ length: 40 }, (_, i) => `Translating batch 1: ${i + 1}/300 lines`)
    const rows = feedLog(stream)
    eq('G4 a changing progress line never collapses', shown(rows), stream)
    check(
      'G4 no counter appears on distinct lines',
      rows.every((r) => r.kind === 'block' && r.count === 1)
    )
  }

  // 3. the measured flood: an 11-line frame redrawn 900 times (REP-12)
  {
    const frame = Array.from({ length: 11 }, (_, i) => `engine message ${i + 1}`)
    const stream: string[] = []
    for (let i = 0; i < 900; i++) stream.push(...frame)
    const rows = feedLog(stream)
    eq('G4 9,900 lines collapse to one block', rows.length, 1)
    eq('G4 the block is the 11 real messages', shown(rows), frame)
    eq('G4 the counter is exact', rows[0].kind === 'block' ? rows[0].count : -1, 900)
    nothingHidden('the 9,900-line flood', stream, rows)

    // and the proof that a one-line check could not have done this
    let naive = 0
    let previous = ''
    for (const l of stream) {
      if (l !== previous) naive++
      previous = l
    }
    eq('G4 a consecutive-duplicate check would have kept every line', naive, stream.length)
  }

  // 4. the shape the engine actually produces: a message history that GROWS and is redrawn
  {
    const msgs = Array.from({ length: 12 }, (_, i) => `history line ${i + 1}`)
    const draws = [2, 2, 2, 2, 3, 2, 2, 2, 2, 2, 2, 3]
    const stream: string[] = []
    draws.forEach((d, i) => {
      for (let k = 0; k < d; k++) stream.push(...msgs.slice(0, i + 1))
    })
    eq('G4 the growing-history fixture is 173 lines', stream.length, 173)
    const rows = feedLog(stream)
    eq('G4 173 lines render as the 12 distinct messages', shown(rows), msgs)
    check(
      'G4 the block carries a climbing counter',
      rows.length === 1 && rows[0].kind === 'block' && rows[0].count > 1
    )
    nothingHidden('the growing history', stream, rows)

    // A redraw that is still arriving shows as ordinary lines until it completes — deliberately,
    // because the alternative is holding lines back on the chance that they will repeat.
    const partial = feedLog([...stream, msgs[0], msgs[1]])
    eq('G4 an in-flight redraw is visible, not withheld', shown(partial).slice(-2), [msgs[0], msgs[1]])
  }

  // 5. a repeated message that recurs with different text between occurrences
  {
    const stream = ['X', 'X', 'X', 'Y', 'X', 'X', 'X']
    const rows = feedLog(stream)
    eq('G4 an interrupted repeat keeps both texts, in order', shown(rows), ['X', 'Y', 'X'])
    nothingHidden('X Y X', stream, rows)
  }

  // 6. REP-7 was declined: the AFC notice must survive
  {
    const afc = 'Direct use of automatic function calling (AFC) is not recommended'
    const frame = ['Validating token size...', 'Token size validated. Translating...']
    const stream = [afc]
    for (let i = 0; i < 50; i++) stream.push(...frame)
    const rows = feedLog(stream)
    check('G4 the AFC notice is still visible after a flood', shown(rows).includes(afc))
    eq('G4 the flood around it still collapses', shown(rows), [afc, ...frame])
  }
}

section('G4b — the cap keeps the start-up block and says what it hid')
{
  const stream = Array.from({ length: 3000 }, (_, i) => `distinct line ${i}`)
  const rows = feedLog(stream)
  const blocks = rows.filter((r) => r.kind === 'block') as LogBlock[]
  const gaps = rows.filter((r) => r.kind === 'gap') as LogGap[]

  eq('G4b exactly one gap marker', gaps.length, 1)
  eq('G4b the head is kept, oldest first', blocks[0].lines[0], 'distinct line 0')
  eq('G4b the newest line survives', blocks[blocks.length - 1].lines[0], 'distinct line 2999')
  eq('G4b retained lines are head + tail', blocks.length, HEAD_LINES + TAIL_LINES)
  eq('G4b the marker counts what went', gaps[0].hiddenLines, 3000 - HEAD_LINES - TAIL_LINES)

  // The gap keeps its identity as more is hidden, so the row under the cursor does not jump.
  let more = rows
  for (let i = 3000; i < 3010; i++) more = appendLogLine(more, `distinct line ${i}`)
  const gap2 = more.find((r) => r.kind === 'gap') as LogGap
  eq('G4b the gap keeps its React key', gap2.seq, gaps[0].seq)
  eq('G4b and grows', gap2.hiddenLines, 3010 - HEAD_LINES - TAIL_LINES)
  eq('G4b the head is still the head', (more[0] as LogBlock).lines[0], 'distinct line 0')

  // Row identity must be unique, or React reuses the wrong DOM node.
  eq('G4b every row has a distinct key', new Set(more.map((r) => r.seq)).size, more.length)
}

// ── G5: sampling parameters and the fields that hold them (REP-4/5/6) ──────────

section('G5b — where Google’s sampling deprecation begins')
{
  const accepts = (id: string): boolean => modelCapabilities(id).acceptsSamplingParams

  // Everything before the boundary is unaffected and must keep working exactly as it did.
  eq('G5b 2.0', accepts('gemini-2.0-flash'), true)
  eq('G5b 2.5', accepts('gemini-2.5-flash'), true)
  eq('G5b 2.5 Pro', accepts('gemini-2.5-pro'), true)
  eq('G5b 3.1 Flash-Lite', accepts('gemini-3.1-flash-lite'), true)
  eq('G5b 3.1 Pro', accepts('gemini-3.1-pro'), true)

  // The boundary runs THROUGH 3.5, which is why this cannot be a major-version test.
  eq('G5b 3.5 Flash is not named', accepts('gemini-3.5-flash'), true)
  eq('G5b 3.5 Flash with the API prefix is the same model', accepts('models/gemini-3.5-flash'), true)
  eq('G5b 3.5 Flash-Lite is named', accepts('gemini-3.5-flash-lite'), false)
  eq('G5b 3.6 Flash is named', accepts('gemini-3.6-flash'), false)
  eq('G5b 3.7 Flash came after it', accepts('gemini-3.7-flash'), false)

  // At the boundary the exemption is an allowlist, not "anything that is not Lite". Google
  // names Flash-Lite and omits Flash; it says nothing at all about any other 3.5 model, and
  // silence is not permission. 3.5 Pro is reachable today — it is in SUSPICIOUS_MODEL_IDS, so
  // a stored profile can still hold it, and M1 only flags such an id rather than replacing it.
  eq('G5b 3.5 Pro is not exempt just because it is not Lite', accepts('gemini-3.5-pro'), false)
  eq('G5b nor is a 3.5 family we have never seen', accepts('gemini-3.5-ultra'), false)
  eq('G5b nor a new variant of the exempt model', accepts('gemini-3.5-flash-preview-11-2026'), false)

  // Versions are compared as numbers. As text, "3.10" sorts beside "3.1" and a future model
  // would silently be handed parameters that fail the request.
  eq('G5b a future 3.10', accepts('gemini-3.10-flash'), false)
  eq('G5b a future 4.x', accepts('gemini-4.0-flash'), false)

  // Unknown means future, and future means rejected. Guessing this way round costs a control
  // that does nothing; guessing the other way costs every run.
  eq('G5b an alias that follows the model line forwards', accepts('gemini-flash-latest'), false)
  eq('G5b an unversioned id', accepts('gemini-exp-1206'), false)
  eq('G5b something that is not Gemini at all', accepts('gpt-4o'), false)
  eq('G5b nothing selected', accepts(''), false)
  // A live or hand-stored id can contain a version token without being a canonical Gemini
  // model id. Sampling's unknown default is withhold; substring matching must not override it.
  eq('G5b a noncanonical id with an embedded version is still unrecognised', accepts('gemini-experimental-2.5-flash'), false)
  eq(
    'G5b thinking still follows the engine substring for that id',
    modelCapabilities('gemini-experimental-2.5-flash').thinking,
    'budget'
  )

  // Adding this capability must not have disturbed the ones already there.
  eq('G5b thinking is unchanged for 2.5', modelCapabilities('gemini-2.5-pro').thinking, 'budget')
  eq('G5b thinking is unchanged for 3.x', modelCapabilities('gemini-3.6-flash').thinking, 'level')
  eq('G5b transcription is unchanged', modelCapabilities('gemini-3.6-flash').supportsTranscription, true)

  eq('G5b 3.x defaults', samplingDefaults('gemini-3.1-flash-lite'), { temperature: 1.0, topP: 0.95 })
  eq('G5b 2.x defaults', samplingDefaults('gemini-2.5-flash'), { temperature: 0.3, topP: 0.8 })
  eq('G5b a dated 2.5 preview is not a 3.x model', samplingDefaults('gemini-2.5-flash-preview-03-25'), {
    temperature: 0.3,
    topP: 0.8
  })
}

section('G5c — a number field can be typed into (REP-4)')
{
  const temp: NumberFieldRules = { min: 0.05, max: 2, step: 0.05 }
  const topK: NumberFieldRules = { min: 1, max: 100, allowEmpty: true }
  const budget: NumberFieldRules = { min: 128, max: 32768 }

  /** Every intermediate the browser reports while a string is typed left to right. */
  const typing = (text: string, rules: NumberFieldRules): (number | null)[] =>
    text.split('').map((_, i) => valueWhileTyping(text.slice(0, i + 1), rules))

  // The reported defect, as a sequence. `0` and `0.` are below the minimum and commit
  // nothing — correcting them is what ate the caret — while `0.8` is a real value on the way
  // to `0.85` and is committed as it passes, so nothing is lost if the field never blurs.
  eq('G5c typing 0.85 into a 0.05-minimum field', typing('0.85', temp), [null, null, 0.8, 0.85])
  eq('G5c typing 512 into a 128-minimum field', typing('512', budget), [null, null, 512])
  eq('G5c an in-range prefix commits as it goes', typing('40', topK), [4, 40])

  // A number input reports '' for a half-typed value it cannot parse — `0.` being the one
  // that matters. It must be held, never turned into a value.
  eq('G5c the unparseable intermediate commits nothing', valueWhileTyping('', temp), null)
  eq('G5c and neither does a bare minus', valueWhileTyping('-', temp), null)
  eq('G5c out of range is held, not clamped', valueWhileTyping('9', temp), null)
  eq('G5c above the maximum is held too', valueWhileTyping('150', topK), null)

  // Correction happens once, on the way out.
  eq('G5c blur clamps to the maximum', valueOnBlur('9', temp, 1), 2)
  eq('G5c blur clamps to the minimum', valueOnBlur('0.01', temp, 1), 0.05)
  eq('G5c blur keeps a good value', valueOnBlur('0.85', temp, 1), 0.85)
  eq('G5c blur rounds a decimal field to two places', valueOnBlur('0.8549', temp, 1), 0.85)
  eq('G5c blur rounds an integer field rather than truncating', valueOnBlur('2.6', topK, 1), 3)

  // Clearing a field: allowed for Top-K, and otherwise a no-op rather than a silent edit.
  // The old field wrote `min` here, so clearing Thinking Budget on 2.5 Pro to retype it and
  // then clicking away changed the setting to 128 without anyone choosing that.
  eq('G5c an empty optional field means no value', valueOnBlur('', topK, 40), null)
  eq('G5c an empty required field keeps what it had', valueOnBlur('', budget, 512), 512)
  eq('G5c text that is not a number keeps what it had', valueOnBlur('abc', temp, 0.7), 0.7)
  eq('G5c whitespace is not a value', valueOnBlur('   ', budget, 512), 512)

  // Regression: the three fields that always worked must keep working, including the
  // integer ones that have no step at all.
  eq('G5c batch size still commits while typing', typing('100', { min: 1, max: 1000 }), [1, 10, 100])
  eq('G5c resume context accepts zero', valueWhileTyping('0', { min: 0, max: 1000 }), 0)
  eq('G5c and blur leaves it alone', valueOnBlur('0', { min: 0, max: 1000 }, 50), 0)
}

section('G6 — an extracted track is named after itself, not after the target (REP-8)')
{
  const track = (
    index: number,
    lang: string,
    isImage = false
  ): SubtitleTrack => ({ index, lang, name: `Track ${index}`, codec: isImage ? 'hdmv_pgs_subtitle' : 'subrip', isImage })

  const video = 'C:\\Media\\Lone.Survivor.2013.UHD.BluRay.REMUX.mkv'
  const stem = 'Lone.Survivor.2013.UHD.BluRay.REMUX'

  // The reported file: English and Spanish PGS, translating into Hebrew. Before per-track
  // extraction existed, the only reachable track was one whose language equalled the target,
  // which is the sole reason naming the file after the target ever looked right. Opening the
  // feature is what breaks that, so the two land together.
  const reported = [track(2, 'en', true), track(3, 'es', true)]
  eq('G6 an English PGS track is not named after Hebrew', extractedTrackName(video, reported[0], reported), `${stem}_en.sup`)
  eq('G6 the Spanish one carries its own language too', extractedTrackName(video, reported[1], reported), `${stem}_es.sup`)

  // Type is already encoded by the extension, so a text and an image track of the same
  // language do not collide and neither needs an index.
  const mixed = [track(0, 'en'), track(2, 'en', true)]
  eq('G6 a text track of the same language', extractedTrackName(video, mixed[0], mixed), `${stem}_en.srt`)
  eq('G6 does not collide with the image one', extractedTrackName(video, mixed[1], mixed), `${stem}_en.sup`)

  // The narrow real collision: two English PGS streams, full and SDH, as Blu-ray remuxes
  // commonly carry. The first keeps the plain name; later ones carry their index.
  const twoEnglish = [track(2, 'en', true), track(3, 'en', true)]
  eq('G6 the first of two alike tracks keeps the plain name', extractedTrackName(video, twoEnglish[0], twoEnglish), `${stem}_en.sup`)
  eq('G6 the second is distinguished by its index', extractedTrackName(video, twoEnglish[1], twoEnglish), `${stem}_en_3.sup`)

  // An untagged track shows '—' in the panel and would otherwise be saved as `..._.srt`.
  const untagged = [track(1, '')]
  eq('G6 an untagged track falls back to its index', extractedTrackName(video, untagged[0], untagged), `${stem}_track1.srt`)

  // Only the last extension is dropped, so a release name full of dots survives intact.
  eq('G6 a POSIX path keeps only the file name', extractedTrackName('/home/u/My Film (2019).mkv', reported[0], reported), 'My Film (2019)_en.sup')
  eq('G6 a bare file name needs no directory', extractedTrackName('clip.mkv', reported[0], reported), 'clip_en.sup')

  // The translated-subtitle save shares this convention — that is why it is one helper.
  eq('G6 the save path builds the same shape', companionName('C:\\Subs\\Pachinko.S01E01.eng.srt', 'he', '.srt'), 'Pachinko.S01E01.eng_he.srt')
  eq('G6 an ASS job keeps its format', companionName('/x/Show.ass', 'he', '.ass'), 'Show_he.ass')
  eq('G6 and a run with no source path still proposes something', companionName('', 'he', '.srt'), 'subtitle_he.srt')
}

section('G7 — ffmpeg progress is read, never invented (REP-11)')
{
  // The format is ffmpeg's `-progress` output: blocks of key=value ending in progress=continue,
  // or progress=end on the last one. A read has to survive several blocks arriving in one chunk,
  // because the process writes faster than the main process reads.
  const block = (t: string, state = 'continue'): string =>
    `frame=120\nfps=25\nbitrate=N/A\ntotal_size=4096\nout_time_us=${Math.round(
      parseFloat(t) * 1_000_000
    )}\nout_time_ms=${Math.round(parseFloat(t) * 1_000_000)}\nspeed=12x\nprogress=${state}\n`

  eq('G7 a single block reports its position', readProgressChunk(block('12.5')).outTimeSec, 12.5)
  eq('G7 and is not finished', readProgressChunk(block('12.5')).ended, false)
  // The LAST block in a chunk is the current one; the earlier ones are already stale.
  eq(
    'G7 several blocks at once report the newest',
    readProgressChunk(block('10') + block('20') + block('30')).outTimeSec,
    30
  )
  eq('G7 progress=end is recognised', readProgressChunk(block('60', 'end')).ended, true)
  eq('G7 a chunk with no timestamp reports none', readProgressChunk('frame=1\nfps=0\n').outTimeSec, null)
  eq('G7 an empty chunk is harmless', readProgressChunk('').outTimeSec, null)

  // out_time is the unambiguous spelling and wins when both are present. out_time_ms is
  // deliberately never read: it has carried MICROseconds for years, a bug kept for
  // compatibility, so trusting it would report a 90-minute film as finishing in 5 seconds.
  eq(
    'G7 the timestamp spelling is preferred',
    readProgressChunk('out_time_us=1000000\nout_time=00:01:00.000000\nprogress=continue').outTimeSec,
    60
  )
  eq(
    'G7 the millisecond spelling is ignored',
    readProgressChunk('out_time_ms=90000000\nprogress=continue').outTimeSec,
    null
  )

  // A pipe read can end anywhere, including mid-number. `execFfmpeg` carries the remainder
  // to the next chunk for exactly this reason: half of `out_time_us=10000000` parses as a
  // valid 1 second, which is not a missing report but a wrong one — and wrong in the only
  // direction a progress bar must never move. The reader below sees whole lines only.
  const twoBlocks = block('10') + block('30')
  const cut = twoBlocks.lastIndexOf('out_time_us=') + 16 // four digits into the second value
  eq(
    'G7 a chunk cut mid-number would report a time that never happened',
    readProgressChunk(twoBlocks.slice(0, cut)).outTimeSec,
    0.003
  )
  eq(
    'G7 …so trimming to the last line break reports the previous position instead',
    readProgressChunk(twoBlocks.slice(0, twoBlocks.lastIndexOf('\n', cut) + 1)).outTimeSec,
    10
  )

  eq('G7 timestamps carry hours', parseTimestamp('01:02:03.500000'), 3723.5)
  eq('G7 and fractions', parseTimestamp('00:00:00.250000'), 0.25)
  // N/A appears before ffmpeg has decoded anything. Reading it as zero would show a 0% bar
  // for a file that has not started, which is the very state this feature exists to disprove.
  eq('G7 N/A is not a time', parseTimestamp('N/A'), null)
  eq('G7 nor is nothing', parseTimestamp(''), null)
  eq('G7 nor is a bare number', parseTimestamp('12'), null)

  // Duration comes from ffprobe and is allowed to be missing: streams and some remuxes
  // genuinely will not say. That costs a percentage, never an error.
  eq('G7 a duration is read', durationFromProbe('5405.280000\n'), 5405.28)
  eq('G7 an unknown duration is null', durationFromProbe('N/A\n'), null)
  eq('G7 as is an empty answer', durationFromProbe(''), null)
  eq('G7 and a zero one', durationFromProbe('0.000000'), null)

  eq('G7 the percentage is whole', percentOf(2702.64, 5405.28), 50)
  eq('G7 it starts at zero', percentOf(0, 5405.28), 0)
  // Capped below 100 while the process is alive: ffmpeg routinely reports a position at or
  // past the nominal duration near the end, and a bar reading 100% for another minute is
  // exactly the "it is stuck" complaint in a different costume.
  eq('G7 it never reaches 100 while running', percentOf(5405.28, 5405.28), 99)
  eq('G7 nor beyond it', percentOf(9999, 5405.28), 99)
  eq('G7 no duration means no percentage', percentOf(120, null), null)
  eq('G7 a nonsense duration means the same', percentOf(120, 0), null)
}

section('G8b — a run that stops getting anywhere is ended (REP-2)')
{
  /** The measured storm: an alternating block, in more than one wording, forever. */
  const STORM = [
    '\x1b[F\x1b[K\x1b[F\x1b[KTranscribing: |████| 0% (00:00:00,000/00:00:10,001) gemini-2.5-flash-lite',
    'Transcribing audio segment 00:00 to 00:10.',
    "An unexpected error occurred: 400 invalid_argument. {'error': {'code': 400, 'message': 'api key not valid. please pass a valid api key.', 'status': 'invalid_argument'}}. Retrying immediately...",
    'Transcribing: |████| 0% (00:00:00,000/00:00:10,001) gemini-2.5-flash-lite',
    "An unexpected error occurred: 401 UNAUTHENTICATED. {'error': {'code': 401, 'reason': 'ACCESS_TOKEN_TYPE_UNSUPPORTED'}}. Retrying immediately..."
  ]

  // The rule the first design got wrong, and the reason this is a gate rather than a manual
  // check: no two error lines are ever adjacent, so a consecutive-identical counter never
  // reaches 2 — let alone N — against this exact input.
  {
    let adjacent = 0
    for (let i = 1; i < 400; i++) if (STORM[i % STORM.length] === STORM[(i - 1) % STORM.length]) adjacent++
    eq('G8b no line in the storm ever repeats consecutively', adjacent, 0)
  }
}

section('G8c — an unreachable key is not an invalid key (MAN-4)')
{
  // The persisted verdict is where MAN-4 began: every failure, including a DNS error, was
  // stored as `false` — the identical value a rejected key gets.
  eq('G8c a rejected key is rejected', classifyFetchFailure('400 api key not valid. please pass a valid api key.', false).verdict, 'rejected')
  eq('G8c so is a 401', classifyFetchFailure('401 UNAUTHENTICATED', false).verdict, 'rejected')
  eq('G8c and a 403', classifyFetchFailure('PERMISSION_DENIED: 403', false).verdict, 'rejected')
  eq('G8c a DNS failure proves nothing about the key', classifyFetchFailure('getaddrinfo ENOTFOUND generativelanguage.googleapis.com', false).verdict, 'unchecked')
  eq('G8c nor does a timeout', classifyFetchFailure('', true).verdict, 'unchecked')
  // A 429 means the key is real, working, and merely busy. Calling that invalid would demote
  // a perfectly good key in the spawn ranking.
  eq('G8c nor does exhausted quota', classifyFetchFailure('429 RESOURCE_EXHAUSTED: quota', false).verdict, 'unchecked')
  eq('G8c and an unrecognised failure defaults to proving nothing', classifyFetchFailure('something went sideways', false).verdict, 'unchecked')
  check(
    'G8c the offline message does not accuse the key',
    !/invalid/i.test(classifyFetchFailure('getaddrinfo ENOTFOUND', false).error),
    classifyFetchFailure('getaddrinfo ENOTFOUND', false).error
  )

  // The three keys of the report, offline: none rejected, none checked.
  const offline = ['unchecked', 'unchecked', 'unchecked'] as const
  const counts = countKeyStates([...offline])
  eq('G8c nothing is counted as invalid', counts.rejected, 0)
  const headline = keyHeadline(counts, null)
  check('G8c and the headline does not say "no valid keys"', !/no valid keys/i.test(headline.text), headline.text)
  check('G8c nor calls anything invalid', !/invalid/i.test(headline.text), headline.text)
  // Both spellings are natural English and both appear — "None of your keys could be checked"
  // in the plural, "This key could not be checked" in the singular. What is being asserted is
  // that the sentence is about the CHECK, which is the fact, rather than about the keys.
  check('G8c it says the check failed, not the keys', /be checked/i.test(headline.text), headline.text)
  // One key offline is the same fact in the singular, and the old copy got that wrong too.
  check(
    'G8c a single unreachable key reads in the singular',
    /^This key could not be checked/.test(keyHeadline(countKeyStates(['unchecked']), null).text),
    keyHeadline(countKeyStates(['unchecked']), null).text
  )

  // The sentence that was ungrammatical for a list and wrong for a reserve.
  eq(
    'G8c two active keys are described in the plural',
    uncheckedNote([0, 1], [0, 1]),
    'Keys 1 and 2 could not be checked, and a run would use them.'
  )
  eq(
    'G8c a lone reserve is described as a reserve',
    uncheckedNote([2], [0, 1]),
    'Key 3 could not be checked; it is a reserve, so runs are unaffected.'
  )
  check(
    'G8c a mixed list splits rather than mislabelling either',
    uncheckedNote([0, 2], [0, 1]) ===
      'Key 1 could not be checked, and a run would use it. Key 3 could not be checked; it is a reserve, so runs are unaffected.',
    uncheckedNote([0, 2], [0, 1])
  )
  eq('G8c the list grammar', listKeyNumbers([0, 1, 2]), '1, 2 and 3')

  // The ordinary cases still read as they did.
  eq('G8c a valid key still reports valid', keyStateOf(true, true), 'valid')
  eq('G8c a rejected one still earns its ✗', keyStateOf(true, false), 'rejected')
  eq('G8c an empty slot is not a state', keyStateOf(false, null), 'blank')
  check(
    'G8c a good check still reads as before',
    keyHeadline(countKeyStates(['valid', 'valid', 'rejected']), 12).text === '✓ 2 of 3 keys valid — 12 models available.',
    keyHeadline(countKeyStates(['valid', 'valid', 'rejected']), 12).text
  )
  eq('G8c and a genuinely rejected set still says so', keyHeadline(countKeyStates(['rejected']), null).tone, 'bad')
}

section('G8d — a check that proves nothing does not undo what was proven (FP7-V01)')
{
  const queried = (n: number): SlotFetchResult[] =>
    Array.from({ length: n }, (_, slot) => ({ slot, queried: true, ok: false, ids: [] }))
  const prior = (valid: boolean | null, error = '', sameKey = true): PriorVerdict => ({ valid, error, sameKey })
  const unchecked: KeyCheck = { valid: null, error: 'Could not reach Google. Check your internet connection and try again.' }

  // The defect: `false` is the one verdict that REMOVES a key from the pool, so erasing it
  // without contrary evidence changes what a run does. Asserted through the ranking rather
  // than through the field, because the ranking is what the defect was actually about.
  const rank = (valid: boolean | null): number[] =>
    orderKeySlots([{ index: 0, valid, tier: 'free' }, { index: 1, valid: null, tier: 'free' }])
  eq('G8d a proven-dead key is dropped from the pool', JSON.stringify(rank(false)), JSON.stringify([1]))
  eq('G8d and an unchecked one is not', JSON.stringify(rank(null)), JSON.stringify([0, 1]))

  const kept = keepProvenRejections([unchecked], queried(1), [prior(false, 'Invalid API key.')])
  eq('G8d so an offline check keeps the rejection', kept[0].valid, false)
  eq('G8d with the refusal, not the network error, beside it', kept[0].error, 'Invalid API key.')
  eq(
    'G8d and the key stays out of the pool',
    JSON.stringify(rank(kept[0].valid)),
    JSON.stringify([1])
  )

  // The asymmetry, and the reason for it: retaining `true` would answer a failed check with
  // "✓ N of N keys valid" — MAN-4's own report with the polarity flipped.
  const decayed = keepProvenRejections([unchecked], queried(1), [prior(true, '')])
  eq('G8d a valid verdict is allowed to decay to unchecked', decayed[0].valid, null)
  check(
    'G8d because retaining it would claim a check that did not happen',
    /be checked/i.test(keyHeadline(countKeyStates([keyStateOf(true, decayed[0].valid)]), null).text),
    keyHeadline(countKeyStates([keyStateOf(true, decayed[0].valid)]), null).text
  )
  eq(
    'G8d and it costs nothing operationally — both are usable',
    JSON.stringify(rank(decayed[0].valid)),
    JSON.stringify([0, 1])
  )

  // Evidence always wins, in both directions.
  eq(
    'G8d a fresh rejection overwrites a stored pass',
    keepProvenRejections([{ valid: false, error: 'Invalid API key.' }], queried(1), [prior(true)])[0].valid,
    false
  )
  eq(
    'G8d and a fresh pass clears a stored rejection',
    keepProvenRejections([{ valid: true, error: '' }], queried(1), [prior(false, 'Invalid API key.')])[0].valid,
    true
  )
  eq(
    'G8d with its error',
    keepProvenRejections([{ valid: true, error: '' }], queried(1), [prior(false, 'Invalid API key.')])[0].error,
    ''
  )

  // A retained verdict must never outlive the credential it was about.
  eq(
    'G8d an edited key does not inherit the old key\u2019s rejection',
    keepProvenRejections([unchecked], queried(1), [prior(false, 'Invalid API key.', false)])[0].valid,
    null
  )
  eq(
    'G8d and an emptied slot does not either',
    keepProvenRejections([{ valid: null, error: '' }], [{ slot: 0, queried: false, ok: false, ids: [] }], [
      prior(false, 'Invalid API key.')
    ])[0].valid,
    null
  )
  eq(
    'G8d a slot with nothing stored is unaffected',
    keepProvenRejections([unchecked], queried(1), [prior(null)])[0].valid,
    null
  )
  eq(
    'G8d as is one with no stored entry at all',
    keepProvenRejections([unchecked], queried(1), [])[0].valid,
    null
  )

  // MAN-4's actual report: three keys, all previously valid, one network outage. This is the
  // case the fix must not disturb, and the one that rules out merging every verdict.
  const outage = keepProvenRejections(
    [unchecked, unchecked, unchecked],
    queried(3),
    [prior(true), prior(true), prior(true)]
  )
  check('G8d MAN-4 unchanged: nothing is branded invalid', outage.every((r) => r.valid !== false))
  check('G8d MAN-4 unchanged: nothing claims to be valid either', outage.every((r) => r.valid === null))
  const outageStates = outage.map((r) => keyStateOf(true, r.valid))
  eq('G8d MAN-4 unchanged: the headline still reports on the check', keyHeadline(countKeyStates(outageStates), null).tone, 'warn')

  // The mixed list, which is where a blanket merge and this rule differ most visibly.
  const mixed = keepProvenRejections(
    [unchecked, unchecked],
    queried(2),
    [prior(true), prior(false, 'Invalid API key.')]
  )
  eq('G8d a mixed list keeps only the rejection', JSON.stringify(mixed.map((r) => r.valid)), JSON.stringify([null, false]))
  eq(
    'G8d so the good key leads and the dead one is gone',
    JSON.stringify(
      orderKeySlots([
        { index: 0, valid: mixed[0].valid, tier: 'free' },
        { index: 1, valid: mixed[1].valid, tier: 'free' }
      ])
    ),
    JSON.stringify([0])
  )
  eq(
    'G8d an all-rejected set is empty, not a last-resort pool',
    JSON.stringify(orderKeySlots([{ index: 0, valid: false, tier: 'free' }])),
    JSON.stringify([])
  )
}

section('G8e — a result may not be applied to keys it was not learned from (FP7-R01)')
{
  // Everything a check produces is addressed by SLOT INDEX and carries no trace of the key
  // it came from, so applying it to a changed key set writes one credential's verdict, error
  // and model evidence onto another.
  const asked = ['AIzaKEY-one', 'AIzaKEY-two', '']

  check('G8e an untouched snapshot is applied', !keySnapshotChanged(asked, [...asked]))
  check('G8e an edited key discards the result', keySnapshotChanged(asked, ['AIzaKEY-one', 'AIzaKEY-CHANGED', '']))
  check('G8e so does editing the one being checked first', keySnapshotChanged(asked, ['AIzaKEY-NEW', 'AIzaKEY-two', '']))
  check('G8e a cleared key discards it', keySnapshotChanged(asked, ['AIzaKEY-one', '', '']))
  check('G8e an added key discards it', keySnapshotChanged(asked, [...asked, 'AIzaKEY-three']))
  // Removal is the sharpest case: every slot above it renumbers, so a late write lands
  // wholesale on the wrong keys.
  check('G8e and a removed key discards it', keySnapshotChanged(asked, ['AIzaKEY-two', '']))
  // Reordering is not detectable by length, and it is exactly what "by slot index" breaks on.
  check('G8e reordering the same keys still discards', keySnapshotChanged(asked, ['AIzaKEY-two', 'AIzaKEY-one', '']))
  // Not over-eager: discarding a minute of checking needs a reason. A tier is not part of
  // what a check learns, is not persisted by it, and is not ranked on.
  check('G8e an empty configuration compares equal to itself', !keySnapshotChanged([], []))
  check('G8e and a whitespace difference is a real difference', keySnapshotChanged([' k'], ['k']))
}

section('G9a — the console log keeps both ends of a run it has to cut (REP-1/REP-3)')
{
  // Tiny limits so the cut is reached in a few lines. The policy is a function of the limits,
  // not of the defaults, which is the whole reason they are a parameter.
  const chunks: string[] = []
  const log = createConsoleLog((c) => chunks.push(c), { headBytes: 40, tailBytes: 40 })
  for (let i = 1; i <= 60; i++) log.write(`line ${i}`)
  log.close()
  const file = chunks.join('')

  // The head streams as it happens, so it is on disk even if nothing ever closes the file.
  check('G9a the run starts at the start', file.startsWith('line 1\nline 2\n'))
  check('G9a the cut is announced', file.includes(CONSOLE_LOG_TRUNCATION_MARK))
  // The point of the whole exercise: a run long enough to be cut is a run that went wrong, and
  // what went wrong is at the end.
  check('G9a the ending survives the cut', file.trimEnd().endsWith('line 60'))
  check('G9a and the middle is honestly reported missing', /\d+ line\(s\) from the middle/.test(file))
  // A ceiling that can be exceeded by ten thousand lines is not a ceiling. Head + tail + one
  // marker is the entire budget, whatever the run does.
  check(
    'G9a the file cannot grow with the run',
    file.length < 400,
    `${file.length} bytes for 60 lines`
  )
  // Nothing is invented and nothing is reordered — this file is the console, verbatim.
  check('G9a no line is rewritten', file.includes('line 1\n') && file.includes('line 60\n'))
  check('G9a and none is duplicated across the cut', file.split('line 60\n').length === 2)

  // A run that never reaches the ceiling gets no marker and no ceremony.
  const small: string[] = []
  const quiet = createConsoleLog((c) => small.push(c), { headBytes: 4096, tailBytes: 4096 })
  quiet.write('only line')
  quiet.close()
  check('G9a a short run is written whole', small.join('') === 'only line\n')

  // `close()` runs from `finish()`, which several racing paths can reach for the same job.
  const twice: string[] = []
  const closed = createConsoleLog((c) => twice.push(c), { headBytes: 8, tailBytes: 64 })
  closed.write('aaaaaaaaaaaaaaaa')
  closed.write('bbbb')
  closed.close()
  const after = twice.join('')
  closed.close()
  closed.write('cccc')
  check('G9a closing twice is closing once', twice.join('') === after)
  check('G9a and a line after the end is refused', !twice.join('').includes('cccc'))
}

section('G9d — one line cannot step over the ceiling the other lines respect')
{
  // The hole this closes: both the head and the tail decide whether to take a line BEFORE seeing
  // how big it is, so a single line arriving with budget left was written whole at any size —
  // and `run()` turns an entire newline-free chunk into exactly one line.
  const flood: string[] = []
  const log = createConsoleLog((c) => flood.push(c), { headBytes: 200, tailBytes: 200, lineBytes: 64 })
  log.write('a'.repeat(100_000))
  log.close()
  const file = flood.join('')

  check('G9d the long line is cut, not written', file.length < 300, `${file.length} bytes`)
  check('G9d it is cut to its own budget', file.split('\n')[0].startsWith('a'.repeat(64)))
  check('G9d not one byte further', !file.includes('a'.repeat(65)))
  check('G9d and the cut is admitted, with its size', /\[log truncated\] 99936 more character\(s\)/.test(file))

  // The ceiling is only a ceiling if it holds for a run made ENTIRELY of such lines.
  const many: string[] = []
  const flooded = createConsoleLog((c) => many.push(c), { headBytes: 200, tailBytes: 200, lineBytes: 64 })
  for (let i = 0; i < 500; i++) flooded.write('b'.repeat(50_000))
  flooded.close()
  check(
    'G9d five hundred of them still fit under it',
    many.join('').length < 1200,
    `${many.join('').length} bytes for 500 x 50 KB`
  )

  // Cutting at an arbitrary byte would put half a character — a replacement character — into a
  // file whose whole value is being a faithful record. 'é' is two bytes, so a 9-byte budget has
  // to stop at four of them and refuse the fifth rather than emit its first byte alone.
  const utf8: string[] = []
  const chars = createConsoleLog((c) => utf8.push(c), { headBytes: 4096, tailBytes: 4096, lineBytes: 9 })
  chars.write('é'.repeat(20))
  chars.close()
  const cut = utf8.join('').split(' [log truncated]')[0]
  check('G9d a multi-byte character is never split', !cut.includes('\uFFFD'), JSON.stringify(cut))
  check('G9d the cut lands on a character boundary', cut === 'é'.repeat(4), JSON.stringify(cut))

  // Surrogate pairs are the same hazard one level up: two code units, four bytes, and slicing
  // the string rather than the bytes would leave a lone surrogate behind.
  const astral: string[] = []
  const emoji = createConsoleLog((c) => astral.push(c), { headBytes: 4096, tailBytes: 4096, lineBytes: 10 })
  emoji.write('😀'.repeat(20))
  emoji.close()
  const emojiCut = astral.join('').split(' [log truncated]')[0]
  check('G9d a surrogate pair survives the cut whole', emojiCut === '😀'.repeat(2), JSON.stringify(emojiCut))

  // And the lines that actually occur are still the bytes the engine sent, unexamined.
  const plain: string[] = []
  const ordinary = createConsoleLog((c) => plain.push(c))
  ordinary.write('Translating batch 3 of 40…')
  ordinary.close()
  check('G9d an ordinary line is untouched', plain.join('') === 'Translating batch 3 of 40…\n')

  // A default-limits log has a stated ceiling; it is worth one assertion that it is a real number
  // and that the per-line limit is the small one of the three.
  check(
    'G9d the per-line budget is the smallest of them',
    DEFAULT_CONSOLE_LOG_LIMITS.lineBytes < DEFAULT_CONSOLE_LOG_LIMITS.tailBytes &&
      DEFAULT_CONSOLE_LOG_LIMITS.tailBytes < DEFAULT_CONSOLE_LOG_LIMITS.headBytes
  )
}

section('G9e — the console file keeps each line it is written (REP-26)')
{
  const distinct: string[] = []
  const unique = createConsoleLog((c) => distinct.push(c), { headBytes: 4096, tailBytes: 4096 })
  for (let i = 1; i <= 20; i++) unique.write(`line ${i} ${'x'.repeat(20)}`)
  unique.close()
  const uniqueFile = distinct.join('')
  check('G9e twenty distinct lines are twenty lines', uniqueFile.split('\n').filter(Boolean).length === 20)

  const mid: string[] = []
  const dangling = createConsoleLog((c) => mid.push(c), { headBytes: 4096, tailBytes: 4096 })
  dangling.write('A')
  dangling.write('B')
  dangling.write('A')
  dangling.close()
  check(
    'G9e a partial suffix at close is written, not swallowed',
    mid.join('') === 'A\nB\nA\n'
  )
}

section('G9b — no sidecar overwrites another, and the console log is one of them')
{
  const saved = String.raw`C:\Users\me\Movies\Pachinko.he.srt`
  const temp = String.raw`C:\Temp\srt-out-123`
  const sidecars = [
    `${temp}.tokens.json`,
    `${temp}.progress.log`,
    `${temp}.thoughts.log`,
    `${temp}${CONSOLE_LOG_SUFFIX}`
  ]
  const dests = sidecars.map((p) => sidecarDestination(p, saved))

  check('G9b every sidecar lands on its own name', new Set(dests).size === dests.length, dests.join(' '))
  check('G9b none of them lands on the subtitle', !dests.includes(saved))
  // The specific bug this phase was warned about: `path.extname()` sees only the last dot, so a
  // `.console.log` missing from the list becomes `.log` — a name the other two logs are one
  // small mistake away from as well.
  check(
    'G9b the console log keeps its compound suffix',
    dests[3] === String.raw`C:\Users\me\Movies\Pachinko.he.console.log`,
    dests[3]
  )
  check('G9b and the token report keeps both of its dots', dests[0].endsWith('.tokens.json'))
  // Every sidecar takes the name the user chose, not the temp name the engine was given.
  check('G9b all of them take the saved name', dests.every((d) => d.startsWith(String.raw`C:\Users\me\Movies\Pachinko.he.`)))

  // POSIX separators, since the same code runs on both.
  check(
    'G9b and it works with forward slashes',
    sidecarDestination('/tmp/out-9.console.log', '/home/me/ep1.he.srt') === '/home/me/ep1.he.console.log'
  )
}

section('G9c — a run\u2019s console is named after its output, and found again by name')
{
  check('G9c beside the output, sharing its name', consoleLogPathFor('/out/ep1.srt') === '/out/ep1.console.log')
  check('G9c an .ass output is no different', consoleLogPathFor('/out/ep1.ass') === '/out/ep1.console.log')
  check('G9c an extensionless output still gets one', consoleLogPathFor('/out/ep1') === '/out/ep1.console.log')
  // Windows paths have dots in directory names far more often than anyone expects.
  check(
    'G9c a dotted directory is not mistaken for an extension',
    consoleLogPathFor(String.raw`C:\My.Films\ep1.srt`) === String.raw`C:\My.Films\ep1.console.log`
  )

  // The panel picks it out of a list whose other members depend on settings, so position is
  // not something it may rely on.
  check('G9c found among the engine\u2019s own reports', findConsoleLog(['/a/x.progress.log', '/a/x.console.log']) === '/a/x.console.log')
  check('G9c found when it is the only one', findConsoleLog(['/a/x.console.log']) === '/a/x.console.log')
  check('G9c and absent means absent', findConsoleLog(['/a/x.progress.log', '/a/x.tokens.json']) === '')
  check('G9c an empty list is not an error', findConsoleLog([]) === '')
  check('G9c nor is no list at all', findConsoleLog(undefined) === '')
}

// ── G10 — the release audit's findings (round 1, GPT-5.6-Sol) ──────────────────

{
  section('G10b — a partial tree kill names its survivors')
  // SOL-05. `taskkill /t` can remove the bootloader and fail on the interpreter beneath it, so a
  // liveness check on the pid we hold would report the whole tree gone. The pids are in the text.
  const real =
    'ERROR: The process with PID 4711 (child process of PID 4096) could not be terminated.\r\n' +
    'Reason: Access is denied.'
  const found = survivorsIn(real)
  check('G10b both pids on the line are collected', found.includes(4711) && found.includes(4096), found.join(','))
  check('G10b a clean kill names nobody', survivorsIn('').length === 0)
  check(
    'G10b SUCCESS output contributes no survivors',
    survivorsIn('SUCCESS: The process with PID 4096 has been terminated.').length === 1,
    // One pid IS named here — checking a pid that has just died is harmless (it reads as gone),
    // whereas missing one is the defect. The asymmetry is deliberate.
    survivorsIn('SUCCESS: The process with PID 4096 has been terminated.').join(',')
  )
  check('G10b duplicates collapse', survivorsIn('PID 12 ... PID 12').length === 1)
  check('G10b and nonsense yields nothing', survivorsIn('Access is denied.').length === 0)
}

// ── G11 — the release audit's findings (round 2, GPT-5.6-Sol) ──────────────────

{
  section('G11a — a stepped name keeps its compound suffix, and never runs out')
  // SOL-13. The first collision fix stopped after fifty numbered names and then returned no logger
  // at all, trading a destructive overwrite for silently losing the feature. The counter must also
  // go BEFORE the compound suffix: `episode.console-2.log` no longer ends in `.console.log` and is
  // therefore invisible to `findConsoleLog()` and to the sidecar suffix table.
  const c = (n: number): string => nthCandidate('/out/episode.console.log', '.console.log', n)
  check('G11a the first candidate is the preferred name', c(1) === '/out/episode.console.log')
  check('G11a the second is numbered', c(2) === '/out/episode-2.console.log', c(2))
  check('G11a and every candidate still ends in the compound suffix', [1, 2, 3, 20, 21, 99].every((n) => c(n).endsWith('.console.log')))
  check('G11a the counter never lands inside the suffix', !c(2).includes('.console-'), c(2))
  // Past the numbered range it must still produce a name, and a DIFFERENT one each time.
  const overflow = [c(500), c(500), c(500)]
  check('G11a past the numbered range it still produces names', overflow.every(Boolean))
  check('G11a and they are distinct, so it cannot run out', new Set(overflow).size === 3, overflow.join(' '))
  // A path that does not carry the suffix must not be mangled into one that half does.
  const bare = nthCandidate('/out/episode', '.console.log', 2)
  check('G11a a name without the suffix gains it', bare === '/out/episode-2.console.log', bare)
  // The other three sidecars share this machinery.
  check(
    'G11a the token report keeps both of its dots',
    nthCandidate('/out/x.tokens.json', '.tokens.json', 2) === '/out/x-2.tokens.json'
  )

  section('G11b — every sidecar destination is exclusive except the subtitle')
  // SOL-12. The save dialog obtains consent for ONE file. These four names are derived from it, so
  // an existing one used to be overwritten silently. Proven against the real filesystem.
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'g11-'))
  const src = path.join(dir, 'src.console.log')
  fs.writeFileSync(src, 'new run')
  const occupied = path.join(dir, 'episode.console.log')
  fs.writeFileSync(occupied, 'PRECIOUS')
  const landed = copyExclusive(src, occupied, '.console.log')
  check('G11b the existing sidecar is untouched', fs.readFileSync(occupied, 'utf-8') === 'PRECIOUS')
  check('G11b the copy went somewhere else', landed !== null && landed !== occupied, String(landed))
  check('G11b and it carries the new content', !!landed && fs.readFileSync(landed, 'utf-8') === 'new run')
  check('G11b the reported name is the one on disk', !!landed && fs.existsSync(landed))
  // A free name must be used as-is, or every ordinary save would start numbering.
  const free = path.join(dir, 'other.console.log')
  check('G11b a free name is taken unchanged', copyExclusive(src, free, '.console.log') === free)
  // The rewritten sidecar (the token report) takes the same route.
  const tokOccupied = path.join(dir, 'episode.tokens.json')
  fs.writeFileSync(tokOccupied, 'OLD REPORT')
  const tokLanded = writeExclusive('{"new":true}', tokOccupied, '.tokens.json')
  check('G11b the existing token report survives', fs.readFileSync(tokOccupied, 'utf-8') === 'OLD REPORT')
  check('G11b and the new one is beside it', !!tokLanded && tokLanded !== tokOccupied, String(tokLanded))
  rmTemp(dir)

  section('G11c — waiting for an exit means waiting for the exit')
  // SOL-02. Nothing to wait for must resolve at once, rather than sitting out a grace period.
  const goneAt = Date.now()
  const goneResult = await waitForChildExit(undefined)
  check('G11c an absent process is gone immediately', goneResult === true)
  check('G11c and it does not wait to say so', Date.now() - goneAt < 100)
  check('G11c pidIsAlive agrees about this process', pidIsAlive(process.pid))
  check('G11c and an undefined pid is not alive', !pidIsAlive(undefined))

  // A child that exits on its own must be reported gone WITHOUT anything being killed. This is the
  // SOL-14 property stated as a test: the helper used to poll a bare pid on its own timer, so it
  // could still be watching — and still escalating — after the child it was hired to watch had been
  // reaped and its pid handed to something else. Counting kills is how that is observable.
  let kills = 0
  const countKill = (): void => {
    kills += 1
  }
  const quick = spawn(process.execPath, ['-e', 'setTimeout(()=>{},150)'])
  const quickGone = await waitForChildExit(quick, { graceMs: 3_000, attempts: 3, kill: countKill })
  check('G11c a child that exits on its own is reported gone', quickGone === true)
  check('G11c and nothing was killed to achieve it', kills === 0, `kills=${kills}`)
  // And after `close`, no poll may remain to act on that pid later.
  const killsAtClose = kills
  await new Promise((r) => setTimeout(r, 400))
  check('G11c nor is anything killed after it closes', kills === killsAtClose, `kills=${kills}`)

  // A child that will not leave must be escalated against, and reported honestly if it stays. It
  // ignores SIGTERM, so only the real forced kill ends it — which is the escalation being tested.
  kills = 0
  const stubborn = spawn(process.execPath, [
    '-e',
    "process.on('SIGTERM',()=>{});setInterval(()=>{},1000)"
  ])
  await new Promise((r) => setTimeout(r, 200))
  const stubbornGone = await waitForChildExit(stubborn, { graceMs: 200, attempts: 4 })
  check('G11c a process that ignores SIGTERM is escalated against until it goes', stubbornGone === true)
  check('G11c hasExited agrees once it has', hasExited(stubborn))
  // A reaped child is never signalled: its pid may belong to someone else by now.
  // SOL-44: the kill is injectable so "zero signals" is observed, not inferred from the
  // pid being gone. Prove the spy is wired on a live child first, or kills===0 is vacuous.
  kills = 0
  const live = spawn(process.execPath, ['-e', 'setInterval(()=>{},1000)'])
  await new Promise((r) => setTimeout(r, 80))
  forceKillTree(live, countKill)
  check('G11c a live child is handed to the injected kill', kills === 1, `kills=${kills}`)
  live.kill()
  await new Promise<void>((r) => live.once('close', () => r()))
  kills = 0
  forceKillTree(stubborn, countKill)
  check('G11c a reaped child is not signalled again', kills === 0, `kills=${kills}`)

  section('G11d — a stepped sidecar is distinguishable from a canonical one')
  // SOL-15. The panel tells the user which reports could not take their usual name, and it decides by
  // asking whether the name begins with the subtitle's stem AND a dot. That is a CONTRACT between two
  // modules that never import each other: the stepping in `exclusiveFile.ts` and the predicate in
  // TranslatePage. If stepping ever produced `episode.2.tokens.json`, every stepped file would read
  // as canonical and the warning would silently stop appearing. Pinned here so it cannot drift.
  // 1 is the preferred name unchanged; stepping starts at 2, and past the numbered range the unique
  // fallback must still read as stepped rather than as canonical.
  const canonical = nthCandidate('/out/episode.tokens.json', '.tokens.json', 1)
  const stepped = nthCandidate('/out/episode.tokens.json', '.tokens.json', 2)
  const farStepped = nthCandidate('/out/episode.tokens.json', '.tokens.json', 500)
  const nameOf = (p: string): string => p.split(/[\\/]/).pop() ?? ''
  check('G11d the first candidate is the canonical name', nameOf(canonical) === 'episode.tokens.json')
  check('G11d and it reads as belonging to the subtitle', nameOf(canonical).startsWith('episode.'))
  check(
    'G11d a stepped name does NOT read as belonging to it',
    !nameOf(stepped).startsWith('episode.'),
    nameOf(stepped)
  )
  check('G11d and it keeps the compound suffix', nameOf(stepped).endsWith('.tokens.json'))
  check(
    'G11d the unique fallback reads as stepped too',
    !nameOf(farStepped).startsWith('episode.'),
    nameOf(farStepped)
  )

  section('G11e — displaceExclusive moves without destroying, and is not how save works')
  // The primitive is still the right answer to "move this file to a free name". The save handler
  // no longer uses it (SOL-17: Transcribe's picker-only call would have renamed four reports
  // nobody agreed to move). G11e pins the primitive; G11f pins what save actually does.
  const box = fs.mkdtempSync(path.join(os.tmpdir(), 'srt-g11e-'))
  const tokens = path.join(box, 'episode.tokens.json')
  const stranger = path.join(box, 'episode-2.tokens.json')
  fs.writeFileSync(tokens, 'OLD REPORT')
  fs.writeFileSync(stranger, 'SOMEONE ELSE')
  const moved = displaceExclusive(tokens, '.tokens.json')
  check('G11e the canonical name is now free', !fs.existsSync(tokens))
  check('G11e the stranger at -2 was not overwritten', fs.readFileSync(stranger, 'utf-8') === 'SOMEONE ELSE')
  check('G11e the old report still exists under a stepped name', !!moved && fs.existsSync(moved), String(moved))
  check('G11e and it still holds the old bytes', !!moved && fs.readFileSync(moved, 'utf-8') === 'OLD REPORT')
  check('G11e a missing file displaces nothing', displaceExclusive(path.join(box, 'absent.console.log'), '.console.log') === null)
  rmTemp(box)

  section('G11f — leftover canonicals are reported, not renamed')
  // SOL-12 / SOL-15 / SOL-17. After a real translation save, names this run did not write that
  // still sit at the canonical path must be listed, and the files themselves must not move.
  const nest = fs.mkdtempSync(path.join(os.tmpdir(), 'srt-g11f-'))
  const saved = path.join(nest, 'episode.srt')
  const oldTokens = path.join(nest, 'episode.tokens.json')
  const newProgress = path.join(nest, 'episode.progress.log')
  const steppedThoughts = path.join(nest, 'episode-2.thoughts.log')
  fs.writeFileSync(oldTokens, 'OLD TOKENS')
  fs.writeFileSync(newProgress, 'THIS RUN')
  fs.writeFileSync(steppedThoughts, 'STEPPED')
  const leftover = leftoverCanonicals(saved, [newProgress, steppedThoughts])
  check(
    'G11f a type this run did not write is leftover',
    leftover.includes(oldTokens),
    leftover.join(' ')
  )
  check('G11f a canonical this run DID write is not leftover', !leftover.includes(newProgress))
  check('G11f a stepped path is not treated as a leftover canonical', !leftover.includes(steppedThoughts))
  check('G11f and the old file is still at its name', fs.readFileSync(oldTokens, 'utf-8') === 'OLD TOKENS')
  check(
    'G11f a missing type is not leftover',
    !leftoverCanonicals(saved, [newProgress]).some((p) => p.endsWith('.console.log'))
  )
  rmTemp(nest)

  section('G11g — once the child we own has closed, nothing may kill its former number')
  // SOL-18. Round 5 kept a copy of the PGID and SIGKILLed it three seconds later, even after
  // `close`. That number is reusable. `waitForChildExit` of an already-reaped child must
  // resolve immediately and must not escalate — the same contract `forceKillTree` already
  // keeps by refusing `hasExited`. There is no delayed bare-PGID kill left to call.
  kills = 0
  const alreadyGone = spawn(process.execPath, ['-e', 'process.exit(0)'])
  await new Promise<void>((r) => alreadyGone.once('close', () => r()))
  const afterClose = Date.now()
  const afterGone = await waitForChildExit(alreadyGone, { graceMs: 3_000, attempts: 3, kill: countKill })
  check('G11g a reaped child is reported gone immediately', afterGone === true)
  check('G11g and it does not sit out a grace period', Date.now() - afterClose < 100)
  check('G11g and nothing is killed on the strength of its old pid', kills === 0, `kills=${kills}`)
  check('G11g hasExited is what keeps forceKillTree off that pid', hasExited(alreadyGone))

  section('G11h — a pid is not signalable once Node has reaped the child')
  // SOL-19. `close` can lag `exit` while stdio drains; the job is still Stop-able in that gap.
  // `livePid` must refuse as soon as `hasExited`, not wait for `close`.
  const held = spawn(process.execPath, ['-e', 'setInterval(()=>{},1000)'])
  await new Promise((r) => setTimeout(r, 80))
  check('G11h a live child still has a signalable pid', livePid(held) === held.pid && livePid(held) !== undefined)
  let closeHadFired = false
  held.once('close', () => {
    closeHadFired = true
  })
  const atExit = await new Promise<{ live: number | undefined; closeHadFired: boolean }>((resolve) => {
    held.once('exit', () => resolve({ live: livePid(held), closeHadFired }))
    held.kill()
  })
  check('G11h livePid is gone on exit', atExit.live === undefined)
  check('G11h because hasExited, not because pid was cleared', hasExited(held) && held.pid !== undefined)
  // A handle that never declared exitCode is not reaped. `!== null` used to say it was, and Stop
  // then skipped the tree kill of a still-running engine (the console-log probe's FakeChild).
  const stub = { pid: 42 } as unknown as import('child_process').ChildProcess
  check('G11h a missing exitCode is not a reap', !hasExited(stub) && livePid(stub) === 42)
}

{
  section('G12 — HTTPS-only external open (SOL-24)')
  check('G12 https is approved', isHttpsUrl('https://aistudio.google.com/apikey'))
  check('G12 a trailing path is still https', isHttpsUrl('https://www.imdb.com/title/tt1/'))
  check('G12 http is not', !isHttpsUrl('http://example.com'))
  check('G12 file is not', !isHttpsUrl('file:///C:/secret.txt'))
  check('G12 a custom protocol is not', !isHttpsUrl('myapp:open'))
  check('G12 javascript is not', !isHttpsUrl('javascript:alert(1)'))
  check('G12 empty is not', !isHttpsUrl(''))
  check('G12 malformed is not', !isHttpsUrl('not a url'))
}

section('G14 — transcribe endings tell the truth about the file (SF-4 / REP-37)')
{
  const stopped = transcribeUnsavedDetail()
  const failed = transcribeFailedDetail()
  eq(
    'G14 the stopped detail is stable',
    stopped,
    'Nothing was written. The transcription must start over.'
  )
  check('G14 stopped uses the shared claim', stopped.toLowerCase().includes(NOTHING_WAS_WRITTEN), stopped)
  check('G14 and tells the user the work must start over', /must start over/i.test(stopped), stopped)
  check('G14 stopped does not point at a partial file', !/partial/i.test(stopped), stopped)

  check('G14 generic failure is not the stopped sentence', failed !== stopped, failed)
  check(
    'G14 generic failure does not claim nothing was written (SOL-68)',
    !failed.toLowerCase().includes(NOTHING_WAS_WRITTEN),
    failed
  )
  check(
    'G14 generic failure tells the user to check the output path',
    /check the output path/i.test(failed),
    failed
  )


  // R3-05: the new engine writes as it goes, so a failed or stopped run can name an incomplete file.
  const incomplete = transcribeIncompleteDetail('C:\\subs\\film.partial.srt')
  check(
    'G14 R3-05 the incomplete detail names the file, says it is incomplete, and never that it is the finished transcription',
    incomplete.includes('C:\\subs\\film.partial.srt') && /incomplete/i.test(incomplete) && /not the finished transcription/.test(incomplete) && !incomplete.toLowerCase().includes(NOTHING_WAS_WRITTEN),
    incomplete
  )
  const finished = (outcome: 'failed' | 'stopped' | 'completed', partialPath?: string) =>
    reduceRunEvent(reduceRunEvent(initialRunnerModel('g14'), { type: 'started', runId: 'g14', kind: 'transcribe', engine: 'native', config: {} } as unknown as RunEvent), {
      type: 'finished', runId: 'g14', outcome, exitCode: null, outputPath: 'C:\\subs\\film.srt', logPaths: [], warnings: [],
      ...(partialPath ? { partialPath } : {}), ...(outcome === 'failed' ? { error: { kind: 'overload', message: 'busy' } } : {})
    } as unknown as RunEvent).state
  eq('G14 R3-05 a stopped or failed ending carries its partial into the page state', [finished('stopped', 'C:\\p.srt').partialPath, finished('failed', 'C:\\p.srt').partialPath, finished('stopped').partialPath], ['C:\\p.srt', 'C:\\p.srt', ''])
  eq('G14 R3-05 a completed ending never shows one, and a new run starts without one', [finished('completed', 'C:\\p.srt').partialPath, initialRunnerModel('next').state.partialPath], ['', ''])
  const page14 = fs.readFileSync(path.join(process.cwd(), 'src', 'pages', 'TranscribePage.tsx'), 'utf8')
  check(
    'G14 R3-05 TranscribePage: stopped and failed say the incomplete file when there is one, and otherwise keep the old sentences',
    /Stopped\. \{state\.partialPath \? transcribeIncompleteDetail\(state\.partialPath\) : transcribeUnsavedDetail\(\)\}/.test(page14) &&
      /\{state\.partialPath \? transcribeIncompleteDetail\(state\.partialPath\) : transcribeFailedDetail\(\)\}/.test(page14) &&
      !/Transcription saved[^\n]*partialPath/.test(page14)
  )
}

section('G15 — generation-parameters toggle follows the model (SF-7 / F2)')
{
  const onAccepting = {
    model: 'gemini-3.5-flash',
    customGenerationParams: true,
    temperature: 0.7,
    topP: 0.8
  }

  const toRejecting = settingsPatchOnModelChange(onAccepting, 'gemini-3.6-flash')
  check(
    'G15 sitting on a rejecting model does not destroy sampling intent (SOL-69)',
    toRejecting.customGenerationParams === undefined,
    JSON.stringify(toRejecting)
  )
  eq('G15 and records the new model', toRejecting.model, 'gemini-3.6-flash')
  check(
    'G15 that hop does not wipe typed sampling values (REP-5)',
    toRejecting.temperature === undefined && toRejecting.topP === undefined,
    JSON.stringify(toRejecting)
  )
  eq(
    'G15 the greyed switch does not look ON',
    samplingToggleChecked(true, 'gemini-3.6-flash'),
    false
  )
  eq(
    'G15 an accepting model still shows the stored ON',
    samplingToggleChecked(true, 'gemini-3.5-flash'),
    true
  )

  const onRejecting = {
    model: 'gemini-3.6-flash',
    customGenerationParams: true,
    temperature: 0.7,
    topP: 0.8
  }
  const back = settingsPatchOnModelChange(onRejecting, 'gemini-3.5-flash')
  eq('G15 switching back does not restore the toggle', back.customGenerationParams, false)
  check(
    'G15 and keeps the typed 0.7 / 0.8 (SOL-70)',
    back.temperature === undefined && back.topP === undefined,
    JSON.stringify(back)
  )
  eq('G15 and the control is live again', modelCapabilities('gemini-3.5-flash').acceptsSamplingParams, true)

  eq(
    'G15 persist-off helper: rejecting → accepting',
    shouldPersistSamplingToggleOff('gemini-3.6-flash', 'gemini-3.5-flash', true),
    true
  )
  eq(
    'G15 persist-off helper: accepting → rejecting leaves shared intent (SOL-69)',
    shouldPersistSamplingToggleOff('gemini-3.5-flash', 'gemini-3.6-flash', true),
    false
  )
  eq(
    'G15 persist-off helper: still rejecting leaves shared intent (SOL-69)',
    shouldPersistSamplingToggleOff('gemini-3.6-flash', 'gemini-3.6-flash-lite', true),
    false
  )
  eq(
    'G15 persist-off helper: user-off does not write false',
    shouldPersistSamplingToggleOff('gemini-3.6-flash', 'gemini-3.5-flash', false),
    false
  )

  {
    const live = (id: string, on: number[]): ModelInfo => ({
      id,
      label: id,
      source: 'live',
      availableOn: on
    })
    const stored = 'gemini-3.6-flash'
    const next = {
      models: [live('gemini-3.5-flash', [0])],
      unionIds: ['gemini-3.5-flash'],
      runnableIds: ['gemini-3.5-flash'],
      outcome: 'allComplete' as const
    }
    const sel = applyModelSelectionRules(stored, [live(stored, [0])], next)
    eq('G15 refresh proves the rejecting model absent (SOL-71)', sel.changed, true)
    eq('G15 and selects an accepting fallback', sel.model, 'gemini-3.5-flash')
    const persist = selectionSettingsPatch(
      { model: stored, customGenerationParams: true },
      sel
    )
    eq('G15 that same patch persists the toggle OFF (SOL-71)', persist.customGenerationParams, false)
    check(
      'G15 refresh persist-off does not write temperature / top-p (SOL-70)',
      persist.temperature === undefined && persist.topP === undefined,
      JSON.stringify(persist)
    )

    const ontoRejecting = applyModelSelectionRules(stored, [live(stored, [0])], {
      models: [live('gemini-3.6-flash-lite', [0])],
      unionIds: ['gemini-3.6-flash-lite'],
      runnableIds: ['gemini-3.6-flash-lite'],
      outcome: 'allComplete'
    })
    const stay = selectionSettingsPatch(
      { model: stored, customGenerationParams: true },
      ontoRejecting
    )
    eq('G15 refresh onto another rejecting model still writes the fallback', stay.model, 'gemini-3.6-flash-lite')
    check(
      'G15 and leaves shared sampling intent stored (SOL-69)',
      stay.customGenerationParams === undefined,
      JSON.stringify(stay)
    )

    const advance = applyModelSelectionRules(
      'gemini-3.1-flash-lite',
      [live('gemini-3.1-flash-lite', [0, 1])],
      {
        models: [live('gemini-3.2-flash-lite', [0, 1])],
        unionIds: ['gemini-3.2-flash-lite'],
        runnableIds: ['gemini-3.2-flash-lite'],
        outcome: 'activeComplete'
      }
    )
    const stayOn = selectionSettingsPatch(
      { model: 'gemini-3.1-flash-lite', customGenerationParams: true },
      advance
    )
    eq('G15 auto-advance between accepting models still writes the new id', stayOn.model, 'gemini-3.2-flash-lite')
    check(
      'G15 and does not turn the toggle off',
      stayOn.customGenerationParams === undefined,
      JSON.stringify(stayOn)
    )
  }

  const alreadyOff = settingsPatchOnModelChange(
    { model: 'gemini-3.5-flash', customGenerationParams: false },
    'gemini-2.5-flash'
  )
  eq('G15 preview defaults still refresh while the toggle is off', alreadyOff.temperature, 0.3)
  eq('G15 including top-p', alreadyOff.topP, 0.8)

  eq('G15 accepting models keep the override desc', samplingToggleDesc('gemini-3.5-flash'), SAMPLING_TOGGLE_DESC)
  eq('G15 3.1 flash-lite keeps the override desc', samplingToggleDesc('gemini-3.1-flash-lite'), SAMPLING_TOGGLE_DESC)
  eq(
    'G15 a greyed control explains why',
    samplingToggleDesc('gemini-3.6-flash'),
    SAMPLING_UNAVAILABLE_DESC
  )
  eq(
    'G15 flash-lite at 3.5 is greyed for the same reason',
    samplingToggleDesc('gemini-3.5-flash-lite'),
    SAMPLING_UNAVAILABLE_DESC
  )
  check(
    'G15 the greyed reason still points at Description',
    /Steer it with the Description field/i.test(SAMPLING_UNAVAILABLE_DESC)
  )
  check(
    'G15 the greyed reason is not an amber warning',
    !/text-amber/.test(SAMPLING_UNAVAILABLE_DESC)
  )

  const page = fs.readFileSync(path.join(process.cwd(), 'src', 'pages', 'SettingsPage.tsx'), 'utf8')
  check(
    'G15 the unreachable amber deprecation paragraph is gone (hazard 137)',
    !page.includes('This model does not use these settings.')
  )
  check(
    'G15 the toggle is disabled when the model rejects sampling',
    page.includes('disabled={!caps.acceptsSamplingParams}')
  )
  check(
    'G15 Settings does not persist-off on a rejecting global model (SOL-69)',
    !page.includes('void patch({ customGenerationParams: false })')
  )
  const ipcSrc = fs.readFileSync(path.join(process.cwd(), 'electron', 'main', 'ipc.ts'), 'utf8')
  eq(
    'G15 both refresh handlers persist via selectionSettingsPatch (SOL-71)',
    (ipcSrc.match(/Object\.assign\(patch, selectionSettingsPatch\(/g) ?? []).length,
    2
  )
}

// ── NG1: the frozen run-event contract has a runtime witness ───────────────────

/** Compile-time assertion; `typecheck:scripts` is what enforces it. */
type Assert<T extends true> = T

/*
 * Each table below is typed `Record<Union, …>`, so `typecheck:scripts` rejects it the moment a
 * member is added to or dropped from the contract without the table following. The runtime checks
 * then pin the table to the frozen member list, so the esbuild-bundled suite fails too.
 */
const RUN_EVENT_TAGS: Record<RunEvent['type'], true> = {
  started: true,
  phase: true,
  unit: true,
  lines: true,
  usage: true,
  budget: true,
  advice: true,
  log: true,
  warning: true,
  error: true,
  finished: true
}
const RUN_ERROR_KINDS: Record<RunErrorKind, true> = {
  blocked: true,
  auth: true,
  forbidden: true,
  unsupportedLocation: true,
  invalidRequest: true,
  quota: true,
  rateLimit: true,
  overload: true,
  network: true,
  timeout: true,
  responseTooLarge: true,
  inputLimit: true,
  malformed: true,
  countMismatch: true,
  refusedByApp: true,
  unknown: true
}
const WARNING_CODES: Record<WarningCode, true> = {
  filler: true,
  timing: true,
  fragment: true,
  scriptMix: true,
  artifact: true,
  notice: true
}
const RUN_PHASES: Record<RunPhase, true> = { starting: true, preparing: true, working: true, finishing: true }
const UNIT_STATES: Record<UnitState, true> = {
  sending: true,
  validating: true,
  received: true,
  retrying: true,
  failed: true
}
const BUDGET_STATES: Record<BudgetState, true> = {
  ready: true,
  waiting: true,
  groupSwitch: true,
  paidFallback: true,
  dailyExhausted: true
}
/** Every renderer status, classified, so the outcome map below can be checked for a gap. */
const RUN_STATUSES: Record<RunStatus, 'live' | 'terminal'> = {
  idle: 'live',
  running: 'live',
  done: 'terminal',
  error: 'terminal',
  stopped: 'terminal'
}
const OUTCOME_STATUS: Record<RunOutcome, RunStatus> = { completed: 'done', failed: 'error', stopped: 'stopped' }
const RUN_CONFIG_KEYS: Record<keyof RunConfigurationSummary, true> = {
  provider: true,
  model: true,
  inputPaths: true,
  outputPath: true,
  sourceLanguage: true,
  targetLanguage: true,
  requestedBatchSize: true,
  requestedChunkSeconds: true,
  thinkingLevel: true,
  thinkingBudget: true,
  serviceTier: true,
  generation: true,
  resumeFrom: true,
  resumeContextSize: true,
  credentialSlotCount: true,
  hasDescription: true,
  hasSystemPrompt: true,
  hasVideo: true,
  hasAudio: true,
  showTokenStats: true,
  writeTokenReport: true,
  progressLog: true,
  thoughtsLog: true,
  hebrewSpeakerRepair: true,
  hebrewMethodB: true,
  hebrewC1Spanish: true,
  hebrewC1Portuguese: true
}
const PROVIDER_CAPABILITY_KEYS: Record<keyof ProviderCapabilities, true> = {
  acceptsSystemPrompt: true,
  acceptsContext: true,
  acceptsReferenceTrack: true,
  acceptsAudio: true,
  transcribes: true,
  structuredOutputVariesByModel: true,
  timestampGranularityVariesByModel: true,
  serviceTier: true
}

/**
 * Names a field that would carry a credential, prompt/description text or a raw body. Matched on
 * whole camelCase words, so `resumeContextSize` is not "text". `token` is deliberately absent:
 * `showTokenStats` / `writeTokenReport` are usage toggles, not credentials.
 */
const CONTENT_WORDS = new Set(['key', 'keys', 'secret', 'credential', 'prompt', 'description', 'body', 'content', 'text', 'raw'])
const CONTENT_FIELD = {
  test: (name: string): boolean =>
    name.split(/(?=[A-Z])/).some((word) => CONTENT_WORDS.has(word.toLowerCase()))
}
/** The only content-adjacent names admitted: presence flags and a slot count, never values. */
const CONTENT_FLAGS = ['credentialSlotCount', 'hasDescription', 'hasSystemPrompt']

type ProviderModelOverlap = Assert<[keyof ProviderCapabilities & keyof ReturnType<typeof modelCapabilities>] extends [never] ? true : false>
type NoBareStructuredOutput = Assert<'structuredOutput' extends keyof ProviderCapabilities ? false : true>
type NoBareTimestampPrecision = Assert<'timestampPrecision' extends keyof ProviderCapabilities ? false : true>
type NoProviderTimestampGrid = Assert<'timestampGranularityMs' extends keyof ProviderCapabilities ? false : true>
type ServiceTierAdmitsBoth = Assert<'both' extends ProviderCapabilities['serviceTier'] ? true : false>
type DescriptionIsAFlag = Assert<RunConfigurationSummary['hasDescription'] extends boolean ? true : false>
type SystemPromptIsAFlag = Assert<RunConfigurationSummary['hasSystemPrompt'] extends boolean ? true : false>
type SlotCountIsANumber = Assert<RunConfigurationSummary['credentialSlotCount'] extends number ? true : false>
type FinishedCarriesError = Assert<'error' extends keyof Extract<RunEvent, { type: 'finished' }> ? true : false>
type EveryEventCarriesRunId = Assert<RunEvent extends { runId: string } ? true : false>
export type NG1CompileTimeWitnesses = [
  ProviderModelOverlap,
  NoBareStructuredOutput,
  NoBareTimestampPrecision,
  NoProviderTimestampGrid,
  ServiceTierAdmitsBoth,
  DescriptionIsAFlag,
  SystemPromptIsAFlag,
  SlotCountIsANumber,
  FinishedCarriesError,
  EveryEventCarriesRunId
]

section('NG1 — the run-event contract is frozen and witnessed (Step 0.3)')
{
  const sorted = (o: object): string[] => Object.keys(o).sort()

  eq('NG1 every RunEvent tag is in the tag table', sorted(RUN_EVENT_TAGS), [
    'advice', 'budget', 'error', 'finished', 'lines', 'log', 'phase', 'started', 'unit', 'usage', 'warning'
  ])
  eq('NG1 RunErrorKind is exhaustive, D14 kinds included', sorted(RUN_ERROR_KINDS), [
    'auth', 'blocked', 'countMismatch', 'forbidden', 'inputLimit', 'invalidRequest', 'malformed', 'network',
    'overload', 'quota', 'rateLimit', 'refusedByApp', 'responseTooLarge', 'timeout', 'unknown', 'unsupportedLocation'
  ])
  eq('NG1 WarningCode is exhaustive, artifact included', sorted(WARNING_CODES), [
    'artifact', 'filler', 'fragment', 'notice', 'scriptMix', 'timing'
  ])
  eq('NG1 RunPhase carries the four lifecycle values (BR-6)', sorted(RUN_PHASES), [
    'finishing', 'preparing', 'starting', 'working'
  ])
  eq('NG1 UnitState carries the five unit states', sorted(UNIT_STATES), [
    'failed', 'received', 'retrying', 'sending', 'validating'
  ])
  eq('NG1 BudgetState carries the five pacing states', sorted(BUDGET_STATES), [
    'dailyExhausted', 'groupSwitch', 'paidFallback', 'ready', 'waiting'
  ])
  eq(
    'NG1 RunOutcome covers every terminal RunStatus without a gap',
    [...new Set(Object.values(OUTCOME_STATUS))].sort(),
    Object.entries(RUN_STATUSES).filter(([, k]) => k === 'terminal').map(([s]) => s).sort()
  )
  check(
    'NG1 no RunOutcome maps to a live status',
    Object.values(OUTCOME_STATUS).every((s) => RUN_STATUSES[s] === 'terminal')
  )

  // ProviderCapabilities is per provider; anything modelCaps.ts answers per model must not be here.
  const perModelFacts = Object.keys(modelCapabilities('gemini-2.5-flash'))
  check(
    'NG1 ProviderCapabilities repeats no per-model fact from modelCaps.ts',
    Object.keys(PROVIDER_CAPABILITY_KEYS).every((k) => !perModelFacts.includes(k)),
    `overlap: ${Object.keys(PROVIDER_CAPABILITY_KEYS).filter((k) => perModelFacts.includes(k)).join(', ')}`
  )
  check(
    'NG1 no bare per-provider structuredOutput / timestamp field (D5-4)',
    !['structuredOutput', 'timestampPrecision', 'timestampGranularityMs'].some((k) => k in PROVIDER_CAPABILITY_KEYS)
  )
  eq(
    'NG1 per-model facts appear on the provider only as varies-by-model signals',
    Object.keys(PROVIDER_CAPABILITY_KEYS).filter((k) => /structured|timestamp/i.test(k)).sort(),
    ['structuredOutputVariesByModel', 'timestampGranularityVariesByModel']
  )

  // started.config: an allow-list of safe facts, never a value that is a secret or content.
  // R19 F17.3 amended in place (D17-5): the four Feature-17 switches join as required booleans.
  eq('NG1 started.config is exactly the frozen allow-list', sorted(RUN_CONFIG_KEYS), [
    'credentialSlotCount', 'generation', 'hasAudio', 'hasDescription', 'hasSystemPrompt', 'hasVideo',
    'hebrewC1Portuguese', 'hebrewC1Spanish', 'hebrewMethodB', 'hebrewSpeakerRepair',
    'inputPaths', 'model', 'outputPath', 'progressLog', 'provider', 'requestedBatchSize', 'requestedChunkSeconds',
    'resumeContextSize', 'resumeFrom', 'serviceTier', 'showTokenStats', 'sourceLanguage', 'targetLanguage',
    'thinkingBudget', 'thinkingLevel', 'thoughtsLog', 'writeTokenReport'
  ])
  check(
    'NG1 no started.config field names a credential, prompt, description or body value',
    Object.keys(RUN_CONFIG_KEYS).every((k) => CONTENT_FLAGS.includes(k) || !CONTENT_FIELD.test(k)),
    `offending: ${Object.keys(RUN_CONFIG_KEYS).filter((k) => !CONTENT_FLAGS.includes(k) && CONTENT_FIELD.test(k)).join(', ')}`
  )

  const KEY_A = 'AIza' + 'SyNG1-primary-0000000000000000000000'
  const KEY_B = 'AIza' + 'SyNG1-fallback-000000000000000000000'
  const DESCRIPTION = 'Source language: Hebrew. A family drama set in Haifa; Noa is female.'
  const SYSTEM_PROMPT = 'Translate tersely and keep slang.'
  const BODY = '{"candidates":[{"content":{"parts":[{"text":"1\\tשלום"}]}}]}'

  const translateConfig: RunConfigurationSummary = {
    provider: 'gemini',
    model: 'gemini-3.1-flash-lite',
    inputPaths: ['C:/in/film.srt', 'C:/in/film.mkv'],
    outputPath: 'C:/tmp/film.he.srt',
    sourceLanguage: 'Hebrew',
    targetLanguage: 'English',
    requestedBatchSize: 100,
    requestedChunkSeconds: 600,
    thinkingLevel: 'low',
    thinkingBudget: 512,
    serviceTier: 'flex',
    generation: { temperature: 0.7, topP: 0.9, topK: 40 },
    resumeFrom: 120,
    resumeContextSize: 50,
    credentialSlotCount: [KEY_A, KEY_B].length,
    hasDescription: DESCRIPTION.trim() !== '',
    hasSystemPrompt: SYSTEM_PROMPT.trim() !== '',
    hasVideo: true,
    hasAudio: false,
    showTokenStats: true,
    writeTokenReport: true,
    progressLog: false,
    thoughtsLog: true,
    hebrewSpeakerRepair: true,
    hebrewMethodB: false,
    hebrewC1Spanish: true,
    hebrewC1Portuguese: false
  }
  const transcribeConfig: RunConfigurationSummary = {
    provider: 'gemini',
    model: 'gemini-2.5-flash',
    inputPaths: ['C:/in/lecture.mp4'],
    outputPath: 'C:/out/lecture.srt',
    credentialSlotCount: 1,
    hasDescription: false,
    hasSystemPrompt: false,
    hasVideo: true,
    hasAudio: false,
    showTokenStats: true,
    writeTokenReport: false,
    progressLog: false,
    thoughtsLog: false,
    hebrewSpeakerRepair: false,
    hebrewMethodB: false,
    hebrewC1Spanish: false,
    hebrewC1Portuguese: false
  }
  const started: RunEvent[] = [
    { type: 'started', runId: 'ng1-t', kind: 'translate', config: translateConfig, totalLines: null, totalUnits: null },
    { type: 'started', runId: 'ng1-x', kind: 'transcribe', config: transcribeConfig, totalLines: null, totalUnits: null }
  ]

  check(
    'NG1 a full translate started fixture fills every allow-listed field',
    Object.keys(RUN_CONFIG_KEYS).every((k) => k in translateConfig)
  )
  check(
    'NG1 the minimal transcribe fixture carries every required field',
    ['provider', 'model', 'inputPaths', 'outputPath', 'credentialSlotCount', 'hasDescription', 'hasSystemPrompt',
      'hasVideo', 'hasAudio', 'showTokenStats', 'writeTokenReport', 'progressLog', 'thoughtsLog',
      'hebrewSpeakerRepair', 'hebrewMethodB', 'hebrewC1Spanish', 'hebrewC1Portuguese'].every((k) => k in transcribeConfig)
  )
  eq('NG1 the translate fixture counts its two eligible credential slots', translateConfig.credentialSlotCount, 2)
  eq('NG1 the transcribe fixture counts its one credential slot', transcribeConfig.credentialSlotCount, 1)
  check(
    'NG1 every credential-slot count is a whole number within the five-slot UI',
    started.every((e) => e.type === 'started' && Number.isInteger(e.config.credentialSlotCount) &&
      e.config.credentialSlotCount >= 0 && e.config.credentialSlotCount <= 5)
  )
  check(
    'NG1 content-adjacent config fields are presence flags, never values',
    started.every((e) => e.type === 'started' &&
      typeof e.config.hasDescription === 'boolean' && typeof e.config.hasSystemPrompt === 'boolean')
  )
  // What IPC and a JSONL row would carry is the serialised event.
  const wire = JSON.stringify(started)
  check('NG1 serialised started events carry no API key', !wire.includes(KEY_A) && !wire.includes(KEY_B) && !/AIza/.test(wire))
  check('NG1 serialised started events carry no description text', !wire.includes('Haifa') && !wire.includes(DESCRIPTION))
  check('NG1 serialised started events carry no system-prompt text', !wire.includes(SYSTEM_PROMPT))
  check('NG1 serialised started events carry no response body', !wire.includes(BODY) && !wire.includes('candidates'))

  // The schema itself refuses the fields; these lines exist for `typecheck:scripts`.
  const rejected: unknown[] = [
    // @ts-expect-error a credential value is not a run-configuration field
    { ...transcribeConfig, apiKeys: [KEY_A] } satisfies RunConfigurationSummary,
    // @ts-expect-error description text is not a run-configuration field
    { ...transcribeConfig, description: DESCRIPTION } satisfies RunConfigurationSummary,
    // @ts-expect-error system-prompt text is not a run-configuration field
    { ...transcribeConfig, systemPrompt: SYSTEM_PROMPT } satisfies RunConfigurationSummary,
    // @ts-expect-error a raw provider body is not a run-configuration field
    { ...transcribeConfig, body: BODY } satisfies RunConfigurationSummary
  ]
  eq('NG1 the four rejected-field fixtures are compiled (see @ts-expect-error)', rejected.length, 4)

}

// ── NG2: the typed unit event (Step 0.4) ──────

section('NG2 — the typed unit event admits audio seconds (Step 0.4)')
{
  type Line = ['stdout' | 'stderr', string]
  const MODEL = 'gemini-3.5-flash-lite'
  {
    const amended: RunEvent = { type: 'unit', runId: 'r', index: 1, total: 3, state: 'received', audioSeconds: { done: 54, total: 838.345 } }
    check('NG2 the contract admits audioSeconds on a unit (2026-10-04 amendment)', amended.type === 'unit' && amended.audioSeconds?.done === 54)
  }

  section('NG3 — useRunner reduces the typed run: the §2.1a matrix, and 1.1.0 parity on gst transcripts (Step 0.6)')

  const R3 = 'ng3-run'
  const feed = (events: readonly RunEvent[], runId = R3): RunnerModel => events.reduce(reduceRunEvent, initialRunnerModel(runId))
  const cfg = literalTranslateConfig('C:/tmp/ng3.srt')
  const startedEv: RunEvent = { type: 'started', runId: R3, kind: 'translate', config: cfg, totalLines: null, totalUnits: null }
  const finishedEv = (over: Partial<Extract<RunEvent, { type: 'finished' }>> = {}): RunEvent => ({
    type: 'finished',
    runId: R3,
    outcome: 'completed',
    exitCode: 0,
    outputPath: 'C:/tmp/ng3.srt',
    logPaths: ['C:/tmp/ng3.console.log'],
    warnings: [],
    ...over
  })
  const GUARD = 'No API key is configured. Open Settings > Gemini API Keys and enter a key before starting.'

  {
    const m = feed([finishedEv({ outcome: 'failed', exitCode: -1, reason: 'guard', outputPath: '', logPaths: [], error: { kind: 'refusedByApp', message: GUARD } })])
    check('NG3 outer model refusal: not left spinning', m.settled && m.state.status === 'error', JSON.stringify(m.state.status))
    check('NG3 outer model refusal: no artifact and no path', m.state.outputPath === '' && m.state.logPaths.length === 0)
    eq('NG3 outer model refusal: the guard sentence is what the panel shows', m.state.log.flatMap((r) => (r.kind === 'block' ? r.lines : [])), [GUARD])
  }
  {
    const busy = 'A process is already running.'
    const holder = feed([startedEv, { type: 'lines', runId: R3, done: 40, total: 250 }])
    const holderAfter = [
      { type: 'error', runId: 'ng3-busy', error: { kind: 'refusedByApp', message: busy } },
      { type: 'finished', runId: 'ng3-busy', outcome: 'failed', exitCode: -1, outputPath: 'C:/tmp/b.srt', logPaths: [], warnings: [], error: { kind: 'refusedByApp', message: busy } }
    ] satisfies RunEvent[]
    const unaffected = holderAfter.reduce(reduceRunEvent, holder)
    check('NG3 busy slot: the existing run is unaffected', unaffected === holder)
    const refused = feed(holderAfter, 'ng3-busy')
    check('NG3 busy slot: the refused request ends failed and opens no artifact', refused.state.status === 'error' && refused.state.logPaths.length === 0)
    eq('NG3 busy slot: its sentence reaches its own panel once', refused.state.log.flatMap((r) => (r.kind === 'block' ? r.lines : [])), [busy])
  }
  {
    const m = feed([
      startedEv,
      { type: 'log', runId: R3, stream: 'stderr', text: GUARD },
      { type: 'error', runId: R3, error: { kind: 'refusedByApp', message: GUARD } },
      finishedEv({ outcome: 'failed', exitCode: -1, reason: 'guard', error: { kind: 'refusedByApp', message: GUARD } })
    ])
    check('NG3 reserved guard failure: failed, with its console offered', m.state.status === 'error' && m.state.logPaths[0] === 'C:/tmp/ng3.console.log')
    eq('NG3 reserved guard failure: the sentence is in the panel once, from its log line', m.state.log.flatMap((r) => (r.kind === 'block' ? r.lines : [])), [GUARD])
  }
  {
    const m = feed([
      startedEv,
      { type: 'phase', runId: R3, phase: 'working' },
      { type: 'unit', runId: R3, index: 1, total: 3, state: 'sending' },
      { type: 'unit', runId: R3, index: 2, total: 3, state: 'received' },
      { type: 'unit', runId: R3, index: 3, total: 3, state: 'received' },
      { type: 'lines', runId: R3, done: 250, total: 250 },
      finishedEv()
    ])
    check('NG3 clean run: progress reaches 100% and it reads Completed', m.state.progress === 100 && m.state.status === 'done' && m.state.statusText === 'Completed')
    check('NG3 clean run: no error is carried', m.lastError === null && m.state.exitCode === 0)
  }
  {
    const midRetry = feed([
      startedEv,
      { type: 'unit', runId: R3, index: 2, total: 3, state: 'sending' },
      { type: 'error', runId: R3, error: { kind: 'quota', message: 'quota' } },
      { type: 'unit', runId: R3, index: 2, total: 3, state: 'retrying', attempt: 2, lineRange: { from: 101, to: 200 } }
    ])
    eq('NG3 retry: the banner names the batch while it is retried', midRetry.state.retry, { from: 101, to: 200 })
    eq('NG3 retry: and the status card keeps its last words', midRetry.state.statusText, 'Sending batch…')
    const m = [
      { type: 'unit', runId: R3, index: 2, total: 3, state: 'received' },
      finishedEv()
    ].reduce((acc, e) => reduceRunEvent(acc, e as RunEvent), midRetry)
    check('NG3 retry then success: the outcome is success', m.state.status === 'done' && m.state.statusText === 'Completed')
    check('NG3 retry then success: the transient error is not the run\u2019s result', m.lastError === null)
    eq('NG3 retry then success: the banner went away with the retry', m.state.retry, null)
  }
  {
    const AUTH = 'Your API key was rejected.'
    const m = feed([startedEv, { type: 'error', runId: R3, error: { kind: 'auth', message: AUTH } }, finishedEv({ outcome: 'failed', exitCode: 1, error: { kind: 'auth', message: AUTH } })])
    check('NG3 failure: the auth sentence survives, sourced from finished.error', m.state.status === 'error' && m.lastError?.kind === 'auth' && m.lastError.message === AUTH)
  }
  {
    const m = feed([startedEv, finishedEv({ outcome: 'stopped', exitCode: null, reason: 'user' })])
    check('NG3 Stop: reported as stopped, never as failed', m.state.status === 'stopped' && m.state.statusText === 'Stopped')
  }
  {
    const m = feed([finishedEv({ outcome: 'failed', exitCode: 1, error: { kind: 'network', message: 'offline' } })])
    check(
      'NG3 late consumer: the full terminal state is rebuilt from finished alone',
      m.state.status === 'error' && m.state.outputPath === 'C:/tmp/ng3.srt' && m.state.logPaths[0] === 'C:/tmp/ng3.console.log' && m.state.exitCode === 1 && m.lastError?.kind === 'network'
    )
  }
  {
    const once = feed([startedEv, finishedEv()])
    const twice = reduceRunEvent(once, finishedEv({ outcome: 'failed', exitCode: 1, error: { kind: 'unknown', message: 'x' } }))
    check('NG3 duplicate terminal: the second is dropped, state unchanged', twice.state === once.state && twice.dropped === 1)
    const after = reduceRunEvent(reduceRunEvent(once, { type: 'lines', runId: R3, done: 3, total: 250 }), { type: 'unit', runId: R3, index: 1, total: 3, state: 'sending' })
    check('NG3 post-terminal events: dropped and counted; progress does not move back', after.state === once.state && after.dropped === 2 && after.state.progress === 100)
  }
  {
    const own: RunEvent[] = [startedEv, { type: 'lines', runId: R3, done: 50, total: 250 }, { type: 'log', runId: R3, stream: 'stdout', text: 'mine' }, finishedEv()]
    const foreign: RunEvent[] = [
      { type: 'log', runId: 'other', stream: 'stdout', text: 'theirs' },
      { type: 'lines', runId: 'other', done: 240, total: 250 },
      { type: 'finished', runId: 'other', outcome: 'failed', exitCode: 1, outputPath: 'C:/x', logPaths: ['C:/x.log'], warnings: [], error: { kind: 'unknown', message: 'x' } }
    ]
    const mixed = own.flatMap((e, i) => (foreign[i] ? [foreign[i], e] : [e]))
    eq('NG3 foreign runId: interleaved events of another run are ignored entirely', feed(mixed), feed(own))
  }

  {
    // Only the Translate page has a status card; Transcribe's status text was never on screen.
    const page = fs.readFileSync(path.join(process.cwd(), 'src', 'pages', 'TranscribePage.tsx'), 'utf8')
    check('NG3 a transcription: the Transcribe page does not render status text', !page.includes('statusText'))
  }

  {
    const runnerSrc = fs.readFileSync(path.join(process.cwd(), 'src', 'lib', 'useRunner.ts'), 'utf8')
    check('NG3 useRunner subscribes to onEngineEvent', runnerSrc.includes('window.api.onEngineEvent('))
    check('NG3 useRunner no longer listens on the old channels', !/window\.api\.on(Output|Done)\(/.test(runnerSrc))
    const srcFiles = (dir: string): string[] =>
      fs.readdirSync(dir, { withFileTypes: true }).flatMap((d) => (d.isDirectory() ? srcFiles(path.join(dir, d.name)) : /\.tsx?$/.test(d.name) ? [path.join(dir, d.name)] : []))
    eq(
      'NG3 no renderer file imports terminalNoise',
      srcFiles(path.join(process.cwd(), 'src')).filter((f) => /terminalNoise/.test(fs.readFileSync(f, 'utf8'))).map((f) => path.relative(process.cwd(), f)),
      []
    )
  }

  section('NG3 — Step 0.7: the pages read typed errors and warnings, and say what 1.1.0 said')


  {
    const read = (...p: string[]): string => fs.readFileSync(path.join(process.cwd(), ...p), 'utf8')
    const srcFiles = (dir: string): string[] =>
      fs.readdirSync(dir, { withFileTypes: true }).flatMap((d) => (d.isDirectory() ? srcFiles(path.join(dir, d.name)) : /\.tsx?$/.test(d.name) ? [path.join(dir, d.name)] : []))
    eq(
      'NG3 0.7 no renderer file imports engineErrors or outputSanity',
      srcFiles(path.join(process.cwd(), 'src'))
        .filter((f) => /from '[^']*\/(engineErrors|outputSanity)'/.test(fs.readFileSync(f, 'utf8')))
        .map((f) => path.relative(process.cwd(), f)),
      []
    )
    for (const page of ['TranslatePage.tsx', 'TranscribePage.tsx']) {
      const text = read('src', 'pages', page)
      check(
        `NG3 0.7 ${page} reads no engine text: no log flattening, no classifier call`,
        !/flattenRunnerLog|classifyEngineFailure|explainTranslateAbort|fragmentNoteInLog/.test(text)
      )
      check(`NG3 0.7 ${page} takes its failure sentence from the typed error`, text.includes('failureSentence(state, '))
    }
    check('NG3 0.7 TranslatePage splits warnings by code, not by their copy', !/\/wrong timings\/i/.test(read('src', 'pages', 'TranslatePage.tsx')))
  }
}

section('NG2 — Step 0.5: engine:event and the old channels describe the same run (real IPC handlers)')
{
  const SECRET = 'AIza' + 'SyNG2-dual-key-0000000000000000000000'
  const MODEL = 'gemini-3.5-flash-lite'
  type Sent = { channel: string; payload: unknown }
  const sent: Sent[] = []
  const fakeWindow = {
    on: (): void => {},
    isDestroyed: (): boolean => false,
    webContents: {
      isDestroyed: (): boolean => false,
      send: (channel: string, payload: unknown): void => {
        sent.push({ channel, payload })
      }
    }
  }
  setMainWindow(fakeWindow as unknown as Parameters<typeof setMainWindow>[0])
  registerIpc()

  const streams = (runId: string) => {
    const mine = sent.filter((s) => (s.payload as { runId?: string })?.runId === runId)
    return {
      channels: [...new Set(mine.map((s) => s.channel))],
      events: mine.filter((s) => s.channel === 'engine:event').map((s) => s.payload as RunEvent)
    }
  }
  /** The panel and ending a page shows, through the real reducer. */
  const shown = (runId: string) => {
    const state = streams(runId).events.reduce(reduceRunEvent, initialRunnerModel(runId)).state
    return {
      panel: state.log.flatMap((r) => (r.kind === 'block' ? r.lines : [])),
      ending: { exitCode: state.exitCode, outputPath: state.outputPath, logPaths: state.logPaths, warnings: state.warnings },
      reason: (() => {
        const end = streams(runId).events.at(-1)
        return end?.type === 'finished' ? end.reason : 'no finished'
      })()
    }
  }
  // What `translate:output` / `translate:done` carried for these runs, captured from both streams at
  // Step 0.9 before the old channels were removed (gate_ledger.md §5.9).
  const NO_KEY = 'No API key is configured. Open Settings > Gemini API Keys and enter a key before starting.'
  const UNVERIFIED_MODELS =
    'Models have not been verified against your API key yet. If the run fails with "model not available", open Settings and use "Fetch Models & Check API Keys".'
  const NOT_UTF8_ASS =
    'This .ass file is not UTF-8. Re-save it as UTF-8 (most subtitle editors offer "Save as UTF-8") and try again. It was left untouched — guessing a legacy code page would corrupt styled text and style names.'
  const BUSY = 'A process is already running.'
  const RUN_IDS = ['ng2-dual-noKey', 'ng2-dual-txNoKey', 'ng2-dual-reserved', 'ng2-dual-busy', 'ng2-dual-txBusy']
  const lifecycleOk = (events: readonly RunEvent[], expectStarted: boolean): string | null => {
    const started = events.filter((e) => e.type === 'started').length
    if (started !== (expectStarted ? 1 : 0)) return `started x${started}`
    if (expectStarted && events[0]?.type !== 'started') return 'started is not first'
    if (events.filter((e) => e.type === 'finished').length !== 1) return 'finished is not exactly once'
    if (events.at(-1)?.type !== 'finished') return 'something follows finished'
    return null
  }
  const txArgs = (dir: string, over: Partial<TranscribeArgs> = {}): TranscribeArgs => ({
    mediaFile: path.join(dir, 'lecture.mp3'),
    outputFile: path.join(dir, 'lecture.srt'),
    targetLang: '',
    model: MODEL,
    apiKeys: [SECRET],
    thinkingLevel: 'low',
    thinkingBudget: 0,
    customGenerationParams: false,
    temperature: 1,
    topP: 0.95,
    topK: null,
    ...over
  })
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'ng2-dual-'))
  // ── the app's own guard, before the bridge is reached: error then finished, nothing else ──
  setSettings({ apiKeys: [], apiKeyValid: [], apiKeyTiers: [], cachedModels: [] })
  {
    const result = await __invokeIpc('translate:start', baseArgs({ apiKeys: [], model: MODEL, runId: 'ng2-dual-noKey' }))
    eq('NG2 0.5 translate guard: the handler still returns no output path', result, '')
    const s = streams('ng2-dual-noKey')
    eq('NG2 0.5 translate guard: typed stream is error then finished', s.events.map((e) => e.type), ['error', 'finished'])
    eq('NG2 0.5 translate guard: the typed stream keeps the lifecycle', lifecycleOk(s.events, false), null)
    const end = s.events.at(-1)
    check(
      'NG2 0.5 translate guard: it fails as refusedByApp, reason guard',
      end?.type === 'finished' && end.outcome === 'failed' && end.reason === 'guard' && end.error?.kind === 'refusedByApp'
    )
    const view = shown('ng2-dual-noKey')
    eq('NG2 0.9 translate guard: the panel shows the guard sentence', view.panel, [NO_KEY])
    eq(
      'NG2 0.9 translate guard: the ending is what translate:done said',
      { ...view.ending, reason: view.reason },
      { exitCode: -1, outputPath: '', logPaths: [], warnings: [], reason: 'guard' }
    )
  }
  {
    const result = await __invokeIpc('transcribe:start', txArgs(dir, { apiKeys: [], runId: 'ng2-dual-txNoKey' }))
    eq('NG2 0.5 transcribe guard: the handler still returns no output path', result, '')
    const s = streams('ng2-dual-txNoKey')
    eq('NG2 0.5 transcribe guard: typed stream is error then finished', s.events.map((e) => e.type), ['error', 'finished'])
    const view = shown('ng2-dual-txNoKey')
    eq('NG2 0.9 transcribe guard: the panel shows the guard sentence', view.panel, [NO_KEY])
    eq(
      'NG2 0.9 transcribe guard: the ending is what translate:done said',
      { ...view.ending, reason: view.reason },
      { exitCode: -1, outputPath: '', logPaths: [], warnings: [], reason: 'guard' }
    )
  }

  // ── reserved, then refused by the bridge: the guard's warning is the run's first log ──
  setSettings({ apiKeys: [SECRET], apiKeyValid: [true], apiKeyTiers: ['free'], cachedModels: [] })
  {
    const ass = path.join(dir, 'latin1.ass')
    fs.writeFileSync(ass, Buffer.from([0x5b, 0x53, 0x63, 0x72, 0x69, 0x70, 0x74, 0x5d, 0x0a, 0xe9, 0xe8, 0x0a]))
    const result = await __invokeIpc('translate:start', baseArgs({ inputFile: ass, apiKeys: [SECRET], model: MODEL, runId: 'ng2-dual-reserved' }))
    const s = streams('ng2-dual-reserved')
    eq('NG2 0.5 reserved refusal: the typed stream keeps the lifecycle', lifecycleOk(s.events, true), null)
    eq('NG2 0.5 reserved refusal: the guard warning is the first log, directly after started', s.events.slice(0, 2).map((e) => e.type), ['started', 'log'])
    const first = s.events[0]
    check('NG2 0.5 reserved refusal: started names the output the handler returned', first?.type === 'started' && first.config.outputPath === result && typeof result === 'string' && result !== '')
    check('NG2 0.5 reserved refusal: no credential reaches the typed stream', !JSON.stringify(s.events).includes(SECRET))
    const view = shown('ng2-dual-reserved')
    eq('NG2 0.9 reserved refusal: the panel shows the guard warning, then the refusal', view.panel, [UNVERIFIED_MODELS, `Translating "latin1.ass" with ${MODEL} (native engine).`, NOT_UTF8_ASS])
    const consoleBeside = view.ending.outputPath.replace(/\.srt$/, '.console.log')
    check(
      'NG2 0.9 reserved refusal: the ending is what translate:done said — no exit code (no process), no reason, its run record and console offered',
      view.ending.exitCode === null && view.reason === undefined && view.ending.warnings.length === 0 &&
        /\.srt$/.test(view.ending.outputPath) && JSON.stringify(view.ending.logPaths) === JSON.stringify([runRecordPathFor(view.ending.outputPath), consoleBeside]),
      JSON.stringify(view)
    )
    check('NG2 0.5 reserved refusal: the slot is released', !isRunning())
  }

  // ── busy: another job holds the slot, so the start is never reserved ──
  {
    const holdUntilStopped = (_key: string, signal: AbortSignal): Promise<KeyPreflight> =>
      new Promise((resolve) => {
        signal.addEventListener('abort', () => resolve({ verdict: 'unchecked', message: '' }), { once: true })
      })
    // Retargeted at Step 4.5 (gate_ledger §5m.5, R-9): the slot is held by a native Transcribe waiting on its key check.
    const holding = createNativeEngineAdapter({ preflight: holdUntilStopped, settings: () => ({}) }).transcribe(
      txArgs(dir, { model: 'gemini-3.7-flash' }),
      { runId: 'ng2-dual-holder', epoch: 1, signal: new AbortController().signal, settingsRevisions: { current: () => 0, subscribe: () => () => {} } },
      () => {}
    )
    await new Promise((r) => setImmediate(r))
    check('NG2 0.5 busy: the holder took the slot', isRunning())

    const result = await __invokeIpc('translate:start', baseArgs({ apiKeys: [SECRET], model: MODEL, runId: 'ng2-dual-busy' }))
    const s = streams('ng2-dual-busy')
    eq('NG2 0.5 busy: typed stream is error then finished, no started', s.events.map((e) => e.type), ['error', 'finished'])
    check('NG2 0.5 busy: the handler still answers with the output path it would have used', typeof result === 'string' && result !== '')
    const view = shown('ng2-dual-busy')
    eq('NG2 0.9 busy: the panel shows the guard warning, then the bridge\u2019s refusal', view.panel, [UNVERIFIED_MODELS, BUSY])
    eq(
      'NG2 0.9 busy: the ending is what translate:done said',
      { ...view.ending, reason: view.reason },
      { exitCode: null, outputPath: String(result), logPaths: [], warnings: [], reason: undefined }
    )

    const txResult = await __invokeIpc('transcribe:start', txArgs(dir, { outputFile: path.join(dir, 'other.srt'), runId: 'ng2-dual-txBusy' }))
    const t = streams('ng2-dual-txBusy')
    eq('NG2 0.5 transcribe busy: typed stream is error then finished', t.events.map((e) => e.type), ['error', 'finished'])
    eq('NG2 0.5 transcribe busy: the handler returns the chosen output', txResult, path.join(dir, 'other.srt'))
    const txView = shown('ng2-dual-txBusy')
    eq('NG2 0.9 transcribe busy: the panel shows the guard warning, then the bridge\u2019s refusal', txView.panel, [UNVERIFIED_MODELS, BUSY])
    eq(
      'NG2 0.9 transcribe busy: the ending is what translate:done said',
      { ...txView.ending, reason: txView.reason },
      { exitCode: null, outputPath: path.join(dir, 'other.srt'), logPaths: [], warnings: [], reason: undefined }
    )
    check('NG2 0.5 busy: the holder is untouched', isRunning())

    stopCurrent()
    await holding
    await new Promise((r) => setImmediate(r))
    check('NG2 0.5 busy: the slot is released after Stop', !isRunning())
  }

  eq(
    'NG2 0.9 the run handlers send nothing but engine:event',
    [...new Set(RUN_IDS.flatMap((id) => streams(id).channels))],
    ['engine:event']
  )

  // ── the typed warnings are the scan's own strings ──
  {
    const source = path.join(dir, 'source.srt')
    const output = path.join(dir, 'output.srt')
    fs.writeFileSync(source, G3_FILLER_PAIR.source)
    fs.writeFileSync(output, G3_FILLER_PAIR.output)
    const typed = scanOutputWarnings(source, output)
    check('NG2 0.5 scan: the fixture is a real warning', typed.length === 1)
    eq('NG2 0.5 scan: the old strings are the typed warnings\u2019 messages', scanOutputFiles(source, output), typed.map((w) => w.message))
    eq('NG2 0.5 scan: a missing file is still silent on the typed side', scanOutputWarnings(path.join(dir, 'nope.srt'), output), [])
  }

  // ── nothing in the handler bypasses the seam ──
  {
    const ipcSrc = fs.readFileSync(path.join(process.cwd(), 'electron', 'main', 'ipc.ts'), 'utf8')
    eq('NG2 0.5 engine:event leaves through one sender', (ipcSrc.match(/'engine:event'/g) ?? []).length, 1)
    const preloadSrc = fs.readFileSync(path.join(process.cwd(), 'electron', 'preload', 'index.ts'), 'utf8')
    check('NG2 0.5 the preload exposes onEngineEvent on engine:event', /onEngineEvent[\s\S]{0,200}'engine:event'/.test(preloadSrc))
    eq('NG2 0.9 ipc.ts sends neither old run channel', ipcSrc.match(/translate:(?:output|done)/g) ?? [], [])
    eq('NG2 0.9 the preload exposes neither onOutput nor onDone', preloadSrc.match(/\bon(?:Output|Done)\b|translate:(?:output|done)/g) ?? [], [])
    const typesSrc = fs.readFileSync(path.join(process.cwd(), 'electron', 'shared', 'types.ts'), 'utf8')
    check(
      'NG2 0.9 types.ts drops ProcOutput and ProcDone and keeps RunId and TerminalReason',
      !/\bProc(?:Output|Done)\b/.test(typesSrc) && /export type RunId\b/.test(typesSrc) && /export type TerminalReason\b/.test(typesSrc)
    )
    const roots = ['src', 'electron', path.join('scripts', 'verify')].map((r) => path.join(process.cwd(), r))
    const walk = (d: string): string[] =>
      fs.readdirSync(d, { withFileTypes: true }).flatMap((e) =>
        e.isDirectory() ? walk(path.join(d, e.name)) : /\.tsx?$/.test(e.name) ? [path.join(d, e.name)] : []
      )
    const stale = roots
      .flatMap(walk)
      .filter((f) => /\bProc(?:Output|Done)\b|translate:(?:output|done)|\bapi\.on(?:Output|Done)\b/.test(fs.readFileSync(f, 'utf8')))
      .map((f) => path.relative(process.cwd(), f))
    eq('NG2 0.9 no source still names an old run channel or its payload type', stale, [])
  }

  rmTemp(dir)
}

// ── G4c / G4d, moved under NG2 by Step 0.6: their subjects now live behind the CLI adapter ──

section('NG2 (moved from G4c) — a retry is named, never counted from redrawn lines (MAN-8)')
{
  // Five real retries of one batch, each adding three messages to a history that is redrawn
  // twenty times per cycle — the measured shape, where two retries arrived as 1,521 lines.
  const history: string[] = ['Validating token size...', 'Token size validated. Translating...']
  const stream: string[] = []
  for (let retry = 1; retry <= 5; retry++) {
    history.push(
      'Consecutive error count: 1/3',
      'Expected 100 lines, got 50.',
      'Retrying batch for lines 301-400...'
    )
    for (let draw = 0; draw < 20; draw++) stream.push(...history)
  }
  const raw = stream.filter((l) => l.startsWith('Retrying batch')).length
  check('G4c the raw stream really is inflated', raw > 200, `raw retry lines: ${raw}`)

  const rows = feedLog(stream)

  // No count is claimed, on purpose: the display cannot tell "the history accumulated five
  // retries" from "one history was redrawn five times", and inventing a number here is how a
  // recovered run gets reported as a catastrophe.
  eq('G4c nothing to say before a retry', retryIsCurrent(null, 0), false)
  eq('G4c speaks while the batch is unfinished', retryIsCurrent({ from: 301, to: 400 }, 300), true)
  eq('G4c goes quiet once the run reaches the end of that batch', retryIsCurrent({ from: 301, to: 400 }, 400), false)
  eq('G4c and stays quiet after it', retryIsCurrent({ from: 301, to: 400 }, 460), false)

  // The panel must not turn a five-retry history into sixty adjacent identical blocks.
  check('G4c the redrawn storm stays readable', rows.length <= 8, `rows: ${rows.length}`)
  eq('G4c row keys stay unique', new Set(rows.map((r) => r.seq)).size, rows.length)
  check(
    'G4c row keys stay in order',
    rows.every((r, i) => i === 0 || r.seq > rows[i - 1].seq)
  )
}

