    const told = invent.tagged('disproportion')
    eq('CV18 a half that comes back as text grossly short of its sound is refused, not asked for in smaller pieces again', [invent.result.outcome, told.length, invent.asked.filter((s) => s.start >= 300 && s.end <= 455).length, invent.saved?.some((c) => c.text === greet.text)], ['completed', 1, 1, false])

    // One part alone: its unchanged retry spends the whole 1\u00d7 allowance, so the halves are not sent.
    const alone = await run(profile(300, [[0, 300, -20]]), (s) => (s.end - s.start > 150 ? { ok: false, error: refusal } : hears(talk(0, 300))(s)))
    eq('CV18 the allowance binds a one-part film: retry, then the refusal is reported rather than re-sent past 1\u00d7', [spans(alone), alone.tagged('refused').length, alone.saved, alone.tagged('uncovered').length], [[[0, 300], [0, 300]], 1, [], 0])
    const said = alone.tagged('refused')[0]?.message ?? ''
    check('CV18 and it says the halves were not sent, not that they were refused too', /0:00\u20135:00/.test(said) && /could not be asked for again in smaller pieces, because this run re-sends at most/.test(said) && !/even when asked/.test(said), said)
