    const inverted = await run(clip, one([{ start: 2, end: 6, text: `${words} a` }, { start: 12, end: 8, text: `${words} b` }, { start: 20, end: 24, text: `${words} c` }]))
    eq('CV18 R3-03 a line that ends before it starts is left out; the lines around it are kept, untouched', [inverted.saved?.map((c) => [c.start, c.end, c.text]), inverted.tagged('mistimed').length], [[[2, 6, `${words} a`], [20, 24, `${words} c`]], 1])
    const backwards = await run(clip, one([{ start: 2, end: 6, text: `${words} a` }, { start: 20, end: 24, text: `${words} b` }, { start: 10, end: 14, text: `${words} c` }]))
    eq('CV18 R3-03 a line that starts before the line ahead of it is left out, never re-ordered or re-timed', [backwards.saved?.map((c) => c.text), backwards.tagged('mistimed').length], [[`${words} a`, `${words} b`], 1])
