    const instant = await run(clip, one([{ start: 2, end: 6, text: `${words} a` }, { start: 12, end: 12, text: 'Yes.' }, { start: 20, end: 24, text: `${words} b` }]))
    eq('CV18 R3-03 a whole-second line that starts and ends on one second is kept, as 1.1.0 wrote it (E68c)', [instant.result.outcome, instant.saved?.map((c) => c.text), instant.tagged('mistimed').length], ['completed', [`${words} a`, 'Yes.', `${words} b`], 0])
    const late = await run(clip, one([{ start: 2, end: 6, text: `${words} a` }, { start: 29.5, end: 30.8, text: `${words} b` }]))
    eq('CV18 R3-03 the 1 s rounding allowance still holds: a line ending 0.8 s past the clip is kept', [late.saved?.length, late.tagged('mistimed').length], [2, 0])
    // The allowance runs out after the halves: what is in hand is settled, and still filtered.
    const truth = talk(0, 300)
    const pastEnd = await run(profile(300, [[0, 300, -20]]), (s) => ({ ok: true, cues: [...(hears(truth)(s) as { cues: TranscriptCue[] }).cues, { start: s.end - s.start - 2, end: s.end - s.start + 50, text: 'runs past the audio' }] }))
