      await sleep(RETIRED_SWEEP_MS + 300)
      const bCleared = !fs.existsSync(path.dirname(path.dirname(ob.outputPath)))
      const aPending = fs.existsSync(oa.outputPath) && fs.existsSync(sessionsRoot)
