      const leasesIn = (): string[] => fs.readdirSync(session).filter((n) => n.startsWith('engine-'))
      const first = takeEngineLease(out)!
      const second = takeEngineLease(out)!
      const two = leasesIn()
      first.release()
      const afterFirst = leasesIn()
      fs.rmdirSync(offerDir)
      second.release()
      second.release()
