          download: async () => ({ ok: true, members: [{ ordinal: 1, safeName: 'm.srt', originalName: 'SECRET.srt', bytes: refBytes }], fileName: 'SECRET.srt', remaining: 9, resetUtc: null, keySource: 'pool', charged: 'key', keysTried: 1, login: 'notEntered' })
