      const panelSrc = fs.readFileSync(path.join(process.cwd(), 'src', 'components', 'GenderReferencePanel.tsx'), 'utf8').replace(/\r\n/g, '\n')
      RW.offerAcceptedReference('run-a', { path: 'C:/tmp/x-reference-1.srt', name: 'SECRET.srt', language: 'ar' })
      const first = RW.acceptedReferenceOf('run-a')
