      for (let i = 0; i < 8; i += 1) RW.offerAcceptedReference(`run-later-${i}`, { path: `C:/tmp/${i}.srt`, name: `${i}.srt`, language: 'he' })
      const evicted = RW.acceptedReferenceOf('run-a')
