section('R19A A.1 - the gender readers ignore invisible direction marks (gate_ledger §5s.24)')
{
  const G = genderReaders
  const RLE = '\u202B'
  const PDF = '\u202C'
  const RLM = '\u200F'
  const lines = ['את נראית עייפה.', 'את לא יכולה לומר שלא ניסיתי.', 'את יודעת מה הייתי עושה?', 'ואת בטעות מעמידה פנים']
  eq(
    'R19A A.1 a human Hebrew line that starts with a direction mark still reads F on the addressee axis, as the reference and as the output (the three measured shapes)',
    [lines.map((t) => G.referenceAddresseeGender(RLE + t + PDF, 'he')), lines.map((t) => G.hebrewAddressee(RLM + t)), lines.map((t) => G.addressesFemale(`${RLE}${t}`))],
    [['F', 'F', 'F', 'F'], ['F', 'F', 'F', 'F'], [true, true, true, true]]
  )
  const plain = ['ואת עייפה', 'ראיתי את דני', 'אני כאן ואתה עייף', 'אני הולכת', 'אני הולך את דני', 'tú estás cansada', 'أنتِ جميلة']
  const marked = (t: string) => `${RLE}${t.slice(0, 2)}${'\u2067'}${t.slice(2)}${'\u2069'}${PDF}`
  eq(
    'R19A A.1 marks change no reading: every reader gives the same answer on a line and on the same line with marks around and inside it',
    plain.map((t) => [G.hebrewAddressee(marked(t)), G.speakerGender(marked(t)), G.addressesMale(marked(t)), G.romanceAddressee(marked(t), 'es'), G.referenceAddresseeGender(marked(t), 'ar')]),
    plain.map((t) => [G.hebrewAddressee(t), G.speakerGender(t), G.addressesMale(t), G.romanceAddressee(t, 'es'), G.referenceAddresseeGender(t, 'ar')])
  )
  const flagged = G.designatedFlags({
    source: [{ index: 1, text: 'You look tired.' }],
    output: new Map([[1, 'אתה נראה עייף.']]),
    oracle: new Map([[1, `${RLE}את נראית עייפה.${PDF}`]]),
    helper: { kind: 'opensubtitles', language: 'he', machineTranslated: false },
    sourceLanguage: 'en',
    layers: G.NO_GENDER_LAYERS
  })
  eq('R19A A.1 a marked human Hebrew reference line now flags a masculine output (base addressee repair)', Object.fromEntries(flagged.flags), { 1: [{ axis: 'addressee', requestedGender: 'F', layer: 'addressee' }] })
}

section('R19A A.2 - the speaker reader counts only what the speaker says about themself (gate_ledger §5s.25)')
{
  const G = genderReaders
  const read = (xs: string[]) => Object.fromEntries(xs.map((t) => [t, G.speakerGender(t)]))
  eq(
    'R19A A.2 another subject\'s verb is not the speaker\'s: שהוא מת, כל אחד עובד, זה אומר, היא חושבת, הוא מבטיח — and the speaker\'s own word then decides (Bad Sisters 29, Before Sunset 880)',
    read(['אני אספר לחבריי שהוא מת בשנתו.', 'אני אכתוב במה כל אחד עובד', 'זה אומר שאני חשודה? אני חשודה?', 'זוועה. היא חושבת שאני אשם.', 'אני הולכת להגיד לחברים שלי\nשהוא מת בשנתו.', 'הוא מבטיח לי שהוא לא לוקח סיכונים.\nאבל אני דואגת.', 'אני חושבת שהוא מת.']),
    { 'אני אספר לחבריי שהוא מת בשנתו.': null, 'אני אכתוב במה כל אחד עובד': null, 'זה אומר שאני חשודה? אני חשודה?': null, 'זוועה. היא חושבת שאני אשם.': null, 'אני הולכת להגיד לחברים שלי\nשהוא מת בשנתו.': 'F', 'הוא מבטיח לי שהוא לא לוקח סיכונים.\nאבל אני דואגת.': null, 'אני חושבת שהוא מת.': 'F' }
  )
  eq(
    'R19A A.2 the speaker\'s own evidence is kept: הייתי + form, a sentence-opening (לא) יודע / מצטער, the copula אני הוא זה ש, a pause (…) inside the clause, and a comma that does not close it',
    read(['הייתי צריכה להוציא את זה. אני-', 'לא יודעת, אבל אני אשרוד.', 'מצטער, אני...', 'אני נפגשת עם חברה הערב. מצטערת.', 'אני הוא זה שהיה צריך להוכיח', 'אני... לא יודע', 'אני עייפה, לכי', 'אם הייתי יודעת מה אני עושה']),
    { 'הייתי צריכה להוציא את זה. אני-': 'F', 'לא יודעת, אבל אני אשרוד.': 'F', 'מצטער, אני...': 'M', 'אני נפגשת עם חברה הערב. מצטערת.': 'F', 'אני הוא זה שהיה צריך להוכיח': 'M', 'אני... לא יודע': 'M', 'אני עייפה, לכי': 'F', 'אם הייתי יודעת מה אני עושה': 'F' }
  )
  eq(
    'R19A A.2 a copula needs to touch "I": after a comma הוא is a new subject again; a clause end and a second-person pronoun close the clause; a dialogue dash starts a new sentence',
    read(['אני, הוא אומר', 'אני עייף. הולכת?', '- אני כאן.\n- יודעת', 'אני חושב שאתם עייפים']),
    { 'אני, הוא אומר': null, 'אני עייף. הולכת?': 'M', '- אני כאן.\n- יודעת': 'F', 'אני חושב שאתם עייפים': null }
  )
  const flagsOf = (ref: string, out: string) =>
    G.designatedFlags({
      source: [{ index: 1, text: 'line' }],
      output: new Map([[1, out]]),
      oracle: new Map([[1, ref]]),
      helper: { kind: 'opensubtitles', language: 'he', machineTranslated: false },
      sourceLanguage: 'en',
      layers: { ...G.NO_GENDER_LAYERS, speaker: true }
    }).flags.size
  eq(
    'R19A A.2 finding 4 end to end: a reference "I will tell my friends he died" no longer asks a feminine speaker to become masculine; a real masculine reference still does',
    [flagsOf('אני אספר לחבריי שהוא מת בשנתו.', 'אני הולכת להגיד לחברים שלי\nשהוא מת בשנתו.'), flagsOf('אני הולך הביתה.', 'אני הולכת הביתה.')],
    [0, 1]
  )
}

section('R19A A.3 - the repair guard rejects a mismatched "you" and stray characters (gate_ledger §5s.26)')
{
  const G = genderReaders
  const mix = (xs: string[]) => xs.map((t) => G.mixedAddress(t))
  eq(
    'R19A A.3 mixedAddress: אתה + a feminine present form, reviewed predicate or 2fs future (after up to three intensifiers), or a clause את + a masculine present form',
    [
      mix(['אתה חושבת שזה טוב', 'אתה תוכלי לבוא', 'אתה ממש לא יודעת', 'ואתה צודקת', 'טוב, את חושב שכן?', 'אתה תלכי הביתה']),
      mix(['אתה רוצה', 'אתה טועה', 'אתה חושב שזה טוב', 'את חושבת שזה טוב', 'ראיתי את חושב', 'את הולך', 'אתה תלמידי', 'אני חושבת שאתה צודק'])
    ],
    [[true, true, true, true, true, true], [false, false, false, false, false, false, false, false]]
  )
  type C = { index: number; startMs: number; endMs: number; text: string }
  const cue = (text: string): C[] => [{ index: 1, startMs: 1000, endMs: 1800, text }]
  const want = (g: 'M' | 'F') => new Map([[1, [{ axis: 'addressee' as const, requestedGender: g, layer: 'addressee' as const }]]])
  const splice = (old: string, g: 'M' | 'F', reply: string) => {
    const r = genderRepair.spliceRepair(cue(old), want(g), `1\n00:00:01,000 --> 00:00:01,800\n${reply}`)
    return [r.cues[0].text, [...r.rejected.keys()].join(',') || 'accepted']
  }
  eq(
    'R19A A.3 a reply that creates אתה + feminine verb passes the addressee veto today and is now rejected as mixedGender; the grammatical reply is accepted; a mismatch the old cue already held does not block an otherwise valid fix',
    [
      splice('את חושבת שזה טוב', 'M', 'אתה חושבת שזה טוב'),
      splice('את תוכלי לבוא', 'M', 'אתה תוכלי לבוא'),
      splice('את חושבת שזה טוב', 'M', 'אתה חושב שזה טוב'),
      splice('את צודקת. אתה תוכלי לבוא', 'M', 'אתה צודק. אתה תוכלי לבוא')
    ],
    [
      ['את חושבת שזה טוב', 'mixedGender'],
      ['את תוכלי לבוא', 'mixedGender'],
      ['אתה חושב שזה טוב', 'accepted'],
      ['אתה צודק. אתה תוכלי לבוא', 'accepted']
    ]
  )
  eq(
    'R19A A.3 stray characters: an added Arabic or Latin letter or an added backslash is rejected as strayLetters; a Latin name the cue already had is kept; a model-escaped \\" is spliced as " when the old cue had no backslash, and is not unescaped when it had one',
    [
      splice('אה, אתה עייף', 'F', 'אه, את עייפה'),
      splice('אתה עייף', 'F', 'את עייפה OK'),
      splice('אתה עייף, Dan', 'F', 'את עייפה, Dan'),
      splice('אמרת "שלום", אתה עייף', 'F', 'אמרת \\"שלום\\", את עייפה'),
      splice('אמרת "שלום", אתה עייף', 'F', 'אמרת "שלום"\\, את עייפה'),
      splice('C:\\ אתה עייף', 'F', 'C:\\ את עייפה \\"')
    ],
    [
      ['אה, אתה עייף', 'strayLetters'],
      ['אתה עייף', 'strayLetters'],
      ['את עייפה, Dan', 'accepted'],
      ['אמרת "שלום", את עייפה', 'accepted'],
      ['אמרת "שלום", אתה עייף', 'strayLetters'],
      ['C:\\ אתה עייף', 'strayLetters']
    ]
  )
}

section('R19A A.4 - a gender flip on an axis the cue did not request is put back (gate_ledger §5s.27)')
{
  type C = { index: number; startMs: number; endMs: number; text: string }
  type Ax = genderReaders.GenderAxis
  const splice = (old: string, wanted: [Ax, 'M' | 'F'][], reply: string) => {
    const r = genderRepair.spliceRepair(
      [{ index: 1, startMs: 1000, endMs: 1800, text: old } as C],
      new Map([[1, wanted.map(([axis, requestedGender]) => ({ axis, requestedGender, layer: axis === 'speaker' ? ('speaker' as const) : ('addressee' as const) }))]]),
      `1\n00:00:01,000 --> 00:00:01,800\n${reply}`
    )
    return [r.cues[0].text, [...r.rejected.keys()].join(',') || 'accepted']
  }
  eq(
    'R19A A.4 finding 2 (Before Sunset 314, 593, 594, addressee F requested): the addressee fix is kept and the speaker\'s own words go back to masculine',
    [
      splice('ובכן, אני מתכוון, אתה יודע, כמו...', [['addressee', 'F']], 'ובכן, אני מתכוונת, את יודעת, כמו...'),
      splice('הנה אני, כן, חמדן\nלהיות רוחני יותר, אתה יודע?', [['addressee', 'F']], 'הנה אני, כן, חמדנית\nלהיות רוחנית יותר, את יודעת?'),
      splice('אני רוצה להיות בן אדם טוב יותר, אתה יודע?', [['addressee', 'F']], 'אני רוצה להיות בת אדם טובה יותר, את יודעת?')
    ],
    [
      ['ובכן, אני מתכוון, את יודעת, כמו...', 'accepted'],
      ['הנה אני, כן, חמדן\nלהיות רוחני יותר, את יודעת?', 'accepted'],
      ['אני רוצה להיות בן אדם טוב יותר, את יודעת?', 'accepted']
    ]
  )
  eq(
    'R19A A.4 the same reply under two requests: speaker only → the +י addressee form goes back; speaker and addressee → nothing goes back',
    [splice('אני עייף, תגיד לי', [['speaker', 'F']], 'אני עייפה, תגידי לי'), splice('אני עייף, תגיד לי', [['speaker', 'F'], ['addressee', 'F']], 'אני עייפה, תגידי לי')],
    [['אני עייפה, תגיד לי', 'accepted'], ['אני עייפה, תגידי לי', 'accepted']]
  )
  eq(
    'R19A A.4 limits: a reply that only flips the unrequested axis is rejected as unrequestedAxis; a reply whose word count differs is left to the rest of the guard; a third-person change (no "I"/"you" clause) is not put back',
    [
      splice('ובכן, אני מתכוון, אתה יודע', [['addressee', 'F']], 'ובכן, אני מתכוונת, אתה יודע'),
      splice('אני מתכוון, אתה יודע', [['addressee', 'F']], 'אני מתכוונת, את יודעת היטב'),
      splice('הוא עייף, אתה יודע', [['addressee', 'F']], 'היא עייפה, את יודעת')
    ],
    [
      ['ובכן, אני מתכוון, אתה יודע', 'unrequestedAxis'],
      ['אני מתכוונת, את יודעת היטב', 'accepted'],
      ['היא עייפה, את יודעת', 'accepted']
    ]
  )
}

section('R19A A.5 - with Speaker on, the repair is two requests by axis; with Speaker off it is byte-identical (D19A-1, gate_ledger §5s.28)')
{
  const R = genderRepair
  type C = { index: number; startMs: number; endMs: number; text: string }
  type Fix = genderReaders.GenderCorrection
  const mk = (texts: string[]): C[] => texts.map((text, i) => ({ index: i + 1, startMs: 1000 * (i + 1), endMs: 1000 * (i + 1) + 800, text }))
  const blk = (n: number, text: string) => `${n}\n00:00:01,000 --> 00:00:01,800\n${text}`
  const addr: Fix[] = [{ axis: 'addressee', requestedGender: 'F', layer: 'addressee' }]
  const spk: Fix[] = [{ axis: 'speaker', requestedGender: 'F', layer: 'speaker' }]
  const source = mk(['You are very tired.', "I'm tired.", 'You are tired.'])
  const output = mk(['אתה עייף מאוד', 'אני עייף', 'אתה עייף'])
  const oracle = new Map([[1, 'את עייפה מאוד'], [2, 'אני עייפה'], [3, 'את עייפה']])
  const fixed: Record<number, string> = { 1: 'את עייפה מאוד', 2: 'אני עייפה', 3: 'את עייפה' }
  const record = () => {
    const calls: { prompt: string; numbers: number[] }[] = []
    const send = async (prompt: string, numbers: readonly number[] = []): Promise<genderRepair.ModelReply> => {
      calls.push({ prompt, numbers: [...numbers] })
      return { kind: 'text', text: Object.entries(fixed).map(([n, t]) => blk(Number(n), t)).join('\n\n') }
    }
    return { calls, send }
  }
  const input = (flags: Map<number, Fix[]>, out: C[] = output, src: C[] = source, orc: Map<number, string> = oracle) => ({ source: src, output: out, flags, oracle: orc, referenceLanguage: 'he' })

  const noSpeaker = new Map([[1, addr], [3, addr]])
  const a = record()
  const b = record()
  const byAxis = await R.repairGenderByAxis(input(noSpeaker), a.send)
  const single = await R.repairGender(input(noSpeaker), (p) => b.send(p, [1, 3]))
  eq(
    'R19A A.5 no speaker correction (Speaker off): one request, the same prompt bytes and flagged numbers as the single repair, the same cues',
    [a.calls.length, a.calls[0].prompt === b.calls[0].prompt, a.calls[0].numbers, byAxis.cues.map((c) => c.text), byAxis.accepted],
    [1, true, [1, 3], single.cues.map((c) => c.text), single.accepted]
  )

  const two = record()
  const r = await R.repairGenderByAxis(input(new Map([[1, addr], [2, spk], [3, addr]])), two.send)
  const o = (l: genderReaders.GenderLayer) => {
    const x = r.layers.get(l)!
    return [x.requested, x.eligible, x.attempted, x.proposedCount, x.acceptedCount, x.skip]
  }
  eq(
    'R19A A.5 with a speaker correction: request 1 = the addressee-only cues with the 0.2.533 prompt, request 2 = the speaker cue with the two-axis prompt on request 1\'s result; every fix lands and the layer counts add up',
    [
      two.calls.map((c) => [c.numbers, c.prompt.startsWith(R.ADDRESSEE_REPAIR_PROMPT), c.prompt.startsWith(R.AXIS_REPAIR_PROMPT)]),
      r.cues.map((c) => c.text),
      r.accepted,
      o('addressee'),
      o('speaker')
    ],
    [[[[1, 3], true, false], [[2], false, true]], ['את עייפה מאוד', 'אני עייפה', 'את עייפה'], 3, [2, 2, 2, 2, 2, null], [1, 1, 1, 1, 1, null]]
  )

  // Finding 1: fifteen speaker flags with long evidence fill the 24 000-character cap before a late base fix.
  const many = mk([...Array.from({ length: 15 }, () => "I'm tired."), 'You are tired.'])
  const manyOut = mk([...Array.from({ length: 15 }, () => 'אני עייף'), 'אתה עייף'])
  const manyOracle = new Map<number, string>([...Array.from({ length: 15 }, (_, i) => [i + 1, `אני עייפה ${'א'.repeat(1900)}`] as [number, string]), [16, 'את עייפה']])
  const manyFlags = new Map<number, Fix[]>([...Array.from({ length: 15 }, (_, i) => [i + 1, spk] as [number, Fix[]]), [16, addr]])
  const lateReply = async (): Promise<genderRepair.ModelReply> => ({ kind: 'text', text: blk(16, 'את עייפה') })
  const oneRequest = await R.repairGender(input(manyFlags, manyOut, many, manyOracle), lateReply)
  const byAxisMany = await R.repairGenderByAxis(input(manyFlags, manyOut, many, manyOracle), lateReply)
  eq(
    'R19A A.5 finding 1: fifteen long speaker items fill the cap and a single request never sends the late base fix (cue 16); split by axis it is sent first and lands',
    [oneRequest.cues[15].text, byAxisMany.cues[15].text, byAxisMany.layers.get('addressee')?.acceptedCount],
    ['אתה עייף', 'את עייפה', 1]
  )

  const failFirst: { numbers: number[] }[] = []
  const r2 = await R.repairGenderByAxis(input(new Map([[1, addr], [2, spk]])), async (prompt, numbers) => {
    failFirst.push({ numbers: [...numbers] })
    return failFirst.length === 1 ? { kind: 'failed' } : { kind: 'text', text: blk(2, 'אני עייפה') }
  })
  eq(
    'R19A A.5 a failed first request keeps its cues and the second is still sent and judged on its own',
    [failFirst.map((c) => c.numbers), r2.cues.map((c) => c.text), r2.layers.get('addressee')?.skip, r2.layers.get('speaker')?.acceptedCount],
    [[[1], [2]], ['אתה עייף מאוד', 'אני עייפה', 'אתה עייף'], 'failed', 1]
  )
  const severity = async (first: genderRepair.ModelReply, second: genderRepair.ModelReply) => {
    let n = 0
    const s = await R.repairGenderByAxis(input(new Map([[1, addr], [2, [...addr, ...spk]]])), async () => (n++ === 0 ? first : second))
    return [s.layers.get('addressee')?.skip, s.layers.get('speaker')?.skip]
  }
  eq(
    'R19A A.5 a layer in both requests reports the more serious skip whichever request had it (failed before refused), and a layer in one request keeps its own',
    [await severity({ kind: 'failed' }, { kind: 'refused' }), await severity({ kind: 'refused' }, { kind: 'failed' })],
    [['failed', 'refused'], ['failed', 'failed']]
  )

  const finish = async (speaker: boolean) => {
    const sent: number[][] = []
    const f = await genderFinish({
      source: source.slice(0, 2),
      output: output.slice(0, 2),
      preserved: new Set(),
      reference: { helper: { kind: 'opensubtitles', language: 'he', machineTranslated: false }, language: 'he', lines: new Map([[1, 'את עייפה מאוד'], [2, 'אני עייפה']]), log: [] },
      sourceLanguage: 'en',
      layers: { ...genderReaders.NO_GENDER_LAYERS, speaker },
      send: async (_prompt, numbers) => {
        sent.push([...numbers])
        return { kind: 'text', text: [blk(1, 'את עייפה מאוד'), blk(2, 'אני עייפה')].join('\n\n') }
      }
    })
    return [sent, f.cues.map((c) => c.text), f.log.filter((l) => /^Gender check|speaker:/.test(l))]
  }
  eq(
    'R19A A.5 end to end (genderFinish): Speaker on sends the base cue, then the speaker cue, and the log adds both; Speaker off sends the base cue alone',
    [await finish(true), await finish(false)],
    [
      [
        [[1], [2]],
        ['את עייפה מאוד', 'אני עייפה'],
        ['Gender check: 2 lines read the other gender from the reference; 2 corrected.', 'Advanced Hebrew correction, speaker: requested 1, eligible 1, attempted 1, proposed 1, accepted 1.']
      ],
      [[[1]], ['את עייפה מאוד', 'אני עייף'], ['Gender check: 1 line read the other gender from the reference; 1 corrected.']]
    ]
  )
}

section('R19A A.6 - a C1-marked cue the Hebrew reader cannot read is read by the pronoun alone (D19A-2, gate_ledger §5s.29)')
{
  const G = genderReaders
  eq(
    'R19A A.6 pronounAddressee: a pronoun את → F, אתה → M; an object marker, both, or neither → null',
    ['את משוגעת.', 'אז, את לבדך, או--', 'אתה לבד?', 'ראיתי את זה', 'את האיש', 'אתה ואת', 'שלום'].map((t) => G.pronounAddressee(t)),
    ['F', 'F', 'M', null, null, null, null]
  )
  const flags = (helperLang: string, ref: string, out: string, layers: genderReaders.GenderLayers) =>
    Object.fromEntries(
      G.designatedFlags({
        source: [{ index: 1, text: 'line' }],
        output: new Map([[1, out]]),
        oracle: new Map([[1, ref]]),
        helper: { kind: 'opensubtitles', language: helperLang, machineTranslated: false },
        sourceLanguage: 'en',
        layers
      }).flags
    )
  const es = { ...G.NO_GENDER_LAYERS, c1Spanish: true }
  const pt = { ...G.NO_GENDER_LAYERS, c1Portuguese: true }
  eq(
    'R19A A.6 finding 6 (Before Sunset 853 and 1423, Bad Sisters 315): C1 alone now flags the masculine "you" the Hebrew gave as את, on the C1 layer; with C1 off nothing is flagged',
    [
      flags('es', 'No voy a cantar sin una guitarra. Estás loco.', 'אני לא שר שיר בלי גיטרה.\nאת משוגעת.', es),
      flags('es', '¿Qué crees, que escribí esa canción sobre ti? ¿Estás loco?', 'את משוגעת? (מצחקק)', es),
      flags('pt', 'Não. Então, estás sozinho ou… - Não, não vamos… Não.', '- אוי, לא. אז, את לבדך, או--\n- לא, בוא לא-- לא.', pt),
      flags('es', 'No voy a cantar sin una guitarra. Estás loco.', 'אני לא שר שיר בלי גיטרה.\nאת משוגעת.', G.NO_GENDER_LAYERS)
    ],
    [
      { 1: [{ axis: 'addressee', requestedGender: 'M', layer: 'c1Spanish' }] },
      { 1: [{ axis: 'addressee', requestedGender: 'M', layer: 'c1Spanish' }] },
      { 1: [{ axis: 'addressee', requestedGender: 'M', layer: 'c1Portuguese' }] },
      {}
    ]
  )
  eq(
    'R19A A.6 the base reader is untouched: an Arabic reference wanting M over את משוגעת still raises nothing; a pronoun that already agrees with C1 raises nothing',
    [flags('ar', 'أنتَ مجنون', 'את משוגעת.', { ...G.NO_GENDER_LAYERS, c1Spanish: true, c1Portuguese: true }), flags('es', '¿Y estás enamorada de ese tipo?', 'אז, את מאוהבת בבחור ההוא?', es)],
    [{}, {}]
  )
  const splice = (layer: genderReaders.GenderLayer, old: string, reply: string) => {
    const r = genderRepair.spliceRepair(
      [{ index: 1, startMs: 1000, endMs: 1800, text: old }],
      new Map([[1, [{ axis: 'addressee' as const, requestedGender: 'F' as const, layer }]]]),
      `1\n00:00:01,000 --> 00:00:01,800\n${reply}`
    )
    return [r.cues[0].text, [...r.rejected.keys()].join(',') || 'accepted']
  }
  eq(
    'R19A A.6 the veto of a C1 correction reads the pronoun too: את משוגעת is accepted for a C1 request and still vetoed for a base request',
    [splice('c1Spanish', 'אתה משוגע?', 'את משוגעת?'), splice('c1Portuguese', 'אתה לבד?', 'את לבד?'), splice('addressee', 'אתה משוגע?', 'את משוגעת?')],
    [['את משוגעת?', 'accepted'], ['את לבד?', 'accepted'], ['אתה משוגע?', 'readerVeto']]
  )
}

section('R19A A.7 - other-alphabet letters in Hebrew output: one guarded redo request before the gender step, on every Hebrew run (D19A-3, gate_ledger §5s.30)')
{
  const S = strayAlphabet
  eq(
    'R19A A.7 what qualifies: Hebrew plus a Thai, Chinese, Devanagari, Korean or Telugu letter; never Latin, Arabic, Cyrillic, Greek or Armenian (Round 11 handles those), never a line without Hebrew, never the source\'s own script',
    [
      ['- אอย, לא.', 'זה 好 טוב', 'אני नम', 'שלום 안', 'אה తె'].map((t) => S.hasStrayAlphabet(t, null)),
      ['שלום Dan', 'אه שלום', 'אпривет', 'אα', 'אա', '你好', 'שלום!'].map((t) => S.hasStrayAlphabet(t, null)),
      [S.hasStrayAlphabet('זה 好 טוב', 'CJK'), S.hasStrayAlphabet('זה カ טוב', 'CJK'), S.hasStrayAlphabet('זה ก טוב', 'CJK')],
      [S.sourceStrayScript([{ text: 'Oh, no. So, are you on your own?' }]), S.sourceStrayScript([{ text: 'สวัสดีครับ Tom' }]), S.sourceStrayScript([{ text: 'こんにちは、東京' }])]
    ],
    [[true, true, true, true, true], [false, false, false, false, false, false, false], [false, false, true], [null, 'Thai', 'CJK']]
  )
  type C = { index: number; startMs: number; endMs: number; text: string }
  const mk = (texts: string[]): C[] => texts.map((text, i) => ({ index: i + 1, startMs: 1000 * (i + 1), endMs: 1000 * (i + 1) + 800, text }))
  const blk = (n: number, text: string) => `${n}\n00:00:09,000 --> 00:00:09,800\n${text}`
  const source = mk(['- Oh, no. So, are you on your own, or--\n- No, let\'s not-- no.', 'Fine.', 'Two of them.', 'Yes.'])
  const output = mk(['- אอย, לא. אז, את לבדך, או--\n- לא, בוא לא-- לא.', 'בסדר', 'שניים מהם 好.', 'כן 안'])
  const repair = async (reply: genderRepair.ModelReply | null, preserved: Set<number> = new Set(), out: C[] = output) => {
    const sent: { prompt: string; numbers: number[] }[] = []
    const r = await S.repairStrayAlphabet({ source, output: out, preserved }, async (prompt, numbers) => {
      sent.push({ prompt, numbers: [...numbers] })
      if (!reply) throw new Error('down')
      return reply
    })
    return { ...r, sent }
  }
  const good = await repair({ kind: 'text', text: [blk(1, '- אוי, לא. אז, את לבדך, או--\n- לא, בוא לא-- לא.'), blk(3, 'שניים מהם טוב.'), blk(4, 'כן 안'), blk(2, 'בסדר גמור')].join('\n\n') })
  eq(
    'R19A A.7 one request names exactly the affected cues with the redo prompt; a clean reply is spliced (number and times kept), a reply that still holds the letters is not, an unasked cue is never touched; the log counts and names what is left',
    [
      good.sent.map((s) => [s.numbers, s.prompt.startsWith(S.STRAY_ALPHABET_PROMPT)]),
      good.cues.map((c) => `${c.index}|${c.startMs}|${c.text}`),
      good.log
    ],
    [
      [[[1, 3, 4], true]],
      ['1|1000|- אוי, לא. אז, את לבדך, או--\n- לא, בוא לא-- לא.', '2|2000|בסדר', '3|3000|שניים מהם טוב.', '4|4000|כן 안'],
      ['Other-alphabet check: 3 lines held letters of another alphabet; 2 corrected.', 'Other-alphabet check: still affected: line 4.']
    ]
  )
  const guarded = await repair({ kind: 'text', text: [blk(1, '- אוי, לא. אז, את לבדך\n- לא, בוא לא-- לא.\nעוד'), blk(3, 'לא שניים מהם.'), blk(4, 'אולי לגמרי משהו אחר לחלוטין')].join('\n\n') })
  const failed = await repair(null)
  const refused = await repair({ kind: 'refused' })
  const kept = await repair({ kind: 'text', text: blk(1, '- אוי, לא. אז, את לבדך, או--\n- לא, בוא לא-- לא.') }, new Set([1, 3, 4]))
  const none = await repair({ kind: 'text', text: '' }, new Set(), mk(['בסדר', 'שלום Dan', 'אه', 'כן']))
  eq(
    'R19A A.7 guards and fail-soft: a changed line count, an added negation and a rewrite far from the line are refused; a failed or refused request keeps every cue; a cue kept in the source language is never asked about; nothing is sent and nothing logged when no cue qualifies',
    [
      guarded.cues.map((c) => c.text),
      [failed, refused].map((x) => [x.cues.map((c) => c.text), x.accepted, x.log[0]]),
      [kept.sent.length, kept.found],
      [none.sent.length, none.log]
    ],
    [
      output.map((c) => c.text),
      [0, 1].map(() => [output.map((c) => c.text), 0, 'Other-alphabet check: 3 lines held letters of another alphabet; 0 corrected.']),
      [0, 0],
      [0, []]
    ]
  )
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'ng-r19a-a7-'))
  try {
    const src = mk(['Oh, no.', 'Fine.'])
    let runs = 0
    const runIt = async (targetLang: string, heOut: string[], redo?: BatchAnswer) => {
      const requests: PreparedTranslationRequest[] = []
      const events: RunEvent[] = []
      const out = path.join(tmp, `out${++runs}.${targetLang}.srt`)
      const r = await runTranslation({
        runId: 'r19a-a7',
        args: baseArgs({ inputFile: path.join(tmp, 'in.srt'), batchSize: 8, model: 'gemini-3.5-flash-lite', targetLang }),
        outputPath: out,
        signal: new AbortController().signal,
        isCurrent: () => true,
        emit: (e) => events.push(e),
        translateBatch: async (p) => {
          requests.push(p)
          if (p.responseSchemaId === 'none' && !p.request.systemInstruction) return redo ?? { ok: true, text: blk(1, 'אוי, לא.') }
          return { ok: true, text: JSON.stringify(batchItems(p.request).map((i) => ({ index: i.index, text: heOut[Number(i.index)] }))) }
        },
        retryBudget: new RetryBudget(),
        resend: { clock: { now: () => 0, sleep: async () => true } },
        registerScratch: () => {},
        releaseScratch: () => {},
        readSource: () => serializeCues(src, '\n')
      })
      const read = fs.existsSync(out) ? parseCues(fs.readFileSync(out, 'utf-8')) : null
      return {
        outcome: r.outcome,
        requests: requests.map((p) => (p.responseSchemaId === 'none' && !p.request.systemInstruction ? `redo:${[...p.requestedIndices].join(',')}:${String((p.request.parts[0] as { text: string }).text).startsWith(S.STRAY_ALPHABET_PROMPT)}` : 'batch')),
        written: read?.ok ? read.cues.map((c) => c.text) : null,
        logs: events.flatMap((e) => (e.type === 'log' && /^Other-alphabet/.test(e.text) ? [e.text] : []))
      }
    }
    eq(
      'R19A A.7 end to end: a Hebrew run with no reference sends the redo request after the batches and saves the repaired line; a clean Hebrew run and a non-Hebrew run send nothing extra',
      [await runIt('he', ['אอย, לא.', 'בסדר']), await runIt('he', ['אוי, לא.', 'בסדר']), await runIt('fr', ['Oh, non อย.', 'Bien.'])],
      [
        { outcome: 'completed', requests: ['batch', 'redo:0:true'], written: ['אוי, לא.', 'בסדר'], logs: ['Other-alphabet check: 1 line held letters of another alphabet; 1 corrected.'] },
        { outcome: 'completed', requests: ['batch'], written: ['אוי, לא.', 'בסדר'], logs: [] },
        { outcome: 'completed', requests: ['batch'], written: ['Oh, non อย.', 'Bien.'], logs: [] }
      ]
    )
    const stopped = await runIt('he', ['אอย, לא.', 'בסדר'], { ok: false, error: { kind: 'quota', message: 'QUOTA-JOURNAL-MARKER' }, storage: true })
    eq(
      'R19A A.7 a quota-journal stop on the redo request ends the run with that error before promotion: no output file, nothing sent after it',
      [stopped.outcome, stopped.requests, stopped.written],
      ['failed', ['batch', 'redo:0:true'], null]
    )
  } finally {
    fs.rmSync(tmp, { recursive: true, force: true })
  }
}

section('R19A triage - R19A-01 (a masculine ת..י word is not a feminine future) and R19A-02 (a requested pronoun flip is never put back) (gate_ledger §5s.33)')
{
  type C = { index: number; startMs: number; endMs: number; text: string }
  const cue = (text: string): C[] => [{ index: 1, startMs: 1000, endMs: 1800, text }]
  const splice = (old: string, reply: string) => {
    const r = genderRepair.spliceRepair(cue(old), new Map([[1, [{ axis: 'addressee' as const, requestedGender: 'M' as const, layer: 'addressee' as const }]]]), `1\n00:00:01,000 --> 00:00:01,800\n${reply}`)
    return [r.cues[0].text, [...r.rejected.keys()].join(',') || 'accepted']
  }
  const finish = async (out: string, ref: string, reply: string) => {
    const f = await genderFinish({
      source: [{ index: 1, startMs: 1000, endMs: 1800, text: 'Line.' }],
      output: cue(out),
      preserved: new Set(),
      reference: { helper: { kind: 'opensubtitles', language: 'he', machineTranslated: false }, language: 'he', lines: new Map([[1, ref]]), log: [] },
      sourceLanguage: 'en',
      layers: genderReaders.NO_GENDER_LAYERS,
      send: async () => ({ kind: 'text', text: `1\n00:00:01,000 --> 00:00:01,800\n${reply}` })
    })
    return [f.cues[0].text, f.log.filter((l) => /^Gender check/.test(l))]
  }
  const fixedLog = ['Gender check: 1 line read the other gender from the reference; 1 corrected.']
  eq(
    'R19A triage R19A-01: masculine words shaped ת..י (תלוי, תורכי) are not a feminine future, so אתה + them is not mixed; the listed futures (תוכלי, תלכי, תגידי) still are',
    [genderReaders.mixedAddress('אתה תלוי בי'), genderReaders.mixedAddress('אתה תורכי'), ['אתה תוכלי לבוא', 'אתה תלכי הביתה', 'אתה ממש תגידי לו'].map((t) => genderReaders.mixedAddress(t))],
    [false, false, [true, true, true]]
  )
  eq(
    'R19A triage R19A-01: the grammatical masculine repair את תלויה בי, חכי כאן → אתה תלוי בי, חכה כאן is accepted at the splice and end to end (flag → repair → saved cue)',
    [splice('את תלויה בי, חכי כאן', 'אתה תלוי בי, חכה כאן'), await finish('את תלויה בי, חכי כאן', 'אתה תלוי בי, חכה כאן', 'אתה תלוי בי, חכה כאן')],
    [['אתה תלוי בי, חכה כאן', 'accepted'], ['אתה תלוי בי, חכה כאן', fixedLog]]
  )
  eq(
    'R19A triage R19A-02: an addressee-only masculine repair whose old pronoun looked like an object marker inside the speaker clause (שאת האחת) keeps the requested שאת → שאתה flip, at the splice and end to end',
    [
      splice('אני חושב שאת האחת שלי, חכי כאן', 'אני חושב שאתה האחד שלי, חכה כאן'),
      await finish('אני חושב שאת האחת שלי, חכי כאן', 'אני חושב שאתה האחד שלי, חכה כאן', 'אני חושב שאתה האחד שלי, חכה כאן')
    ],
    [['אני חושב שאתה האחד שלי, חכה כאן', 'accepted'], ['אני חושב שאתה האחד שלי, חכה כאן', fixedLog]]
  )
}

