section('RR-2 W3 - no speaker-gender fix on a cue where two people speak (Before Sunset 257)')
{
  const R = genderRepair
  type C = { index: number; startMs: number; endMs: number; text: string }
  type Fix = genderReaders.GenderCorrection
  const mk = (texts: string[]): C[] => texts.map((text, i) => ({ index: i + 1, startMs: 1000 * (i + 1), endMs: 1000 * (i + 1) + 800, text }))
  const blk = (n: number, text: string) => `${n}\n00:00:01,000 --> 00:00:01,800\n${text}`
  const addr: Fix = { axis: 'addressee', requestedGender: 'F', layer: 'addressee' }
  const spk: Fix = { axis: 'speaker', requestedGender: 'F', layer: 'speaker' }
  const spkB: Fix = { axis: 'speaker', requestedGender: 'F', layer: 'methodB' }

  eq(
    'RR-2 W3 a dialogue dash that opens a later speaker is two speakers: both lines dashed, only the second dashed, inside italics, after invisible direction marks, an en dash, and two speakers on one line',
    ['- Are you sure?\n- I am.', 'Are you sure?\n- I am.', '<i>- Wait.</i>\n<i>- No.</i>', '\u200f- את בטוחה?\n\u200f- אני עייף.', '\u2013 Yes.\n\u2013 No.', 'Hi. - Hello.', '- Hi.\r\n- Hello.'].map(R.twoSpeakers),
    [true, true, true, true, true, true, true]
  )
  eq(
    'RR-2 W3 one speaker is not two: a plain line, a two-line sentence, a single dashed line, a hyphenated word, a mid-sentence dash and a dash ending the first line',
    ['I am tired.', 'I am\nvery tired.', '- I am tired.', 'A well-known man.', 'Wait - what?', 'I am tired -\nreally tired.'].map(R.twoSpeakers),
    [false, false, false, false, false, false]
  )

  const source = mk(['- Are you coming?\n- I am tired.', 'I am tired.', '- Are you tired?\n- Yes.'])
  const output = mk(['- את באה?\n- אני עייף.', 'אני עייף.', '- אתה עייף?\n- כן.'])
  const flags = new Map<number, Fix[]>([[1, [spk]], [2, [spk]], [3, [addr, spkB]]])
  const kept = R.withoutTwoSpeakerFixes({ source, output, flags, oracle: new Map(), referenceLanguage: 'he' })
  eq(
    'RR-2 W3 the filter drops only speaker-axis corrections, only on two-speaker cues (Speaker or Method B layer); an addressee correction on the same cue stays and a one-speaker cue is untouched',
    [[...kept.flags.entries()].map(([n, cs]) => [n, cs.map((c) => `${c.axis}/${c.layer}`)]), kept.skipped],
    [[[2, ['speaker/speaker']], [3, ['addressee/addressee']]], 2]
  )
  const fromOutput = R.withoutTwoSpeakerFixes({ source: mk(['Are you coming? I am tired.']), output: mk(['- את באה?\n- אני עייף.']), flags: new Map([[1, [spk]]]), oracle: new Map(), referenceLanguage: 'he' })
  const fromSource = R.withoutTwoSpeakerFixes({ source: mk(['- Are you coming?\n- I am tired.']), output: mk(['את באה? אני עייף.']), flags: new Map([[1, [spk]]]), oracle: new Map(), referenceLanguage: 'he' })
  eq(
    'RR-2 W3 two speakers in the translation alone, or in the source alone (the model merged the lines), are enough to drop the speaker correction',
    [fromOutput.flags.size, fromOutput.skipped, fromSource.flags.size, fromSource.skipped],
    [0, 1, 0, 1]
  )

  const sends: string[] = []
  const send = async (prompt: string): Promise<genderRepair.ModelReply> => {
    sends.push(prompt)
    return { kind: 'text', text: blk(1, '- את באה?\n- אני עייפה.') }
  }
  const only = await R.repairGender({ source: source.slice(0, 1), output: output.slice(0, 1), flags: new Map([[1, [spk]]]), oracle: new Map([[1, '- את באה?\n- אני עייפה.']]), referenceLanguage: 'he' }, send)
  const sp = only.layers.get('speaker')!
  eq(
    'RR-2 W3 a two-speaker cue with only a speaker correction sends no request and keeps its text; the speaker layer reports requested 1, eligible 0, skipped no_evidence, and the skip is counted',
    [sends.length, only.cues[0].text, [sp.requested, sp.eligible, sp.attempted, sp.acceptedCount, sp.skip], only.twoSpeakerSkipped],
    [0, '- את באה?\n- אני עייף.', [1, 0, 0, 0, 'no_evidence'], 1]
  )
  const byAxis = await R.repairGenderByAxis({ source, output, flags, oracle: new Map([[1, 'x'], [2, 'אני עייפה.'], [3, '- את עייפה?\n- כן.']]), referenceLanguage: 'he' }, async (prompt, numbers) => {
    sends.push(`${numbers.join(',')}|${prompt.startsWith(R.AXIS_REPAIR_PROMPT) ? 'axis' : 'addressee'}`)
    return { kind: 'text', text: [blk(2, 'אני עייפה.'), blk(3, '- את עייפה?\n- כן.')].join('\n\n') }
  })
  eq(
    'RR-2 W3 split by axis: the one-speaker cue still gets its speaker fix and the two-speaker cue its addressee fix; the two-speaker speaker fixes are dropped and counted once each',
    [byAxis.cues.map((c) => c.text), byAxis.twoSpeakerSkipped],
    [['- את באה?\n- אני עייף.', 'אני עייפה.', '- את עייפה?\n- כן.'], 2]
  )

  const finish = async (src: string, out: string, ref: string) => {
    const sent: number[][] = []
    const f = await genderFinish({
      source: mk([src]),
      output: mk([out]),
      preserved: new Set(),
      reference: { helper: { kind: 'opensubtitles', language: 'he', machineTranslated: false }, language: 'he', lines: new Map([[1, ref]]), log: [] },
      sourceLanguage: 'en',
      layers: { ...genderReaders.NO_GENDER_LAYERS, speaker: true },
      send: async (_prompt, numbers) => {
        sent.push([...numbers])
        return { kind: 'text', text: blk(1, ref) }
      }
    })
    return [sent.length, f.cues[0].text, f.log.filter((l) => /two people|speaker:/.test(l))]
  }
  eq(
    'RR-2 W3 end to end with Speaker on (genderFinish): the one-speaker control is sent and fixed; the Before Sunset 257 shape is flagged but not sent, keeps both speakers as translated, and the log counts it',
    [
      await finish('I am tired.', 'אני עייף.', 'אני עייפה.'),
      await finish('- Are you coming?\n- I am tired.', '- את באה?\n- אני עייף.', '- את באה?\n- אני עייפה.')
    ],
    [
      [1, 'אני עייפה.', ['Advanced Hebrew correction, speaker: requested 1, eligible 1, attempted 1, proposed 1, accepted 1.']],
      [
        0,
        '- את באה?\n- אני עייף.',
        ['Advanced Hebrew correction, speaker: requested 1, eligible 0, attempted 0, proposed 0, accepted 0, skipped: no_evidence.', 'Gender check: 1 line where two people speak kept the speaker gender as translated.']
      ]
    ]
  )
  const addrOnly = await R.repairGender({ source: mk(['- Are you tired?\n- Yes.']), output: mk(['- אתה עייף?\n- כן.']), flags: new Map([[1, [addr]]]), oracle: new Map([[1, '- את עייפה?\n- כן.']]), referenceLanguage: 'he' }, async () => ({ kind: 'text', text: blk(1, '- את עייפה?\n- כן.') }))
  eq('RR-2 W3 Speaker off is unchanged: an addressee fix on a two-speaker cue is still sent and lands, and nothing is counted', [addrOnly.cues[0].text, addrOnly.twoSpeakerSkipped], ['- את עייפה?\n- כן.', 0])

  const tip = settingsPageH.ADVANCED_HEBREW_TOGGLES.find((t) => t.key === 'hebrewSpeakerRepair')?.tip ?? ''
  check(
    'RR-2 W3 the Speaker "?" no longer says a two-speaker line can be changed to one gender; it says such a line is left as translated',
    !/both can be changed to one gender/.test(tip) && tip.includes('\n- A line where two people speak is left as translated, so a wrong speaker gender there is not fixed.')
  )
}

section('RR-3 release-test fixes')
{
  const page = fs.readFileSync(path.join(process.cwd(), 'src', 'pages', 'SettingsPage.tsx'), 'utf8')
  const service = page.slice(page.indexOf('function SectionService('), page.indexOf('function SectionTmdb('))
  check(
    'RR-3 Settings › Service has no Disable Streaming switch (every request already waits for the whole response, D4); the stored value is still defaulted for old profiles and paused jobs',
    service.length > 500 && !/Disable Streaming|disableStreaming/.test(page) && DEFAULT_SETTINGS.disableStreaming === false
  )
  check(
    'RR-3 Settings › Service › Paid Quota names the highest-ranked key, not the retired command-line flag (-k / promoted key)',
    service.includes('the highest-ranked key. ') && !/sends as -k|engine is told which quota/.test(page)
  )

  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'rr3-pick-'))
  const put = (name: string, text: string): string => {
    const p = path.join(dir, name)
    fs.writeFileSync(p, text)
    return p
  }
  const srt = '1\n00:00:01,000 --> 00:00:02,000\nI think he was right all along and we should have listened to him.\n\n2\n00:00:03,000 --> 00:00:04,000\nThere is nothing more that I can do for you tonight.\n'
  const pick = (p: string) => {
    const r = inspectSubtitleRequest({ path: p })
    return r.ok ? 'ok' : `${r.code}: ${r.error}`
  }
  eq(
    'RR-3 subtitle:inspect refuses at pick what Start would refuse, with Start\u2019s sentence: a text file renamed .srt, a UTF-8 .ass, WebVTT named .srt, text before the first cue; a SubRip file still passes',
    [
      pick(put('notes.srt', 'Shopping list\r\nmilk, eggs, bread\r\nCall the bank on Monday.\r\n')),
      pick(put('styled.ass', '[Script Info]\nTitle: t\n\n[Events]\nFormat: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text\nDialogue: 0,0:00:01.00,0:00:03.00,Default,,0,0,0,,Hello there.\n')),
      pick(put('web.srt', 'WEBVTT\n\n00:00:01.000 --> 00:00:02.000\nHello there.\n')),
      pick(put('preface.srt', `Downloaded from somewhere\n\n${srt}`)),
      pick(put('good.srt', srt))
    ],
    [
      'not-srt: This file has no subtitle timings, so there is nothing to translate.',
      'not-srt: This is an ASS/SSA subtitle. The built-in translator reads SubRip (.srt) files only.',
      'not-srt: This is a WebVTT subtitle. The built-in translator reads SubRip (.srt) files only.',
      'not-srt: Line 1 has text before the first subtitle. It belongs to no subtitle and would be lost, so the file was not translated.',
      'ok'
    ]
  )
  fs.rmSync(dir, { recursive: true, force: true })
  const tp = fs.readFileSync(path.join(process.cwd(), 'src', 'pages', 'TranslatePage.tsx'), 'utf8')
  check(
    'RR-3 the Translate page no longer offers .ass as translatable (D3): the field reads "Subtitle File (.srt)", its help says an .ass is refused, and the missing-input sentence names .srt only',
    tp.includes('Subtitle File (.srt)') && tp.includes('An .ass/.ssa file is refused when you choose it') && !/\.srt or \.ass|saved back as \.ass/.test(tp) && (tp.match(/Provide a subtitle file \(\.srt\), or a video with a selectable text track\./g) ?? []).length === 2
  )
}

section('RR-4 tester requests 2026-10-18 - name, paid fallback on overload, Advanced Hebrew master, tooltips')
{
  const app = fs.readFileSync(path.join(process.cwd(), 'src', 'App.tsx'), 'utf8')
  const header = app.slice(app.indexOf('<header'), app.indexOf('</header>'))
  check(
    'RR-4 the header reads "SRT AI Translator NG" with a smaller "(New Generation)" right after it on the same line; the window title matches; the old "Gemini SRT Translator" name is gone',
    /<div className="flex items-baseline[^"]*">\s*<h1 className="text-lg [^"]*">SRT AI Translator NG<\/h1>\s*<span className="text-xs [^"]*">\(New Generation\)<\/span>\s*<\/div>/.test(header) && !/Gemini SRT Translator/.test(app) &&
      fs.readFileSync(path.join(process.cwd(), 'index.html'), 'utf8').includes('<title>SRT AI Translator NG</title>') &&
      fs.readFileSync(path.join(process.cwd(), 'electron', 'main', 'index.ts'), 'utf8').includes("title: 'SRT AI Translator NG',")
  )
  const sp = fs.readFileSync(path.join(process.cwd(), 'src', 'pages', 'SettingsPage.tsx'), 'utf8')
  check(
    'RR-4 Allow paid fallback: its line and its tooltip both say an overload on the Free keys also moves to the Paid key, the tooltip says at once instead of the 60-second pause and that the next request tries Free first',
    sp.includes('desc="Off by default. Continues on a Paid key when Google refuses the Free keys, they have used today’s requests, or the model is overloaded on them. Paid requests can cost money."') &&
      sp.includes('or when Google says the model is overloaded on a Free key. On an overload the request goes to the Paid key at once instead of pausing 60 seconds, and the next request tries the Free key again first.')
  )
  check(
    'RR-4 System Prompt Override tooltip says the text is added after the built-in instructions and replaces none of them',
    sp.includes('They are added after the app\'s built-in instructions and replace none of them') && !sp.includes('overrides the built-in translation instructions')
  )
  const strength = genderPanelH.REFERENCE_STRENGTH_TIP
  check(
    'RR-4 Reference Strength tooltip names a choice per reference language and marks the untested ones as estimates: Hebrew Hard, Arabic Hard (estimate), German Hint (tested), every other language Hint (estimate)',
    /Hebrew reference: Hard/.test(strength) && /Arabic reference: Hard\. An estimate, not yet tested/.test(strength) && /German reference: Hint[^\n]*Tested/.test(strength) &&
      /Any other language[^\n]*: Hint\. An estimate, not yet tested/.test(strength) && /always into Hebrew/.test(strength) && !/recommended for Hebrew/.test(strength)
  )
  const view = (raw: Record<string, unknown>) => sanitizeSettingsView({ schemaVersion: CURRENT_SCHEMA_VERSION, ...raw }, DEFAULT_SETTINGS).settings.hebrewAdvanced
  eq(
    'RR-4 the Advanced Hebrew master as a profile reads it: a new install is off; a profile that never stored it is on exactly when one of the four is stored on; a stored value of either kind wins',
    [view({}), view({ hebrewMethodB: false, hebrewSpeakerRepair: false }), view({ hebrewC1Portuguese: true }), view({ hebrewAdvanced: false, hebrewSpeakerRepair: true }), view({ hebrewAdvanced: true })],
    [false, false, true, false, true]
  )
  const T = translatePageH
  const allOn = { hebrewSpeakerRepair: true, hebrewMethodB: true, hebrewC1Spanish: true, hebrewC1Portuguese: true }
  const base = { ...(pristineProfile() as unknown as AppSettings), apiKeys: ['K'], ...allOn }
  const offArgs = T.runSettingsArgs({ ...base, hebrewAdvanced: false } as AppSettings, '')
  const onArgs = T.runSettingsArgs({ ...base, hebrewAdvanced: true } as AppSettings, '')
  eq(
    'RR-4 a Start with the master off sends all four layers off whatever they store, and the idle card shows none; with it on they go as stored',
    [
      [offArgs.hebrewSpeakerRepair, offArgs.hebrewMethodB, offArgs.hebrewC1Spanish, offArgs.hebrewC1Portuguese],
      [onArgs.hebrewSpeakerRepair, onArgs.hebrewMethodB, onArgs.hebrewC1Spanish, onArgs.hebrewC1Portuguese],
      Object.values(T.hebrewCardFor(null, false, { ...base, hebrewAdvanced: false } as AppSettings, 'he').flags)
    ],
    [[false, false, false, false], [true, true, true, true], [false, false, false, false]]
  )
}

